export const rows: Record<string, readonly string[]> = {
  "lt_expenses_title": ["Money out — expenses guided tour", "Wydatki — wycieczka z przewodnikiem", "Cheltuieli — tur ghidat", "اخراجات — گائیڈڈ ٹور", "ਖਰਚੇ — ਗਾਈਡਡ ਟੂਰ", "খরচ — গাইডেড ট্যুর", "المصروفات — جولة إرشادية", "Despesas — visita guiada", "Gastos — recorrido guiado", "Dépenses — visite guidée", "Arian allan — taith dywys treuliau"],
  "lt_expenses_intro": ["This is your spending hub — pop in everything the business pays out, mark each one as owed or gone, and watch it all roll up into tidy monthly and yearly totals.", "To Twoje centrum wydatków — wpisuj wszystko, co firma płaci, oznacz każdą pozycję jako do zapłaty lub zapłaconą i patrz, jak sumuje się w przejrzyste zestawienia miesięczne i roczne.", "Acesta este centrul tău de cheltuieli — introdu tot ce plătește afacerea, marchează fiecare sumă ca datorată sau plătită și urmărește cum se adună în totaluri lunare și anuale ordonate.", "یہ آپ کے اخراجات کا مرکز ہے — کاروبار جو کچھ بھی ادا کرتا ہے درج کریں، ہر خرچ کو واجب الادا یا ادا شدہ کے طور پر نشان زد کریں، اور دیکھیں کہ یہ سب صاف ستھرے ماہانہ اور سالانہ مجموعوں میں کیسے جمع ہو جاتا ہے۔", "ਇਹ ਤੁਹਾਡਾ ਖਰਚਿਆਂ ਦਾ ਕੇਂਦਰ ਹੈ — ਕਾਰੋਬਾਰ ਜੋ ਵੀ ਅਦਾ ਕਰਦਾ ਹੈ ਉਹ ਦਰਜ ਕਰੋ, ਹਰ ਖਰਚੇ ਨੂੰ ਬਕਾਇਆ ਜਾਂ ਅਦਾ ਹੋਇਆ ਦੱਸੋ, ਅਤੇ ਦੇਖੋ ਕਿ ਸਭ ਕੁਝ ਸਾਫ਼-ਸੁਥਰੇ ਮਹੀਨਾਵਾਰ ਅਤੇ ਸਾਲਾਨਾ ਕੁੱਲ ਵਿੱਚ ਕਿਵੇਂ ਜੁੜਦਾ ਹੈ।", "এটি আপনার খরচের কেন্দ্র — ব্যবসা যা কিছু পরিশোধ করে সব লিখে রাখুন, প্রতিটি খরচ বকেয়া বা পরিশোধিত হিসেবে চিহ্নিত করুন, আর দেখুন সব কিছু গোছানো মাসিক ও বার্ষিক মোটে কীভাবে জুড়ে যাচ্ছে।", "هذا هو مركز مصروفاتك — سجّل كل ما يدفعه نشاطك، وحدّد كل بند على أنه مستحق أو مدفوع، وشاهد كل شيء يتجمع في إجماليات شهرية وسنوية مرتبة.", "Este é o seu centro de despesas — registe tudo o que o negócio paga, marque cada uma como por pagar ou paga, e veja tudo somar-se em totais mensais e anuais bem organizados.", "Este es tu centro de gastos: anota todo lo que paga el negocio, marca cada uno como pendiente o pagado y mira cómo se suma todo en totales mensuales y anuales bien ordenados.", "Voici votre centre de dépenses : saisissez tout ce que l’activité paie, marquez chaque dépense comme due ou réglée, et regardez le tout s’additionner en totaux mensuels et annuels bien rangés.", "Dyma’ch canolfan gwario — rhowch bopeth y mae’r busnes yn ei dalu, marciwch bob un fel dyledus neu wedi’i dalu, a gwyliwch y cyfan yn cronni’n gyfansymiau misol a blynyddol destlus."],
  "lt_expenses_done": ["Keep your spending logged and your receipts attached, and come tax time it is all sitting neat and ready for the accountant.", "Zapisuj wydatki i dołączaj paragony, a w czasie rozliczeń wszystko będzie czekać w porządku dla księgowego.", "Ține evidența cheltuielilor și atașează chitanțele, iar când vine vremea impozitelor totul va fi ordonat și gata pentru contabil.", "اپنے اخراجات درج کرتے رہیں اور رسیدیں منسلک کریں، اور ٹیکس کے وقت سب کچھ صاف ستھرا اکاؤنٹنٹ کے لیے تیار ملے گا۔", "ਆਪਣੇ ਖਰਚੇ ਦਰਜ ਕਰਦੇ ਰਹੋ ਅਤੇ ਰਸੀਦਾਂ ਜੋੜੋ, ਤੇ ਟੈਕਸ ਦੇ ਸਮੇਂ ਸਭ ਕੁਝ ਸਾਫ਼-ਸੁਥਰਾ ਅਕਾਊਂਟੈਂਟ ਲਈ ਤਿਆਰ ਮਿਲੇਗਾ।", "খরচ লিখে রাখুন আর রসিদ জুড়ে দিন, তাহলে কর জমার সময় সবকিছু গোছানো অবস্থায় হিসাবরক্ষকের জন্য তৈরি থাকবে।", "حافظ على تسجيل مصروفاتك وإرفاق إيصالاتك، وحين يحين موعد الضرائب سيكون كل شيء مرتبًا وجاهزًا للمحاسب.", "Mantenha as despesas registadas e os recibos anexados e, na altura dos impostos, tudo estará arrumado e pronto para o contabilista.", "Mantén tus gastos registrados y los recibos adjuntos, y a la hora de los impuestos todo estará ordenado y listo para el contable.", "Gardez vos dépenses consignées et vos reçus joints, et au moment des impôts tout sera rangé et prêt pour le comptable.", "Cadwch eich gwariant wedi’i gofnodi a’ch derbynebau ynghlwm, ac erbyn amser treth bydd y cyfan yn daclus ac yn barod i’r cyfrifydd."],
  "lt_expenses_s0": ["Everything you spend rolls up into three big numbers up top, and the Cash-or-Accrual toggle quietly decides whether money you still owe is counted yet. Flip on Purchase Orders in Setup and a Purchase orders tab joins the page too.", "Wszystko, co wydajesz, sumuje się w trzy duże liczby na górze, a przełącznik Gotówka lub Memoriałowa cicho decyduje, czy kwoty, które jeszcze jesteś winien, są już liczone. Włącz zamówienia zakupu w Konfiguracji, a na stronie pojawi się też zakładka Zamówienia zakupu.", "Tot ce cheltuiești se adună în trei cifre mari sus, iar comutatorul Numerar sau Angajamente hotărăște discret dacă sumele pe care le mai datorezi sunt deja numărate. Activează Comenzile de achiziție în Configurare și pe pagină apare și fila Comenzi de achiziție.", "آپ کا سارا خرچ اوپر تین بڑے اعداد میں جمع ہو جاتا ہے، اور کیش یا ایکروئل کا سوئچ خاموشی سے طے کرتا ہے کہ جو رقم آپ کو ابھی دینی ہے وہ شمار ہو یا نہیں۔ سیٹ اپ میں پرچیز آرڈرز آن کریں تو صفحے پر پرچیز آرڈرز کا ٹیب بھی آ جاتا ہے۔", "ਤੁਹਾਡਾ ਸਾਰਾ ਖਰਚਾ ਉੱਪਰ ਤਿੰਨ ਵੱਡੇ ਅੰਕਾਂ ਵਿੱਚ ਜੁੜਦਾ ਹੈ, ਅਤੇ ਕੈਸ਼ ਜਾਂ ਐਕਰੂਅਲ ਵਾਲਾ ਸਵਿੱਚ ਚੁੱਪਚਾਪ ਤੈਅ ਕਰਦਾ ਹੈ ਕਿ ਜੋ ਰਕਮ ਤੁਸੀਂ ਅਜੇ ਦੇਣੀ ਹੈ ਉਹ ਗਿਣੀ ਜਾਵੇ ਜਾਂ ਨਹੀਂ। ਸੈੱਟਅੱਪ ਵਿੱਚ ਖਰੀਦ ਆਰਡਰ ਚਾਲੂ ਕਰੋ ਤਾਂ ਪੰਨੇ ਉੱਤੇ ਖਰੀਦ ਆਰਡਰ ਟੈਬ ਵੀ ਜੁੜ ਜਾਂਦੀ ਹੈ।", "আপনার সব খরচ উপরে তিনটি বড় সংখ্যায় জমা হয়, আর ক্যাশ বা অ্যাক্রুয়াল টগল চুপচাপ ঠিক করে দেয় যে এখনও বকেয়া টাকা গণনায় ধরা হবে কি না। সেটআপে পারচেজ অর্ডার চালু করলে পাতায় পারচেজ অর্ডার ট্যাবও যোগ হয়।", "كل ما تنفقه يتجمع في ثلاثة أرقام كبيرة في الأعلى، ويحدد مفتاح النقدي أو الاستحقاق بهدوء ما إذا كانت المبالغ التي لا تزال عليك محسوبة بعد أم لا. فعّل أوامر الشراء من الإعداد وستنضم إلى الصفحة علامة تبويب أوامر الشراء أيضًا.", "Tudo o que gasta soma-se em três números grandes no topo, e o interruptor Caixa ou Acréscimo decide discretamente se o dinheiro que ainda deve já é contado. Ative as Ordens de compra na Configuração e um separador Ordens de compra junta-se também à página.", "Todo lo que gastas se suma en tres números grandes arriba, y el selector Caja o Devengo decide discretamente si el dinero que aún debes ya se cuenta. Activa los Pedidos de compra en Configuración y se añade también una pestaña Pedidos de compra a la página.", "Tout ce que vous dépensez se regroupe en trois grands chiffres en haut, et le bouton Caisse ou Engagement décide discrètement si l’argent que vous devez encore est déjà compté. Activez les Bons de commande dans Configuration et un onglet Bons de commande s’ajoute aussi à la page.", "Mae popeth rydych chi’n ei wario’n cronni’n dri rhif mawr ar y brig, ac mae’r togl Arian parod neu Croniadol yn penderfynu’n dawel a yw arian sy’n dal yn ddyledus wedi’i gyfrif eto. Trowch Archebion prynu ymlaen yn y Gosodiad ac mae tab Archebion prynu yn ymuno â’r dudalen hefyd."],
  "lt_expenses_s1": ["The Overview tab is your quick health-check — the last six months at a glance, where the money is going, and which suppliers cost you most, whether it is holiday camps, weekly clubs or after-school classes.", "Zakładka Przegląd to szybka kontrola kondycji — ostatnie sześć miesięcy w pigułce, na co idą pieniądze i którzy dostawcy kosztują najwięcej, czy to obozy wakacyjne, cotygodniowe zajęcia, czy zajęcia po szkole.", "Fila Prezentare generală este o verificare rapidă — ultimele șase luni dintr-o privire, unde se duc banii și ce furnizori te costă cel mai mult, fie că e vorba de tabere de vacanță, cluburi săptămânale sau activități după școală.", "اوورویو ٹیب آپ کا فوری صحت کا جائزہ ہے — پچھلے چھ مہینے ایک نظر میں، پیسہ کہاں جا رہا ہے، اور کون سے سپلائر آپ کو سب سے مہنگے پڑتے ہیں، چاہے وہ چھٹیوں کے کیمپ ہوں، ہفتہ وار کلب ہوں یا سکول کے بعد کی کلاسیں۔", "ਓਵਰਵਿਊ ਟੈਬ ਇੱਕ ਤੇਜ਼ ਸਿਹਤ-ਜਾਂਚ ਹੈ — ਪਿਛਲੇ ਛੇ ਮਹੀਨੇ ਇੱਕ ਨਜ਼ਰ ਵਿੱਚ, ਪੈਸਾ ਕਿੱਥੇ ਜਾ ਰਿਹਾ ਹੈ, ਅਤੇ ਕਿਹੜੇ ਸਪਲਾਇਰ ਸਭ ਤੋਂ ਮਹਿੰਗੇ ਪੈਂਦੇ ਹਨ, ਭਾਵੇਂ ਛੁੱਟੀਆਂ ਦੇ ਕੈਂਪ ਹੋਣ, ਹਫ਼ਤਾਵਾਰੀ ਕਲੱਬ ਜਾਂ ਸਕੂਲ ਤੋਂ ਬਾਅਦ ਦੀਆਂ ਕਲਾਸਾਂ।", "ওভারভিউ ট্যাব হলো দ্রুত স্বাস্থ্য-পরীক্ষা — গত ছয় মাস এক নজরে, টাকা কোথায় যাচ্ছে, আর কোন সরবরাহকারী সবচেয়ে বেশি খরচ করাচ্ছে, তা ছুটির ক্যাম্প, সাপ্তাহিক ক্লাব বা স্কুলের পরের ক্লাস যা-ই হোক।", "تبويب النظرة العامة هو فحص سريع لصحة أموالك — آخر ستة أشهر في لمحة، وأين يذهب المال، وأي الموردين يكلفونك أكثر، سواء كانت مخيمات العطلات أو النوادي الأسبوعية أو حصص ما بعد المدرسة.", "O separador Visão geral é um controlo rápido da saúde financeira — os últimos seis meses num relance, para onde vai o dinheiro e que fornecedores lhe custam mais, sejam campos de férias, clubes semanais ou aulas depois da escola.", "La pestaña Resumen es un chequeo rápido: los últimos seis meses de un vistazo, adónde va el dinero y qué proveedores te cuestan más, ya sean campamentos de vacaciones, clubes semanales o clases extraescolares.", "L’onglet Aperçu est un bilan de santé rapide : les six derniers mois en un coup d’œil, où va l’argent et quels fournisseurs vous coûtent le plus, que ce soit les camps de vacances, les clubs hebdomadaires ou les cours après l’école.", "Mae’r tab Trosolwg yn wiriad iechyd cyflym — y chwe mis diwethaf ar un olwg, i ble mae’r arian yn mynd, a pha gyflenwyr sy’n costio fwyaf i chi, boed yn wersylloedd gwyliau, yn glybiau wythnosol neu’n ddosbarthiadau ar ôl ysgol."],
  "lt_expenses_s2": ["Come tax time every spend wants a receipt behind it. The Receipts tab shows your coverage at a glance and lets you fill the gaps with a single tap.", "W czasie rozliczeń za każdym wydatkiem powinien stać paragon. Zakładka Paragony pokazuje, ile masz już pokrytych, i pozwala uzupełnić braki jednym dotknięciem.", "La vremea impozitelor fiecare cheltuială are nevoie de o chitanță. Fila Chitanțe îți arată cât de acoperit ești dintr-o privire și te lasă să completezi lipsurile dintr-o singură atingere.", "ٹیکس کے وقت ہر خرچ کے پیچھے ایک رسید ہونی چاہیے۔ رسیدوں کا ٹیب آپ کی کوریج ایک نظر میں دکھاتا ہے اور ایک ٹیپ سے کمی پوری کرنے دیتا ہے۔", "ਟੈਕਸ ਦੇ ਸਮੇਂ ਹਰ ਖਰਚੇ ਪਿੱਛੇ ਇੱਕ ਰਸੀਦ ਹੋਣੀ ਚਾਹੀਦੀ ਹੈ। ਰਸੀਦਾਂ ਟੈਬ ਤੁਹਾਡੀ ਕਵਰੇਜ ਇੱਕ ਨਜ਼ਰ ਵਿੱਚ ਦਿਖਾਉਂਦੀ ਹੈ ਅਤੇ ਇੱਕ ਟੈਪ ਨਾਲ ਕਮੀਆਂ ਪੂਰੀਆਂ ਕਰਨ ਦਿੰਦੀ ਹੈ।", "কর জমার সময় প্রতিটি খরচের পেছনে একটি রসিদ থাকা দরকার। রসিদ ট্যাবে এক নজরে দেখা যায় কতটা কভার হয়েছে, আর এক ট্যাপেই ফাঁক পূরণ করা যায়।", "عند موعد الضرائب يحتاج كل مصروف إلى إيصال يسنده. يعرض تبويب الإيصالات مدى تغطيتك في لمحة ويتيح لك سد الثغرات بنقرة واحدة.", "Na altura dos impostos, cada despesa precisa de um recibo. O separador Recibos mostra a sua cobertura num relance e deixa-o preencher as lacunas com um único toque.", "A la hora de los impuestos, cada gasto necesita un recibo. La pestaña Recibos muestra tu cobertura de un vistazo y te deja rellenar los huecos con un solo toque.", "Au moment des impôts, chaque dépense doit avoir son reçu. L’onglet Reçus montre votre couverture d’un coup d’œil et vous laisse combler les manques d’un seul geste.", "Erbyn amser treth mae angen derbynneb y tu ôl i bob gwariant. Mae’r tab Derbynebau yn dangos eich cwmpas ar un olwg ac yn gadael i chi lenwi’r bylchau gydag un tap."],
  "lt_expenses_s3": ["To add one, you press Log expense, and this form opens.", "Aby dodać wydatek, naciskasz Zapisz wydatek i otwiera się ten formularz.", "Ca să adaugi una, apeși Înregistrează cheltuiala și se deschide acest formular.", "نیا خرچ شامل کرنے کے لیے آپ خرچ درج کریں دباتے ہیں، اور یہ فارم کھل جاتا ہے۔", "ਇੱਕ ਜੋੜਨ ਲਈ ਤੁਸੀਂ ਖਰਚਾ ਦਰਜ ਕਰੋ ਦਬਾਉਂਦੇ ਹੋ, ਅਤੇ ਇਹ ਫਾਰਮ ਖੁੱਲ੍ਹ ਜਾਂਦਾ ਹੈ।", "একটি যোগ করতে আপনি খরচ লিখুন চাপেন, আর এই ফর্মটি খুলে যায়।", "لإضافة مصروف تضغط على تسجيل مصروف فيُفتح هذا النموذج.", "Para adicionar uma, prime Registar despesa e este formulário abre-se.", "Para añadir uno, pulsas Registrar gasto y se abre este formulario.", "Pour en ajouter une, vous appuyez sur Enregistrer une dépense et ce formulaire s’ouvre.", "I ychwanegu un, pwyswch Logio gwariant ac mae’r ffurflen hon yn agor."],
  "lt_expenses_s4": ["Start with the date and a category — here it is the fifth of August, and venue hire for a holiday camp. Not listed? The New button adds a fresh category without leaving the form.", "Zacznij od daty i kategorii — tu jest piąty sierpnia i wynajem obiektu na obóz wakacyjny. Nie ma jej na liście? Przycisk Nowa dodaje kategorię bez wychodzenia z formularza.", "Începe cu data și o categorie — aici este cinci august și închirierea unei săli pentru o tabără de vacanță. Nu e în listă? Butonul Nou adaugă o categorie nouă fără să părăsești formularul.", "تاریخ اور زمرے سے شروع کریں — یہاں پانچ اگست ہے اور چھٹیوں کے کیمپ کے لیے مقام کا کرایہ۔ فہرست میں نہیں ہے؟ نیا بٹن فارم چھوڑے بغیر نیا زمرہ بنا دیتا ہے۔", "ਤਾਰੀਖ਼ ਅਤੇ ਸ਼੍ਰੇਣੀ ਨਾਲ ਸ਼ੁਰੂ ਕਰੋ — ਇੱਥੇ ਪੰਜ ਅਗਸਤ ਹੈ ਅਤੇ ਛੁੱਟੀਆਂ ਦੇ ਕੈਂਪ ਲਈ ਥਾਂ ਦਾ ਕਿਰਾਇਆ। ਸੂਚੀ ਵਿੱਚ ਨਹੀਂ ਹੈ? ਨਵਾਂ ਬਟਨ ਫਾਰਮ ਛੱਡੇ ਬਿਨਾਂ ਨਵੀਂ ਸ਼੍ਰੇਣੀ ਜੋੜ ਦਿੰਦਾ ਹੈ।", "তারিখ আর একটি বিভাগ দিয়ে শুরু করুন — এখানে পাঁচই আগস্ট, আর ছুটির ক্যাম্পের জন্য ভেন্যু ভাড়া। তালিকায় নেই? নতুন বোতাম ফর্ম না ছেড়েই নতুন বিভাগ যোগ করে।", "ابدأ بالتاريخ والفئة — هنا الخامس من أغسطس وإيجار مكان لمخيم العطلة. ليست في القائمة؟ زر جديد يضيف فئة جديدة دون مغادرة النموذج.", "Comece pela data e por uma categoria — aqui é cinco de agosto e o aluguer de um espaço para um campo de férias. Não está na lista? O botão Nova acrescenta uma categoria nova sem sair do formulário.", "Empieza por la fecha y una categoría: aquí es el cinco de agosto y el alquiler de un local para un campamento de vacaciones. ¿No está en la lista? El botón Nueva añade una categoría nueva sin salir del formulario.", "Commencez par la date et une catégorie : ici, le cinq août et la location d’un lieu pour un camp de vacances. Elle n’est pas listée ? Le bouton Nouvelle ajoute une catégorie sans quitter le formulaire.", "Dechreuwch gyda’r dyddiad a chategori — yma mae’n bumed o Awst, a llogi lleoliad ar gyfer gwersyll gwyliau. Ddim ar y rhestr? Mae’r botwm Newydd yn ychwanegu categori newydd heb adael y ffurflen."],
  "lt_expenses_s5": ["Then the amount, who you paid, and a quick note — a hundred and eighty pounds to Riverside Sports Hall for week three of the summer multi-sports camp.", "Potem kwota, komu zapłaciłeś i krótka notatka — sto osiemdziesiąt funtów dla Riverside Sports Hall za trzeci tydzień letniego obozu wielosportowego.", "Apoi suma, cui ai plătit și o scurtă notă — o sută optzeci de lire către Riverside Sports Hall pentru săptămâna a treia a taberei multisport de vară.", "پھر رقم، آپ نے کسے ادا کیا، اور ایک مختصر نوٹ — گرمیوں کے ملٹی سپورٹس کیمپ کے تیسرے ہفتے کے لیے ریور سائیڈ سپورٹس ہال کو ایک سو اسی پاؤنڈ۔", "ਫਿਰ ਰਕਮ, ਤੁਸੀਂ ਕਿਸ ਨੂੰ ਅਦਾ ਕੀਤੀ, ਅਤੇ ਇੱਕ ਛੋਟਾ ਨੋਟ — ਗਰਮੀਆਂ ਦੇ ਮਲਟੀ-ਸਪੋਰਟਸ ਕੈਂਪ ਦੇ ਤੀਜੇ ਹਫ਼ਤੇ ਲਈ ਰਿਵਰਸਾਈਡ ਸਪੋਰਟਸ ਹਾਲ ਨੂੰ ਇੱਕ ਸੌ ਅੱਸੀ ਪੌਂਡ।", "তারপর পরিমাণ, কাকে দিয়েছেন, আর একটি ছোট নোট — গ্রীষ্মকালীন মাল্টি-স্পোর্টস ক্যাম্পের তৃতীয় সপ্তাহের জন্য রিভারসাইড স্পোর্টস হলকে একশো আশি পাউন্ড।", "ثم المبلغ ولمن دفعت وملاحظة سريعة — مئة وثمانون جنيهًا إسترلينيًا لقاعة ريفرسايد الرياضية عن الأسبوع الثالث من مخيم الصيف متعدد الرياضات.", "Depois o valor, a quem pagou e uma nota rápida — cento e oitenta libras ao Riverside Sports Hall pela terceira semana do campo multidesportos de verão.", "Luego el importe, a quién pagaste y una nota rápida: ciento ochenta libras al Riverside Sports Hall por la tercera semana del campamento multideporte de verano.", "Puis le montant, à qui vous avez payé et une note rapide : cent quatre-vingts livres au Riverside Sports Hall pour la troisième semaine du camp multisports d’été.", "Yna’r swm, pwy a dalwyd, a nodyn cyflym — cant wyth deg punt i Riverside Sports Hall ar gyfer wythnos tri’r gwersyll aml-chwaraeon haf."],
  "lt_expenses_s6": ["Mark it Paid if the money has gone, or Pending if you still owe it — and for a regular cost like your weekly club hall or monthly insurance, set a repeat so the whole run is logged for you.", "Oznacz jako Zapłacone, jeśli pieniądze już poszły, albo Oczekujące, jeśli jeszcze je jesteś winien — a przy stałym koszcie, jak cotygodniowa sala czy miesięczne ubezpieczenie, ustaw powtarzanie, by cała seria zapisała się sama.", "Marchează-o Plătită dacă banii au plecat sau În așteptare dacă încă îi datorezi — iar pentru un cost regulat, ca sala săptămânală sau asigurarea lunară, setează o repetare ca întreaga serie să fie înregistrată pentru tine.", "اگر پیسے جا چکے ہیں تو ادا شدہ نشان زد کریں، یا اگر ابھی دینے ہیں تو زیر التوا — اور کسی باقاعدہ خرچ، جیسے ہفتہ وار کلب ہال یا ماہانہ انشورنس، کے لیے دہرائی سیٹ کریں تاکہ پوری سیریز خود درج ہو جائے۔", "ਜੇ ਪੈਸੇ ਜਾ ਚੁੱਕੇ ਹਨ ਤਾਂ ਅਦਾ ਹੋਇਆ ਚੁਣੋ, ਜਾਂ ਜੇ ਅਜੇ ਦੇਣੇ ਹਨ ਤਾਂ ਬਕਾਇਆ — ਅਤੇ ਨਿਯਮਿਤ ਖਰਚੇ, ਜਿਵੇਂ ਹਫ਼ਤਾਵਾਰੀ ਕਲੱਬ ਹਾਲ ਜਾਂ ਮਹੀਨਾਵਾਰ ਬੀਮਾ, ਲਈ ਦੁਹਰਾਓ ਸੈੱਟ ਕਰੋ ਤਾਂ ਜੋ ਪੂਰੀ ਲੜੀ ਆਪਣੇ ਆਪ ਦਰਜ ਹੋ ਜਾਵੇ।", "টাকা চলে গেলে পরিশোধিত চিহ্নিত করুন, আর এখনও দিতে হলে মুলতুবি — আর নিয়মিত খরচ, যেমন সাপ্তাহিক ক্লাব হল বা মাসিক বিমার জন্য পুনরাবৃত্তি ঠিক করুন, যাতে পুরো সিরিজ আপনার হয়ে লেখা হয়ে যায়।", "حدّده مدفوعًا إن كان المال قد خرج، أو معلقًا إن كنت لا تزال مدينًا به — ولتكلفة منتظمة مثل قاعة النادي الأسبوعية أو التأمين الشهري، اضبط التكرار ليُسجَّل المسلسل كله عنك.", "Marque como Paga se o dinheiro já saiu, ou Pendente se ainda o deve — e para um custo regular, como o espaço do clube semanal ou o seguro mensal, defina uma repetição para que toda a série fique registada por si.", "Márcalo como Pagado si el dinero ya salió, o Pendiente si aún lo debes; y para un coste regular, como el local del club semanal o el seguro mensual, configura una repetición para que toda la serie se registre sola.", "Marquez-la Payée si l’argent est parti, ou En attente si vous la devez encore — et pour un coût régulier, comme la salle du club hebdomadaire ou l’assurance mensuelle, réglez une répétition pour que toute la série soit saisie à votre place.", "Marciwch fel Wedi’i dalu os yw’r arian wedi mynd, neu Yn aros os ydych yn dal i’w ddyled — ac ar gyfer cost reolaidd, fel neuadd y clwb wythnosol neu’r yswiriant misol, gosodwch ailadrodd fel bod y gyfres gyfan yn cael ei logio i chi."],
  "lt_expenses_s7": ["Press Log expense at the bottom and it lands in your ledger, totalled and categorised. Pick a repeat first and this button flips to Create series, spinning up every entry in one go.", "Naciśnij Zapisz wydatek na dole, a trafi do księgi — zsumowany i skategoryzowany. Jeśli najpierw wybierzesz powtarzanie, przycisk zmieni się w Utwórz serię i doda wszystkie wpisy naraz.", "Apasă Înregistrează cheltuiala jos și ajunge în registru, totalizată și categorisită. Dacă alegi mai întâi o repetare, butonul devine Creează serie și generează toate înregistrările odată.", "نیچے خرچ درج کریں دبائیں اور یہ آپ کے کھاتے میں مجموعے اور زمرے کے ساتھ پہنچ جاتا ہے۔ پہلے دہرائی چنیں تو یہ بٹن سیریز بنائیں میں بدل جاتا ہے اور تمام اندراجات ایک ساتھ بنا دیتا ہے۔", "ਹੇਠਾਂ ਖਰਚਾ ਦਰਜ ਕਰੋ ਦਬਾਓ ਅਤੇ ਇਹ ਤੁਹਾਡੇ ਖਾਤੇ ਵਿੱਚ ਕੁੱਲ ਅਤੇ ਸ਼੍ਰੇਣੀ ਸਮੇਤ ਆ ਜਾਂਦਾ ਹੈ। ਪਹਿਲਾਂ ਦੁਹਰਾਓ ਚੁਣੋ ਤਾਂ ਇਹ ਬਟਨ ਲੜੀ ਬਣਾਓ ਬਣ ਜਾਂਦਾ ਹੈ ਅਤੇ ਸਾਰੇ ਇੰਦਰਾਜ਼ ਇੱਕੋ ਵਾਰ ਵਿੱਚ ਬਣਾ ਦਿੰਦਾ ਹੈ।", "নিচে খরচ লিখুন চাপুন, আর এটি আপনার খতিয়ানে মোট ও বিভাগসহ চলে যায়। আগে পুনরাবৃত্তি বেছে নিলে এই বোতাম সিরিজ তৈরি করুনে বদলে যায় এবং সব এন্ট্রি এক সঙ্গে তৈরি করে।", "اضغط تسجيل مصروف في الأسفل فيصل إلى دفتر حساباتك مجمّعًا ومصنفًا. اختر تكرارًا أولًا ويتحول هذا الزر إلى إنشاء سلسلة فيُنشئ كل الإدخالات دفعة واحدة.", "Prima Registar despesa em baixo e fica no seu livro, somada e categorizada. Escolha primeiro uma repetição e este botão passa a Criar série, gerando todas as entradas de uma vez.", "Pulsa Registrar gasto abajo y pasa a tu libro, sumado y categorizado. Si eliges antes una repetición, este botón pasa a Crear serie y genera todas las entradas de una vez.", "Appuyez sur Enregistrer une dépense en bas et elle arrive dans votre registre, totalisée et catégorisée. Choisissez d’abord une répétition et ce bouton devient Créer la série, qui génère toutes les entrées d’un coup.", "Pwyswch Logio gwariant ar y gwaelod ac mae’n glanio yn eich cyfriflyfr, wedi’i gyfrif a’i gategoreiddio. Dewiswch ailadrodd yn gyntaf ac mae’r botwm hwn yn troi’n Creu cyfres, gan greu pob cofnod ar unwaith."],
  "lt_purchasing_title": ["Money in", "Wpływy", "Încasări", "آمدنی", "ਆਮਦਨ", "আয়", "الإيرادات", "Receitas", "Ingresos", "Recettes", "Arian i mewn"],
  "lt_purchasing_intro": ["This is your one takings hub, love — every paid booking, paid invoice and bit of cash you log all roll up into a single money-in figure, then split neatly into an Income side and an Invoices side. Let me show you round, then log a bit of income together.", "To Twoje jedno centrum wpływów — każda opłacona rezerwacja, opłacona faktura i gotówka, którą zapiszesz, sumują się w jedną kwotę wpływów, podzieloną na stronę Przychodów i stronę Faktur. Oprowadzę Cię, a potem razem zapiszemy trochę przychodu.", "Acesta este centrul tău unic de încasări — fiecare rezervare plătită, factură achitată și bănuț în numerar pe care îl înregistrezi se adună într-o singură sumă de încasări, apoi împărțită frumos în partea de Venituri și partea de Facturi. Te plimb puțin prin pagină, apoi înregistrăm împreună un venit.", "یہ آپ کی آمدنی کا واحد مرکز ہے — ہر ادا شدہ بکنگ، ادا شدہ انوائس اور آپ کی درج کی ہوئی نقدی ایک ہی آمدنی کے عدد میں جمع ہوتی ہے، جو پھر آمدن اور انوائسز کے دو حصوں میں بٹ جاتا ہے۔ پہلے میں آپ کو گھما کر دکھاتا ہوں، پھر ہم مل کر کچھ آمدن درج کریں گے۔", "ਇਹ ਤੁਹਾਡਾ ਆਮਦਨ ਦਾ ਇੱਕੋ ਕੇਂਦਰ ਹੈ — ਹਰ ਅਦਾ ਹੋਈ ਬੁਕਿੰਗ, ਅਦਾ ਹੋਇਆ ਇਨਵੌਇਸ ਅਤੇ ਤੁਹਾਡੀ ਦਰਜ ਕੀਤੀ ਨਕਦੀ ਇੱਕੋ ਆਮਦਨ ਅੰਕ ਵਿੱਚ ਜੁੜਦੀ ਹੈ, ਜੋ ਫਿਰ ਆਮਦਨ ਅਤੇ ਇਨਵੌਇਸ ਦੇ ਦੋ ਪਾਸਿਆਂ ਵਿੱਚ ਵੰਡਿਆ ਜਾਂਦਾ ਹੈ। ਪਹਿਲਾਂ ਮੈਂ ਤੁਹਾਨੂੰ ਘੁੰਮਾ ਕੇ ਦਿਖਾਉਂਦਾ/ਦਿਖਾਉਂਦੀ ਹਾਂ, ਫਿਰ ਅਸੀਂ ਮਿਲ ਕੇ ਕੁਝ ਆਮਦਨ ਦਰਜ ਕਰਾਂਗੇ।", "এটি আপনার আয়ের একমাত্র কেন্দ্র — প্রতিটি পরিশোধিত বুকিং, পরিশোধিত ইনভয়েস আর আপনার লেখা নগদ টাকা মিলে একটিই আয়ের অঙ্কে জমা হয়, তারপর আয় ও ইনভয়েস — দুই পাশে গোছানোভাবে ভাগ হয়। আগে আপনাকে ঘুরিয়ে দেখাই, তারপর একসঙ্গে কিছু আয় লিখব।", "هذا هو مركز إيراداتك الوحيد — كل حجز مدفوع وكل فاتورة مسددة وكل مبلغ نقدي تسجّله يجتمع في رقم إيرادات واحد، ثم يتوزع بانتظام بين جانب الدخل وجانب الفواتير. دعني أريك المكان أولًا، ثم نسجّل معًا بعض الدخل.", "Este é o seu centro único de receitas — cada reserva paga, cada fatura paga e cada dinheiro em numerário que registar somam-se num único valor de receitas, dividido depois em Rendimentos e Faturas. Mostro-lhe tudo e depois registamos um rendimento em conjunto.", "Este es tu centro único de ingresos: cada reserva pagada, cada factura pagada y cada efectivo que registres se suman en una única cifra de ingresos, que luego se divide en Ingresos y Facturas. Te lo enseño y luego registramos un ingreso juntos.", "Voici votre centre unique de recettes : chaque réservation payée, chaque facture réglée et chaque espèce saisie s’additionnent en un seul chiffre, ensuite réparti entre Revenus et Factures. Je vous fais le tour, puis nous saisissons un revenu ensemble.", "Dyma’ch canolfan arian i mewn — mae pob archeb a dalwyd, pob anfoneb a dalwyd a phob darn o arian parod y byddwch yn ei logio’n cronni’n un ffigur, sydd wedyn yn cael ei rannu’n daclus yn ochr Incwm ac ochr Anfonebau. Gadewch i mi ddangos y lle, yna byddwn yn logio ychydig o incwm gyda’n gilydd."],
  "lt_purchasing_done": ["And that's it — bookings and invoices land on their own, you pop the rest in by hand, and it all tallies up at the top so you always know exactly what's come in.", "I to wszystko — rezerwacje i faktury trafiają tu same, resztę wpisujesz ręcznie, a na górze wszystko się sumuje, więc zawsze wiesz, ile dokładnie wpłynęło.", "Gata — rezervările și facturile ajung singure, restul le introduci manual, iar totul se adună sus, așa că știi mereu exact cât a intrat.", "بس یہی ہے — بکنگز اور انوائسز خود آ جاتی ہیں، باقی آپ ہاتھ سے درج کرتے ہیں، اور سب کچھ اوپر جمع ہو جاتا ہے، تو آپ کو ہمیشہ پتا ہوتا ہے کہ کتنی رقم آئی ہے۔", "ਬੱਸ ਇਹੀ ਹੈ — ਬੁਕਿੰਗਾਂ ਅਤੇ ਇਨਵੌਇਸ ਆਪਣੇ ਆਪ ਆ ਜਾਂਦੇ ਹਨ, ਬਾਕੀ ਤੁਸੀਂ ਹੱਥੀਂ ਪਾਉਂਦੇ ਹੋ, ਅਤੇ ਸਭ ਕੁਝ ਉੱਪਰ ਜੁੜ ਜਾਂਦਾ ਹੈ, ਇਸ ਲਈ ਤੁਹਾਨੂੰ ਹਮੇਸ਼ਾ ਪਤਾ ਰਹਿੰਦਾ ਹੈ ਕਿ ਕਿੰਨਾ ਆਇਆ।", "ব্যস, এটুকুই — বুকিং আর ইনভয়েস নিজে থেকেই আসে, বাকিটা হাতে লেখেন, আর সব কিছু উপরে যোগ হয়ে যায়, তাই আপনি সবসময় জানেন ঠিক কত এসেছে।", "وهذا كل شيء — الحجوزات والفواتير تصل من تلقاء نفسها، وتضيف الباقي يدويًا، ويُجمع كل شيء في الأعلى فتعرف دائمًا بالضبط كم دخل.", "E é isto — as reservas e as faturas chegam sozinhas, o resto regista à mão, e tudo soma no topo para saber sempre exatamente o que entrou.", "Y ya está: las reservas y las facturas llegan solas, el resto lo añades a mano, y todo se suma arriba para que siempre sepas exactamente lo que ha entrado.", "Et voilà : les réservations et les factures arrivent toutes seules, vous ajoutez le reste à la main, et tout se cumule en haut pour que vous sachiez toujours ce qui est entré.", "A dyna ni — mae archebion ac anfonebau’n glanio ar eu pen eu hunain, rydych chi’n rhoi’r gweddill i mewn â llaw, ac mae’r cyfan yn cronni ar y brig fel eich bod bob amser yn gwybod yn union beth sydd wedi dod i mewn."],
  "lt_purchasing_s0": ["Right at the top, your whole takings at a glance — what's come in this month, what's in for the year, and what's still awaiting payment.", "Na samej górze masz wszystkie wpływy w skrócie — ile wpłynęło w tym miesiącu, ile w tym roku i co wciąż czeka na płatność.", "Chiar sus ai toate încasările dintr-o privire — cât a intrat luna aceasta, cât în acest an și ce mai așteaptă plata.", "سب سے اوپر آپ کی ساری آمدنی ایک نظر میں ہے — اس مہینے کتنی آئی، اس سال کتنی آئی، اور کیا ابھی ادائیگی کا منتظر ہے۔", "ਬਿਲਕੁਲ ਉੱਪਰ ਤੁਹਾਡੀ ਸਾਰੀ ਆਮਦਨ ਇੱਕ ਨਜ਼ਰ ਵਿੱਚ ਹੈ — ਇਸ ਮਹੀਨੇ ਕਿੰਨੀ ਆਈ, ਇਸ ਸਾਲ ਕਿੰਨੀ ਆਈ, ਅਤੇ ਕੀ ਅਜੇ ਅਦਾਇਗੀ ਦੀ ਉਡੀਕ ਵਿੱਚ ਹੈ।", "একদম উপরে আপনার সব আয় এক নজরে — এই মাসে কত এসেছে, এই বছর কত, আর কী এখনও পরিশোধের অপেক্ষায়।", "في أعلى الصفحة تجد كل إيراداتك في لمحة — ما دخل هذا الشهر، وما دخل هذا العام، وما لا يزال بانتظار الدفع.", "No topo, todas as suas receitas num relance — o que entrou este mês, o que entrou este ano e o que ainda aguarda pagamento.", "Arriba tienes todos tus ingresos de un vistazo: lo que ha entrado este mes, este año y lo que aún espera pago.", "En haut, toutes vos recettes en un coup d’œil : ce qui est entré ce mois-ci, cette année, et ce qui attend encore d’être payé.", "Ar y brig, eich holl arian ar un olwg — beth ddaeth i mewn y mis hwn, beth eleni, a beth sy’n dal i aros am daliad."],
  "lt_purchasing_s1": ["This little pill flips you between the Income side and the Invoices side, and both feed the same headline figure up top.", "Ta mała pigułka przełącza Cię między stroną Przychodów a stroną Faktur, a obie zasilają tę samą główną kwotę na górze.", "Această pastilă te mută între partea de Venituri și cea de Facturi, iar ambele alimentează aceeași cifră principală de sus.", "یہ چھوٹی گولی آپ کو آمدن اور انوائسز کے حصوں کے درمیان بدلتی ہے، اور دونوں اوپر کے ایک ہی مرکزی عدد میں جاتے ہیں۔", "ਇਹ ਛੋਟੀ ਗੋਲੀ ਤੁਹਾਨੂੰ ਆਮਦਨ ਅਤੇ ਇਨਵੌਇਸ ਵਾਲੇ ਪਾਸਿਆਂ ਵਿਚਕਾਰ ਬਦਲਦੀ ਹੈ, ਅਤੇ ਦੋਵੇਂ ਉੱਪਰ ਦੇ ਇੱਕੋ ਮੁੱਖ ਅੰਕ ਵਿੱਚ ਜਾਂਦੇ ਹਨ।", "এই ছোট পিলটি আপনাকে আয় ও ইনভয়েস — দুই পাশের মধ্যে বদলে দেয়, আর দুটিই উপরের একই মূল অঙ্কে যোগ হয়।", "هذا الزر الصغير ينقلك بين جانب الدخل وجانب الفواتير، وكلاهما يغذي الرقم الرئيسي نفسه في الأعلى.", "Esta pastilha alterna entre o lado dos Rendimentos e o das Faturas, e ambos alimentam o mesmo valor principal no topo.", "Esta pastilla te cambia entre el lado de Ingresos y el de Facturas, y ambos alimentan la misma cifra principal de arriba.", "Cette pastille vous fait passer du côté Revenus au côté Factures, et les deux alimentent le même chiffre principal en haut.", "Mae’r pilsen fach hon yn eich symud rhwng yr ochr Incwm a’r ochr Anfonebau, ac mae’r ddwy’n bwydo’r un ffigur pennawd ar y brig."],
  "lt_purchasing_s2": ["The Overview breaks your income down by programme and payment type, and you can scope it to any season or date range you fancy.", "Przegląd rozbija Twoje przychody według programu i rodzaju płatności, a możesz zawęzić go do dowolnego sezonu lub zakresu dat.", "Prezentarea generală îți împarte veniturile pe program și tip de plată și o poți limita la orice sezon sau interval de date dorești.", "اوورویو آپ کی آمدن کو پروگرام اور ادائیگی کی قسم کے حساب سے تقسیم کرتا ہے، اور آپ اسے کسی بھی سیزن یا تاریخوں کی حد تک محدود کر سکتے ہیں۔", "ਓਵਰਵਿਊ ਤੁਹਾਡੀ ਆਮਦਨ ਨੂੰ ਪ੍ਰੋਗਰਾਮ ਅਤੇ ਅਦਾਇਗੀ ਦੀ ਕਿਸਮ ਅਨੁਸਾਰ ਵੰਡਦਾ ਹੈ, ਅਤੇ ਤੁਸੀਂ ਇਸਨੂੰ ਕਿਸੇ ਵੀ ਸੀਜ਼ਨ ਜਾਂ ਤਾਰੀਖ਼ ਦੀ ਹੱਦ ਤੱਕ ਸੀਮਤ ਕਰ ਸਕਦੇ ਹੋ।", "ওভারভিউ আপনার আয়কে প্রোগ্রাম ও পেমেন্টের ধরন অনুযায়ী ভাগ করে দেখায়, আর আপনি চাইলে যেকোনো সিজন বা তারিখের পরিসরে সীমিত করতে পারেন।", "تقسّم النظرة العامة دخلك حسب البرنامج ونوع الدفع، ويمكنك حصرها في أي موسم أو نطاق تواريخ تشاء.", "A Visão geral divide os seus rendimentos por programa e tipo de pagamento, e pode limitá-la a qualquer época ou intervalo de datas.", "El Resumen desglosa tus ingresos por programa y tipo de pago, y puedes acotarlo a cualquier temporada o rango de fechas.", "L’Aperçu répartit vos revenus par programme et type de paiement, et vous pouvez le limiter à la saison ou à la période de votre choix.", "Mae’r Trosolwg yn dadansoddi eich incwm yn ôl rhaglen a math o daliad, a gallwch ei gyfyngu i unrhyw dymor neu ystod dyddiadau."],
  "lt_purchasing_s3": ["Your camps, clubs and classes fold in on their own, but cash on the door, grants and fundraising don't — so to add one, you press Log income, and this form opens.", "Twoje obozy, zajęcia i kursy wpadają same, ale gotówka przy wejściu, dotacje i zbiórki nie — więc aby dodać taki wpływ, naciskasz Zapisz przychód i otwiera się ten formularz.", "Taberele, cluburile și cursurile tale se adaugă singure, dar numerarul de la ușă, granturile și strângerile de fonduri nu — așa că, ca să adaugi unul, apeși Înregistrează venit și se deschide acest formular.", "آپ کے کیمپ، کلب اور کلاسیں خود شامل ہو جاتی ہیں، مگر دروازے پر نقد، گرانٹس اور فنڈ ریزنگ نہیں — اس لیے ایک شامل کرنے کے لیے آپ آمدن درج کریں دباتے ہیں، اور یہ فارم کھل جاتا ہے۔", "ਤੁਹਾਡੇ ਕੈਂਪ, ਕਲੱਬ ਅਤੇ ਕਲਾਸਾਂ ਆਪਣੇ ਆਪ ਜੁੜ ਜਾਂਦੀਆਂ ਹਨ, ਪਰ ਦਰਵਾਜ਼ੇ ਉੱਤੇ ਨਕਦੀ, ਗ੍ਰਾਂਟਾਂ ਅਤੇ ਫੰਡ ਇਕੱਠੇ ਕਰਨਾ ਨਹੀਂ — ਇਸ ਲਈ ਇੱਕ ਜੋੜਨ ਲਈ ਤੁਸੀਂ ਆਮਦਨ ਦਰਜ ਕਰੋ ਦਬਾਉਂਦੇ ਹੋ, ਅਤੇ ਇਹ ਫਾਰਮ ਖੁੱਲ੍ਹ ਜਾਂਦਾ ਹੈ।", "আপনার ক্যাম্প, ক্লাব আর ক্লাস নিজে থেকেই যোগ হয়, কিন্তু দরজায় নগদ, অনুদান আর তহবিল সংগ্রহ হয় না — তাই একটি যোগ করতে আপনি আয় লিখুন চাপেন, আর এই ফর্মটি খুলে যায়।", "تُضاف مخيماتك ونواديك وحصصك من تلقاء نفسها، لكن النقد عند الباب والمنح وجمع التبرعات لا تُضاف — لذا لإضافة واحد منها تضغط تسجيل دخل فيُفتح هذا النموذج.", "Os seus campos, clubes e aulas entram sozinhos, mas o dinheiro na porta, os subsídios e as angariações não — por isso, para adicionar um, prime Registar rendimento e este formulário abre-se.", "Tus campamentos, clubes y clases entran solos, pero el efectivo en la puerta, las subvenciones y las recaudaciones no; así que, para añadir uno, pulsas Registrar ingreso y se abre este formulario.", "Vos camps, clubs et cours s’ajoutent tout seuls, mais pas les espèces à l’entrée, les subventions ni les collectes — alors, pour en ajouter une, vous appuyez sur Enregistrer un revenu et ce formulaire s’ouvre.", "Mae eich gwersylloedd, clybiau a dosbarthiadau’n plygu i mewn ar eu pen eu hunain, ond nid arian parod wrth y drws, grantiau a chodi arian — felly i ychwanegu un, pwyswch Logio incwm ac mae’r ffurflen hon yn agor."],
  "lt_purchasing_s4": ["First pick a category — I'll choose Grants — then pop in the amount that came in, seven hundred pounds here.", "Najpierw wybierz kategorię — wybiorę Dotacje — potem wpisz kwotę, która wpłynęła, tutaj siedemset funtów.", "Mai întâi alege o categorie — o aleg pe Granturi — apoi introdu suma încasată, aici șapte sute de lire.", "پہلے ایک زمرہ چنیں — میں گرانٹس چنوں گا — پھر آنے والی رقم ڈالیں، یہاں سات سو پاؤنڈ۔", "ਪਹਿਲਾਂ ਇੱਕ ਸ਼੍ਰੇਣੀ ਚੁਣੋ — ਮੈਂ ਗ੍ਰਾਂਟਾਂ ਚੁਣਾਂਗਾ — ਫਿਰ ਆਈ ਰਕਮ ਪਾਓ, ਇੱਥੇ ਸੱਤ ਸੌ ਪੌਂਡ।", "প্রথমে একটি বিভাগ বেছে নিন — আমি অনুদান বাছছি — তারপর যে টাকা এসেছে তা লিখুন, এখানে সাতশো পাউন্ড।", "اختر فئة أولًا — سأختار المنح — ثم أدخل المبلغ الذي وصل، هنا سبعمئة جنيه إسترليني.", "Primeiro escolha uma categoria — vou escolher Subsídios — e depois indique o valor que entrou, aqui setecentas libras.", "Primero elige una categoría (yo elijo Subvenciones) y luego indica el importe que ha entrado, aquí setecientas libras.", "Choisissez d’abord une catégorie — je prends Subventions — puis saisissez le montant reçu, ici sept cents livres.", "Dewiswch gategori’n gyntaf — dewisaf Grantiau — yna rhowch y swm a ddaeth i mewn, saith cant o bunnoedd yma."],
  "lt_purchasing_s5": ["Jot down who it came from — a lottery grant here — and add a quick note underneath so you'll remember what it was for.", "Zanotuj, od kogo pochodzi — tu dotacja loteryjna — i dodaj krótką notatkę, żebyś pamiętał, na co to było.", "Notează de la cine a venit — aici un grant de la loterie — și adaugă dedesubt o scurtă notă ca să-ți amintești pentru ce a fost.", "لکھیں کہ یہ کس سے آیا — یہاں لاٹری گرانٹ — اور نیچے ایک مختصر نوٹ ڈالیں تاکہ آپ کو یاد رہے کہ یہ کس لیے تھا۔", "ਲਿਖੋ ਕਿ ਇਹ ਕਿਸ ਤੋਂ ਆਇਆ — ਇੱਥੇ ਲਾਟਰੀ ਗ੍ਰਾਂਟ — ਅਤੇ ਹੇਠਾਂ ਇੱਕ ਛੋਟਾ ਨੋਟ ਜੋੜੋ ਤਾਂ ਜੋ ਤੁਹਾਨੂੰ ਯਾਦ ਰਹੇ ਕਿ ਇਹ ਕਿਸ ਲਈ ਸੀ।", "কার কাছ থেকে এসেছে লিখে রাখুন — এখানে একটি লটারি অনুদান — আর নিচে একটি ছোট নোট যোগ করুন, যাতে মনে থাকে এটি কীসের জন্য।", "دوّن ممّن جاء — هنا منحة يانصيب — وأضف أسفلها ملاحظة سريعة لتتذكر سببه.", "Anote de quem veio — aqui um subsídio da lotaria — e acrescente por baixo uma nota rápida para se lembrar do motivo.", "Anota de quién viene (aquí, una subvención de la lotería) y añade debajo una nota rápida para acordarte de para qué era.", "Notez d’où ça vient — ici une subvention de la loterie — et ajoutez dessous une petite note pour vous rappeler à quoi elle servait.", "Nodwch o ble y daeth — grant loteri yma — ac ychwanegwch nodyn cyflym oddi tano fel y cofiwch beth oedd ei bwrpas."],
  "lt_purchasing_s6": ["If it comes round regularly, set a repeat and an until-date — I'll make this one monthly to the end of December — and it'll log itself each time.", "Jeśli wpływ się powtarza, ustaw powtarzanie i datę końcową — zrobię to miesięcznie do końca grudnia — a zapisze się sam za każdym razem.", "Dacă se repetă, setează o repetare și o dată de final — o fac lunară până la sfârșitul lui decembrie — și se va înregistra singură de fiecare dată.", "اگر یہ باقاعدگی سے آتا ہے تو دہرائی اور آخری تاریخ سیٹ کریں — میں اسے دسمبر کے آخر تک ماہانہ بناتا ہوں — اور یہ ہر بار خود درج ہو جائے گا۔", "ਜੇ ਇਹ ਨਿਯਮਿਤ ਆਉਂਦਾ ਹੈ ਤਾਂ ਦੁਹਰਾਓ ਅਤੇ ਅੰਤਮ ਤਾਰੀਖ਼ ਸੈੱਟ ਕਰੋ — ਮੈਂ ਇਸਨੂੰ ਦਸੰਬਰ ਦੇ ਅੰਤ ਤੱਕ ਮਹੀਨਾਵਾਰ ਬਣਾਉਂਦਾ ਹਾਂ — ਅਤੇ ਇਹ ਹਰ ਵਾਰ ਆਪਣੇ ਆਪ ਦਰਜ ਹੋ ਜਾਵੇਗਾ।", "নিয়মিত এলে পুনরাবৃত্তি আর একটি শেষ তারিখ ঠিক করুন — আমি এটিকে ডিসেম্বরের শেষ পর্যন্ত মাসিক করছি — আর এটি প্রতিবার নিজে থেকেই লেখা হয়ে যাবে।", "إن كان يتكرر بانتظام، فاضبط تكرارًا وتاريخ انتهاء — سأجعل هذا شهريًا حتى نهاية ديسمبر — وسيُسجَّل تلقائيًا في كل مرة.", "Se se repetir com regularidade, defina uma repetição e uma data final — vou torná-la mensal até ao fim de dezembro — e ficará registada sozinha de cada vez.", "Si se repite con regularidad, configura una repetición y una fecha final (yo la haré mensual hasta finales de diciembre) y se registrará sola cada vez.", "Si elle revient régulièrement, réglez une répétition et une date de fin — je la mets mensuelle jusqu’à fin décembre — et elle se saisira toute seule à chaque fois.", "Os yw’n dod yn rheolaidd, gosodwch ailadrodd a dyddiad terfyn — gwnaf hon yn fisol hyd ddiwedd Rhagfyr — a bydd yn logio ei hun bob tro."],
  "lt_purchasing_s7": ["Then you press Create series, and each month's entry drops straight into your ledger, folded into your money-in totals up top.", "Potem naciskasz Utwórz serię, a wpis za każdy miesiąc trafia do księgi i wlicza się w sumy wpływów na górze.", "Apoi apeși Creează serie, iar înregistrarea fiecărei luni ajunge direct în registru, inclusă în totalurile de încasări de sus.", "پھر آپ سیریز بنائیں دباتے ہیں، اور ہر مہینے کا اندراج سیدھا آپ کے کھاتے میں آ جاتا ہے اور اوپر آمدنی کے مجموعوں میں شامل ہو جاتا ہے۔", "ਫਿਰ ਤੁਸੀਂ ਲੜੀ ਬਣਾਓ ਦਬਾਉਂਦੇ ਹੋ, ਅਤੇ ਹਰ ਮਹੀਨੇ ਦਾ ਇੰਦਰਾਜ਼ ਸਿੱਧਾ ਤੁਹਾਡੇ ਖਾਤੇ ਵਿੱਚ ਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਉੱਪਰ ਆਮਦਨ ਦੇ ਕੁੱਲ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋ ਜਾਂਦਾ ਹੈ।", "তারপর আপনি সিরিজ তৈরি করুন চাপেন, আর প্রতি মাসের এন্ট্রি সরাসরি খতিয়ানে চলে যায় এবং উপরের আয়ের মোটে যুক্ত হয়।", "ثم تضغط إنشاء سلسلة فيهبط إدخال كل شهر مباشرة في دفتر حساباتك ويُضاف إلى إجماليات الإيرادات في الأعلى.", "Depois prime Criar série e a entrada de cada mês cai direta no seu livro, incluída nos totais de receitas no topo.", "Luego pulsas Crear serie y la entrada de cada mes cae directamente en tu libro, incluida en los totales de ingresos de arriba.", "Puis vous appuyez sur Créer la série, et l’entrée de chaque mois tombe directement dans votre registre, incluse dans les totaux de recettes en haut.", "Yna pwyswch Creu cyfres, ac mae cofnod pob mis yn disgyn yn syth i’ch cyfriflyfr, wedi’i gynnwys yn eich cyfansymiau arian i mewn ar y brig."],
  "lt_staff_title": ["Team & deployment", "Zespół i wdrożenie", "Echipa și repartizare", "ٹیم اور تعیناتی", "ਟੀਮ ਅਤੇ ਤੈਨਾਤੀ", "টিম ও নিয়োগ", "الفريق والتوزيع", "Equipa e destacamento", "Equipo y asignación", "Équipe et affectation", "Tîm a dyrannu"],
  "lt_staff_intro": ["This is your team — invite people, watch who joins, then deploy them to the right places. Let me invite someone with you.", "To Twój zespół — zapraszasz osoby, sprawdzasz, kto dołączył, a potem przypisujesz je do właściwych miejsc. Zaprośmy razem kogoś.", "Aceasta este echipa ta — inviți oameni, urmărești cine se alătură, apoi îi repartizezi în locurile potrivite. Hai să invităm pe cineva împreună.", "یہ آپ کی ٹیم ہے — لوگوں کو مدعو کریں، دیکھیں کون شامل ہوا، پھر انہیں صحیح جگہوں پر تعینات کریں۔ آئیں، آپ کے ساتھ کسی کو مدعو کرتے ہیں۔", "ਇਹ ਤੁਹਾਡੀ ਟੀਮ ਹੈ — ਲੋਕਾਂ ਨੂੰ ਸੱਦਾ ਦਿਓ, ਦੇਖੋ ਕੌਣ ਜੁੜਿਆ, ਫਿਰ ਉਨ੍ਹਾਂ ਨੂੰ ਸਹੀ ਥਾਵਾਂ ਉੱਤੇ ਤੈਨਾਤ ਕਰੋ। ਆਓ, ਤੁਹਾਡੇ ਨਾਲ ਕਿਸੇ ਨੂੰ ਸੱਦਾ ਦੇਈਏ।", "এটি আপনার টিম — মানুষকে আমন্ত্রণ জানান, দেখুন কে যোগ দিল, তারপর সঠিক জায়গায় নিয়োগ করুন। আসুন, আপনার সঙ্গে একজনকে আমন্ত্রণ জানাই।", "هذا هو فريقك — ادعُ الأشخاص، وتابع من انضم، ثم وزّعهم على الأماكن المناسبة. دعنا ندعو شخصًا معًا.", "Esta é a sua equipa — convide pessoas, veja quem se junta e depois destaque-as para os locais certos. Vamos convidar alguém em conjunto.", "Este es tu equipo: invita a personas, mira quién se une y luego asígnalas a los sitios adecuados. Vamos a invitar a alguien juntos.", "Voici votre équipe : invitez des personnes, voyez qui les rejoint, puis affectez-les aux bons endroits. Invitons quelqu’un ensemble.", "Dyma’ch tîm — gwahoddwch bobl, gwyliwch pwy sy’n ymuno, yna dyrannwch nhw i’r mannau cywir. Gadewch i ni wahodd rhywun gyda’n gilydd."],
  "lt_staff_done": ["That's it — invited, tracked from Pending to Activated, and deployed to the right location and listings.", "To wszystko — zaproszony, śledzony od Oczekujący do Aktywowany i przypisany do właściwej lokalizacji i ofert.", "Gata — invitat, urmărit de la În așteptare la Activat și repartizat la locația și ofertele potrivite.", "بس — مدعو کیا گیا، زیر التوا سے فعال تک ٹریک ہوا، اور صحیح مقام اور لسٹنگز پر تعینات ہو گیا۔", "ਬੱਸ — ਸੱਦਾ ਦਿੱਤਾ, ਬਕਾਇਆ ਤੋਂ ਚਾਲੂ ਤੱਕ ਟਰੈਕ ਕੀਤਾ, ਅਤੇ ਸਹੀ ਥਾਂ ਅਤੇ ਲਿਸਟਿੰਗਾਂ ਉੱਤੇ ਤੈਨਾਤ ਕੀਤਾ।", "ব্যস — আমন্ত্রণ পাঠানো হলো, মুলতুবি থেকে সক্রিয় পর্যন্ত নজরে রাখা হলো, আর সঠিক অবস্থান ও লিস্টিংয়ে নিয়োগ হলো।", "هذا كل شيء — تمت الدعوة، وجرت المتابعة من معلّق إلى مفعّل، وتم التوزيع على الموقع والإعلانات المناسبة.", "Pronto — convidado, acompanhado de Pendente a Ativado e destacado para o local e os anúncios certos.", "Listo: invitado, seguido de Pendiente a Activado y asignado al lugar y a los anuncios correctos.", "Voilà : invité, suivi de En attente à Activé, et affecté au bon lieu et aux bonnes annonces.", "Dyna ni — gwahoddwyd, tracio o Yn aros i Wedi’i actifadu, a’i ddyrannu i’r lleoliad a’r rhestriadau cywir."],
  "lt_staff_s0": ["Start with who's joining. I'll type their full name — Priya Shah — and the email we'll send the invite to. The email's required; that's how they actually sign up.", "Zacznij od tego, kto dołącza. Wpiszę imię i nazwisko — Priya Shah — oraz e-mail, na który wyślemy zaproszenie. E-mail jest wymagany; tak się rejestrują.", "Începe cu cine se alătură. Scriu numele complet — Priya Shah — și adresa de e-mail la care trimitem invitația. E-mailul este obligatoriu; așa își face cont.", "شروع اس سے کریں کہ کون شامل ہو رہا ہے۔ میں پورا نام لکھتا ہوں — پریا شاہ — اور وہ ای میل جس پر دعوت بھیجی جائے گی۔ ای میل ضروری ہے؛ اسی سے وہ سائن اپ کرتے ہیں۔", "ਇਸ ਨਾਲ ਸ਼ੁਰੂ ਕਰੋ ਕਿ ਕੌਣ ਜੁੜ ਰਿਹਾ ਹੈ। ਮੈਂ ਪੂਰਾ ਨਾਮ ਲਿਖਦਾ ਹਾਂ — ਪ੍ਰੀਆ ਸ਼ਾਹ — ਅਤੇ ਉਹ ਈਮੇਲ ਜਿਸ ਉੱਤੇ ਸੱਦਾ ਭੇਜਿਆ ਜਾਵੇਗਾ। ਈਮੇਲ ਜ਼ਰੂਰੀ ਹੈ; ਇਸੇ ਨਾਲ ਉਹ ਸਾਈਨ ਅੱਪ ਕਰਦੇ ਹਨ।", "শুরু করুন কে যোগ দিচ্ছে তা দিয়ে। আমি পুরো নাম লিখছি — প্রিয়া শাহ — আর যে ইমেইলে আমন্ত্রণ যাবে। ইমেইল আবশ্যক; এভাবেই তাঁরা সাইন আপ করেন।", "ابدأ بمن سينضم. سأكتب الاسم الكامل — بريا شاه — والبريد الإلكتروني الذي سنرسل إليه الدعوة. البريد مطلوب؛ فبه يسجّلون فعليًا.", "Comece por quem se junta. Vou escrever o nome completo — Priya Shah — e o e-mail para onde enviamos o convite. O e-mail é obrigatório; é assim que a pessoa se regista.", "Empieza por quién se une. Escribiré el nombre completo (Priya Shah) y el correo al que enviaremos la invitación. El correo es obligatorio: así es como se registra.", "Commencez par la personne qui rejoint. Je saisis son nom complet — Priya Shah — et l’e-mail où envoyer l’invitation. L’e-mail est obligatoire ; c’est ainsi qu’elle s’inscrit.", "Dechreuwch gyda phwy sy’n ymuno. Teipiaf eu henw llawn — Priya Shah — a’r e-bost y byddwn yn anfon y gwahoddiad iddo. Mae’r e-bost yn ofynnol; dyna sut maen nhw’n cofrestru."],
  "lt_staff_s1": ["Next, their access role — Owner, Management or Staff. It sets what they can see and do. You can rename any role and change its permissions in Setup.", "Dalej rola dostępu — Właściciel, Zarząd lub Personel. Określa, co dana osoba widzi i może robić. Każdą rolę możesz przemianować i zmienić jej uprawnienia w Konfiguracji.", "Apoi rolul de acces — Proprietar, Conducere sau Personal. Stabilește ce poate vedea și face persoana. Poți redenumi orice rol și îi poți schimba permisiunile în Configurare.", "اس کے بعد ان کا رسائی کا کردار — مالک، انتظامیہ یا عملہ۔ یہ طے کرتا ہے کہ وہ کیا دیکھ اور کر سکتے ہیں۔ آپ سیٹ اپ میں کسی بھی کردار کا نام بدل کر اس کی اجازتیں تبدیل کر سکتے ہیں۔", "ਅੱਗੇ ਉਨ੍ਹਾਂ ਦੀ ਪਹੁੰਚ ਦੀ ਭੂਮਿਕਾ — ਮਾਲਕ, ਪ੍ਰਬੰਧਨ ਜਾਂ ਸਟਾਫ਼। ਇਹ ਤੈਅ ਕਰਦੀ ਹੈ ਕਿ ਉਹ ਕੀ ਦੇਖ ਅਤੇ ਕਰ ਸਕਦੇ ਹਨ। ਤੁਸੀਂ ਸੈੱਟਅੱਪ ਵਿੱਚ ਕਿਸੇ ਵੀ ਭੂਮਿਕਾ ਦਾ ਨਾਮ ਬਦਲ ਕੇ ਉਸ ਦੀਆਂ ਇਜਾਜ਼ਤਾਂ ਬਦਲ ਸਕਦੇ ਹੋ।", "এরপর তাঁদের অ্যাক্সেস ভূমিকা — মালিক, ম্যানেজমেন্ট বা কর্মী। এটি ঠিক করে তাঁরা কী দেখতে ও করতে পারবেন। সেটআপে যেকোনো ভূমিকার নাম বদলে তার অনুমতি পরিবর্তন করতে পারেন।", "بعد ذلك دور الوصول — مالك أو إدارة أو موظف. يحدد ما يمكنهم رؤيته وفعله. يمكنك إعادة تسمية أي دور وتغيير صلاحياته من الإعداد.", "A seguir, a função de acesso — Proprietário, Gestão ou Equipa. Define o que a pessoa pode ver e fazer. Pode renomear qualquer função e alterar as suas permissões na Configuração.", "Después, su rol de acceso: Propietario, Dirección o Personal. Define lo que puede ver y hacer. Puedes renombrar cualquier rol y cambiar sus permisos en Configuración.", "Ensuite, son rôle d’accès — Propriétaire, Direction ou Personnel. Il détermine ce que la personne peut voir et faire. Vous pouvez renommer n’importe quel rôle et modifier ses autorisations dans Configuration.", "Nesaf, eu rôl mynediad — Perchennog, Rheolaeth neu Staff. Mae’n pennu beth allan nhw ei weld a’i wneud. Gallwch ailenwi unrhyw rôl a newid ei chaniatâd yn y Gosodiad."],
  "lt_staff_s2": ["Then their job title, like First Aider or Site Manager — the coloured rows on the rota. Not in the list? Add one and it saves for everyone.", "Potem stanowisko, na przykład Pierwsza pomoc lub Kierownik obiektu — kolorowe wiersze w grafiku. Nie ma go na liście? Dodaj, a zapisze się dla wszystkich.", "Apoi titlul postului, ca Prim-ajutor sau Manager de locație — rândurile colorate din program. Nu e în listă? Adaug-o și se salvează pentru toți.", "پھر ان کا عہدہ، جیسے فرسٹ ایڈر یا سائٹ مینیجر — روٹا پر رنگین قطاریں۔ فہرست میں نہیں ہے؟ ایک شامل کریں اور یہ سب کے لیے محفوظ ہو جاتا ہے۔", "ਫਿਰ ਉਨ੍ਹਾਂ ਦਾ ਅਹੁਦਾ, ਜਿਵੇਂ ਫਸਟ ਏਡਰ ਜਾਂ ਸਾਈਟ ਮੈਨੇਜਰ — ਰੋਟਾ ਉੱਤੇ ਰੰਗਦਾਰ ਕਤਾਰਾਂ। ਸੂਚੀ ਵਿੱਚ ਨਹੀਂ ਹੈ? ਇੱਕ ਜੋੜੋ ਅਤੇ ਇਹ ਸਭ ਲਈ ਸੁਰੱਖਿਅਤ ਹੋ ਜਾਂਦਾ ਹੈ।", "তারপর তাঁদের পদবি, যেমন ফার্স্ট এইডার বা সাইট ম্যানেজার — রোটায় রঙিন সারি। তালিকায় নেই? একটি যোগ করুন, আর তা সবার জন্য সংরক্ষিত হবে।", "ثم مسماهم الوظيفي، مثل مسعف أول أو مدير الموقع — الصفوف الملونة في جدول المناوبات. ليس في القائمة؟ أضف واحدًا فيُحفظ للجميع.", "Depois o cargo, como Socorrista ou Gestor do local — as linhas coloridas na escala. Não está na lista? Adicione um e fica guardado para todos.", "Luego su puesto, como Socorrista o Responsable del centro: las filas de colores del cuadrante. ¿No está en la lista? Añade uno y se guarda para todos.", "Puis son intitulé de poste, comme Secouriste ou Responsable de site — les lignes colorées du planning. Il n’est pas dans la liste ? Ajoutez-le et il est enregistré pour tous.", "Yna eu teitl swydd, fel Cymorth Cyntaf neu Reolwr Safle — y rhesi lliw ar y rota. Ddim ar y rhestr? Ychwanegwch un ac mae’n cadw i bawb."],
  "lt_staff_s3": ["Now where they work. Pick None and they get page access from their role but aren't rostered — or choose locations, then the listings inside them, each showing its season. I'll put Priya across all locations and listings.", "Teraz gdzie pracują. Wybierz Brak, a dostaną dostęp do stron z roli, ale nie trafią do grafiku — albo wybierz lokalizacje, a potem zawarte w nich oferty, każda z sezonem. Przypiszę Priyę do wszystkich lokalizacji i ofert.", "Acum unde lucrează. Alege Niciuna și primesc acces la pagini prin rol, dar nu sunt programați — sau alege locații, apoi ofertele din ele, fiecare cu sezonul ei. O voi pune pe Priya în toate locațiile și ofertele.", "اب وہ کہاں کام کرتے ہیں۔ کوئی نہیں چنیں تو انہیں اپنے کردار سے صفحات تک رسائی ملتی ہے مگر وہ روسٹر میں نہیں ہوتے — یا مقامات چنیں، پھر ان کے اندر لسٹنگز، ہر ایک اپنے سیزن کے ساتھ۔ میں پریا کو تمام مقامات اور لسٹنگز میں رکھتا ہوں۔", "ਹੁਣ ਉਹ ਕਿੱਥੇ ਕੰਮ ਕਰਦੇ ਹਨ। ਕੋਈ ਨਹੀਂ ਚੁਣੋ ਤਾਂ ਉਨ੍ਹਾਂ ਨੂੰ ਭੂਮਿਕਾ ਤੋਂ ਪੰਨਿਆਂ ਤੱਕ ਪਹੁੰਚ ਮਿਲਦੀ ਹੈ ਪਰ ਰੋਸਟਰ ਵਿੱਚ ਨਹੀਂ ਹੁੰਦੇ — ਜਾਂ ਥਾਵਾਂ ਚੁਣੋ, ਫਿਰ ਉਨ੍ਹਾਂ ਵਿਚਲੀਆਂ ਲਿਸਟਿੰਗਾਂ, ਹਰ ਇੱਕ ਆਪਣੇ ਸੀਜ਼ਨ ਨਾਲ। ਮੈਂ ਪ੍ਰੀਆ ਨੂੰ ਸਾਰੀਆਂ ਥਾਵਾਂ ਅਤੇ ਲਿਸਟਿੰਗਾਂ ਵਿੱਚ ਪਾਉਂਦਾ ਹਾਂ।", "এবার তাঁরা কোথায় কাজ করেন। কোনোটিই না বাছলে ভূমিকা থেকে পাতায় অ্যাক্সেস পান কিন্তু রোস্টারে থাকেন না — অথবা অবস্থান বেছে নিন, তারপর তার ভেতরের লিস্টিং, প্রতিটি নিজের সিজনসহ। আমি প্রিয়াকে সব অবস্থান ও লিস্টিংয়ে রাখছি।", "الآن أين يعملون. اختر لا شيء فيحصلون على الوصول إلى الصفحات من دورهم دون إدراجهم في الجدول — أو اختر المواقع ثم الإعلانات داخلها، ولكل منها موسمه. سأضع بريا في كل المواقع والإعلانات.", "Agora, onde trabalham. Escolha Nenhum e a pessoa tem acesso às páginas pela função mas não entra na escala — ou escolha locais e depois os anúncios dentro deles, cada um com a sua época. Vou colocar a Priya em todos os locais e anúncios.", "Ahora dónde trabajan. Elige Ninguno y tendrán acceso a las páginas por su rol pero no entrarán en el cuadrante; o elige ubicaciones y luego los anuncios que contienen, cada uno con su temporada. Pondré a Priya en todas las ubicaciones y anuncios.", "Maintenant, où ils travaillent. Choisissez Aucun et la personne a accès aux pages via son rôle sans être planifiée — ou choisissez des lieux, puis les annonces qu’ils contiennent, chacune avec sa saison. Je place Priya sur tous les lieux et toutes les annonces.", "Nawr ble maen nhw’n gweithio. Dewiswch Dim a chânt fynediad i dudalennau gan eu rôl ond nid ydynt ar y rota — neu dewiswch leoliadau, yna’r rhestriadau ynddynt, pob un gyda’i dymor. Rhoddaf Priya ar draws pob lleoliad a rhestriad."],
  "lt_staff_s4": ["Last step reviews it all — name, role, job title and where they're deployed — then Send fires off the invite. Remember: what they can do comes from the role, not from what they're assigned here.", "Ostatni krok podsumowuje wszystko — imię, rolę, stanowisko i miejsca przypisania — a Wyślij wysyła zaproszenie. Pamiętaj: to, co ktoś może robić, wynika z roli, a nie z tego, do czego jest tu przypisany.", "Ultimul pas le trece pe toate în revistă — nume, rol, titlu și unde este repartizat — apoi Trimite expediază invitația. Ține minte: ce poate face cineva vine din rol, nu din ce i se alocă aici.", "آخری مرحلہ سب کا جائزہ لیتا ہے — نام، کردار، عہدہ اور تعیناتی کی جگہیں — پھر بھیجیں دعوت روانہ کر دیتا ہے۔ یاد رکھیں: کوئی کیا کر سکتا ہے وہ کردار سے طے ہوتا ہے، یہاں کی تعیناتی سے نہیں۔", "ਆਖ਼ਰੀ ਕਦਮ ਸਭ ਦੀ ਸਮੀਖਿਆ ਕਰਦਾ ਹੈ — ਨਾਮ, ਭੂਮਿਕਾ, ਅਹੁਦਾ ਅਤੇ ਤੈਨਾਤੀ ਦੀਆਂ ਥਾਵਾਂ — ਫਿਰ ਭੇਜੋ ਸੱਦਾ ਰਵਾਨਾ ਕਰ ਦਿੰਦਾ ਹੈ। ਯਾਦ ਰੱਖੋ: ਕੋਈ ਕੀ ਕਰ ਸਕਦਾ ਹੈ ਇਹ ਭੂਮਿਕਾ ਤੋਂ ਤੈਅ ਹੁੰਦਾ ਹੈ, ਇੱਥੇ ਦੀ ਤੈਨਾਤੀ ਤੋਂ ਨਹੀਂ।", "শেষ ধাপে সব যাচাই হয় — নাম, ভূমিকা, পদবি ও কোথায় নিয়োগ — তারপর পাঠান চাপলে আমন্ত্রণ চলে যায়। মনে রাখবেন: কেউ কী করতে পারবেন তা ভূমিকা থেকে আসে, এখানে কোথায় নিয়োগ হলো তা থেকে নয়।", "تراجع الخطوة الأخيرة كل شيء — الاسم والدور والمسمى والمواقع المعيّنة — ثم يرسل زر إرسال الدعوة. تذكّر: ما يستطيع الشخص فعله يأتي من الدور، لا مما يُعيَّن له هنا.", "O último passo revê tudo — nome, função, cargo e onde fica destacado — e depois Enviar lança o convite. Lembre-se: o que a pessoa pode fazer vem da função, não do que lhe atribui aqui.", "El último paso lo revisa todo (nombre, rol, puesto y dónde queda asignado) y luego Enviar manda la invitación. Recuerda: lo que alguien puede hacer viene del rol, no de lo que le asignas aquí.", "La dernière étape passe tout en revue — nom, rôle, poste et affectation — puis Envoyer lance l’invitation. Rappelez-vous : ce que la personne peut faire vient du rôle, pas de ce qu’on lui affecte ici.", "Mae’r cam olaf yn adolygu popeth — enw, rôl, teitl swydd a ble caiff ei ddyrannu — yna mae Anfon yn saethu’r gwahoddiad ymaith. Cofiwch: mae’r hyn y gallant ei wneud yn dod o’r rôl, nid o’r hyn a neilltuir yma."],
  "lt_staff_s5": ["Once people have joined, the Deployment tab is where you place them. By location shows each site and who's on it — here Loughton Manor has Alex, Priya and Jordan. Open a location's dropdown to add someone new to it.", "Gdy ludzie dołączą, zakładka Wdrożenie służy do ich rozmieszczania. Według lokalizacji pokazuje każde miejsce i kto w nim jest — tu w Loughton Manor są Alex, Priya i Jordan. Otwórz listę lokalizacji, aby dodać kogoś nowego.", "După ce oamenii s-au alăturat, fila Repartizare este locul unde îi plasezi. După locație arată fiecare loc și cine e acolo — aici Loughton Manor îi are pe Alex, Priya și Jordan. Deschide lista unei locații ca să adaugi pe cineva nou.", "جب لوگ شامل ہو جائیں تو تعیناتی کا ٹیب وہ جگہ ہے جہاں آپ انہیں رکھتے ہیں۔ مقام کے لحاظ سے ہر جگہ اور وہاں کون ہے دکھاتا ہے — یہاں لاؤٹن مینر میں ایلکس، پریا اور جورڈن ہیں۔ کسی نئے کو شامل کرنے کے لیے کسی مقام کا ڈراپ ڈاؤن کھولیں۔", "ਜਦੋਂ ਲੋਕ ਜੁੜ ਜਾਣ, ਤੈਨਾਤੀ ਟੈਬ ਉਹ ਥਾਂ ਹੈ ਜਿੱਥੇ ਤੁਸੀਂ ਉਨ੍ਹਾਂ ਨੂੰ ਰੱਖਦੇ ਹੋ। ਥਾਂ ਅਨੁਸਾਰ ਹਰ ਸਾਈਟ ਅਤੇ ਉੱਥੇ ਕੌਣ ਹੈ ਦਿਖਾਉਂਦਾ ਹੈ — ਇੱਥੇ ਲਾਊਟਨ ਮੈਨਰ ਵਿੱਚ ਐਲੈਕਸ, ਪ੍ਰੀਆ ਅਤੇ ਜੌਰਡਨ ਹਨ। ਕਿਸੇ ਨਵੇਂ ਨੂੰ ਜੋੜਨ ਲਈ ਕਿਸੇ ਥਾਂ ਦਾ ਡ੍ਰੌਪਡਾਊਨ ਖੋਲ੍ਹੋ।", "মানুষ যোগ দেওয়ার পর নিয়োগ ট্যাবে আপনি তাঁদের বসান। অবস্থান অনুযায়ী প্রতিটি সাইট ও সেখানে কে আছেন দেখায় — এখানে লাফটন ম্যানরে অ্যালেক্স, প্রিয়া ও জর্ডান আছেন। নতুন কাউকে যোগ করতে কোনো অবস্থানের ড্রপডাউন খুলুন।", "بعد انضمام الأشخاص، تبويب التوزيع هو المكان الذي تضعهم فيه. حسب الموقع يعرض كل موقع ومن فيه — هنا في لوتون مانور ألكس وبريا وجوردان. افتح قائمة أي موقع لإضافة شخص جديد إليه.", "Depois de as pessoas se juntarem, o separador Destacamento é onde as coloca. Por local mostra cada espaço e quem lá está — aqui o Loughton Manor tem o Alex, a Priya e o Jordan. Abra a lista de um local para lhe juntar alguém.", "Cuando la gente se ha unido, la pestaña Asignación es donde la colocas. Por ubicación muestra cada sitio y quién está en él: aquí Loughton Manor tiene a Alex, Priya y Jordan. Abre el desplegable de una ubicación para añadir a alguien nuevo.", "Une fois les personnes inscrites, l’onglet Affectation sert à les placer. Par lieu affiche chaque site et qui s’y trouve — ici Loughton Manor compte Alex, Priya et Jordan. Ouvrez la liste d’un lieu pour y ajouter quelqu’un.", "Unwaith y bydd pobl wedi ymuno, y tab Dyrannu yw lle rydych yn eu gosod. Yn ôl lleoliad mae’n dangos pob safle a phwy sydd arno — yma mae gan Loughton Manor Alex, Priya a Jordan. Agorwch gwymplen lleoliad i ychwanegu rhywun newydd ato."],
  "lt_staff_s6": ["By staff lists everyone A to Z with their locations and listings as chips. Tap a location or a specific listing to turn it on or off — I'll assign a listing now — and that instantly changes which sites and programmes they're rostered for.", "Według pracownika wyświetla wszystkich od A do Z z ich lokalizacjami i ofertami jako znaczkami. Dotknij lokalizacji lub konkretnej oferty, aby ją włączyć lub wyłączyć — przypiszę teraz ofertę — a to od razu zmienia, do jakich miejsc i programów ktoś jest wpisany w grafiku.", "După personal afișează pe toată lumea de la A la Z, cu locațiile și ofertele ca etichete. Atinge o locație sau o ofertă anume ca s-o activezi sau s-o dezactivezi — acum aloc o ofertă — și asta schimbă instantaneu pentru ce locuri și programe e programată persoana.", "عملے کے لحاظ سے سب کو الف سے ے تک ان کے مقامات اور لسٹنگز کے چپس کے ساتھ دکھاتا ہے۔ کسی مقام یا مخصوص لسٹنگ کو آن یا آف کرنے کے لیے ٹیپ کریں — میں اب ایک لسٹنگ تفویض کرتا ہوں — اور یہ فوراً بدل دیتا ہے کہ وہ کن جگہوں اور پروگراموں کے روسٹر میں ہیں۔", "ਸਟਾਫ਼ ਅਨੁਸਾਰ ਸਭ ਨੂੰ A ਤੋਂ Z ਤੱਕ ਉਨ੍ਹਾਂ ਦੀਆਂ ਥਾਵਾਂ ਅਤੇ ਲਿਸਟਿੰਗਾਂ ਦੇ ਚਿੱਪਾਂ ਨਾਲ ਦਿਖਾਉਂਦਾ ਹੈ। ਕਿਸੇ ਥਾਂ ਜਾਂ ਖ਼ਾਸ ਲਿਸਟਿੰਗ ਨੂੰ ਚਾਲੂ ਜਾਂ ਬੰਦ ਕਰਨ ਲਈ ਟੈਪ ਕਰੋ — ਮੈਂ ਹੁਣ ਇੱਕ ਲਿਸਟਿੰਗ ਸੌਂਪਦਾ ਹਾਂ — ਅਤੇ ਇਹ ਤੁਰੰਤ ਬਦਲ ਦਿੰਦਾ ਹੈ ਕਿ ਉਹ ਕਿਹੜੀਆਂ ਸਾਈਟਾਂ ਅਤੇ ਪ੍ਰੋਗਰਾਮਾਂ ਦੇ ਰੋਸਟਰ ਵਿੱਚ ਹਨ।", "কর্মী অনুযায়ী সবাইকে A থেকে Z ক্রমে তাঁদের অবস্থান ও লিস্টিংসহ চিপ আকারে দেখায়। কোনো অবস্থান বা নির্দিষ্ট লিস্টিং চালু বা বন্ধ করতে ট্যাপ করুন — আমি এখন একটি লিস্টিং বরাদ্দ করছি — আর তাতে সঙ্গে সঙ্গে বদলে যায় তাঁরা কোন সাইট ও প্রোগ্রামের রোস্টারে আছেন।", "حسب الموظف يعرض الجميع من الألف إلى الياء مع مواقعهم وإعلاناتهم على هيئة شارات. اضغط على موقع أو إعلان معيّن لتشغيله أو إيقافه — سأعيّن إعلانًا الآن — وهذا يغيّر فورًا المواقع والبرامج المدرجين فيها في الجدول.", "Por funcionário lista todos de A a Z com os seus locais e anúncios como etiquetas. Toque num local ou num anúncio específico para o ligar ou desligar — vou atribuir um anúncio agora — e isso muda de imediato para que locais e programas a pessoa está escalada.", "Por personal lista a todos de la A a la Z con sus ubicaciones y anuncios como etiquetas. Toca una ubicación o un anuncio concreto para activarlo o desactivarlo (ahora asignaré un anuncio) y eso cambia al instante para qué sitios y programas está asignada la persona.", "Par personnel liste tout le monde de A à Z avec ses lieux et annonces sous forme d’étiquettes. Touchez un lieu ou une annonce précise pour l’activer ou le désactiver — j’en affecte une maintenant — et cela change aussitôt les sites et programmes pour lesquels la personne est planifiée.", "Mae Yn ôl staff yn rhestru pawb o A i Z gyda’u lleoliadau a’u rhestriadau fel sglodion. Tapiwch leoliad neu restriad penodol i’w droi ymlaen neu i ffwrdd — neilltuaf restriad nawr — ac mae hynny’n newid ar unwaith pa safleoedd a rhaglenni y maent ar y rota ar eu cyfer."],
  "lt_staff_s7": ["And By listing flips it round — each listing with exactly who's on it, so you can see cover at a glance. That's the whole point: deployment decides whose registers, ratios and schedule each person sees — nothing more, nothing less. That's your team, start to finish.", "A Według oferty odwraca widok — każda oferta z dokładnie tymi osobami, które w niej są, więc obsadę widać od razu. O to właśnie chodzi: wdrożenie decyduje, czyje rejestry, proporcje i grafik dana osoba widzi — nic więcej, nic mniej. Tak wygląda Twój zespół od początku do końca.", "Iar După ofertă întoarce lucrurile — fiecare ofertă cu exact cine e în ea, ca să vezi acoperirea dintr-o privire. Asta e ideea: repartizarea decide ale cui registre, rapoarte și program le vede fiecare persoană — nici mai mult, nici mai puțin. Asta e echipa ta, de la un capăt la altul.", "اور آفر کے لحاظ سے اسے الٹ دیتا ہے — ہر لسٹنگ کے ساتھ ٹھیک وہ لوگ جو اس پر ہیں، تاکہ آپ کوریج ایک نظر میں دیکھ لیں۔ یہی اصل مقصد ہے: تعیناتی طے کرتی ہے کہ ہر شخص کن کے رجسٹر، تناسب اور شیڈول دیکھتا ہے — نہ کم نہ زیادہ۔ یہ ہے آپ کی ٹیم، شروع سے آخر تک۔", "ਅਤੇ ਲਿਸਟਿੰਗ ਅਨੁਸਾਰ ਇਸਨੂੰ ਪਲਟ ਦਿੰਦਾ ਹੈ — ਹਰ ਲਿਸਟਿੰਗ ਨਾਲ ਬਿਲਕੁਲ ਉਹ ਲੋਕ ਜੋ ਉਸ ਉੱਤੇ ਹਨ, ਤਾਂ ਜੋ ਤੁਸੀਂ ਕਵਰੇਜ ਇੱਕ ਨਜ਼ਰ ਵਿੱਚ ਦੇਖ ਸਕੋ। ਇਹੀ ਅਸਲ ਮਕਸਦ ਹੈ: ਤੈਨਾਤੀ ਤੈਅ ਕਰਦੀ ਹੈ ਕਿ ਹਰ ਕੋਈ ਕਿਸ ਦੇ ਰਜਿਸਟਰ, ਅਨੁਪਾਤ ਅਤੇ ਸ਼ਡਿਊਲ ਦੇਖਦਾ ਹੈ — ਨਾ ਘੱਟ, ਨਾ ਵੱਧ। ਇਹ ਹੈ ਤੁਹਾਡੀ ਟੀਮ, ਸ਼ੁਰੂ ਤੋਂ ਅੰਤ ਤੱਕ।", "আর লিস্টিং অনুযায়ী উল্টে দেয় — প্রতিটি লিস্টিংয়ে ঠিক কে কে আছেন, যাতে কভারেজ এক নজরে দেখা যায়। এটাই আসল কথা: নিয়োগ ঠিক করে কার রেজিস্টার, অনুপাত ও সময়সূচি কে দেখবেন — কমও না, বেশিও না। এই হলো আপনার টিম, শুরু থেকে শেষ।", "ثم حسب الإعلان يقلب الصورة — كل إعلان مع من فيه بالضبط، فترى التغطية في لمحة. وهذا هو المقصود: التوزيع يقرر سجلات ونسب وجدول من يراه كل شخص — لا أكثر ولا أقل. هذا هو فريقك من البداية إلى النهاية.", "E Por anúncio inverte a vista — cada anúncio com exatamente quem lá está, para ver a cobertura num relance. É esse o objetivo: o destacamento decide os registos, rácios e escala que cada pessoa vê — nem mais, nem menos. Esta é a sua equipa, do princípio ao fim.", "Y Por anuncio le da la vuelta: cada anuncio con exactamente quién está en él, para ver la cobertura de un vistazo. Ese es el objetivo: la asignación decide qué registros, ratios y horario ve cada persona, ni más ni menos. Ese es tu equipo, de principio a fin.", "Et Par annonce inverse la vue : chaque annonce avec exactement les personnes qui y sont, pour voir la couverture en un coup d’œil. C’est tout l’intérêt : l’affectation décide quels registres, ratios et planning chaque personne voit — ni plus, ni moins. Voilà votre équipe, du début à la fin.", "Ac mae Yn ôl rhestriad yn ei droi o chwith — pob rhestriad gyda’r union bobl sydd arno, fel y gallwch weld y cwmpas ar un olwg. Dyna’r holl bwynt: mae dyrannu’n penderfynu pa gofrestrau, cymarebau ac amserlen y mae pob person yn eu gweld — dim mwy, dim llai. Dyna’ch tîm, o’r dechrau i’r diwedd."],
  "lt_newsfeed_title": ["Newsfeed", "Aktualności", "Noutăți", "نیوز فیڈ", "ਨਿਊਜ਼ਫੀਡ", "নিউজফিড", "آخر الأخبار", "Novidades", "Novedades", "Fil d’actualité", "Ffrwd newyddion"],
  "lt_newsfeed_intro": ["This is your announcement board — post updates, events, reminders and urgent closures, and every family with a booking sees them pop up in their own app.", "To Twoja tablica ogłoszeń — publikuj aktualności, wydarzenia, przypomnienia i pilne zamknięcia, a każda rodzina z rezerwacją zobaczy je w swojej aplikacji.", "Aceasta este tabla ta de anunțuri — postează noutăți, evenimente, mementouri și închideri urgente, iar fiecare familie cu o rezervare le vede în propria aplicație.", "یہ آپ کا اعلانات کا بورڈ ہے — اپ ڈیٹس، ایونٹس، یاد دہانیاں اور فوری بندشیں پوسٹ کریں، اور بکنگ والا ہر خاندان انہیں اپنی ایپ میں دیکھتا ہے۔", "ਇਹ ਤੁਹਾਡਾ ਐਲਾਨ ਬੋਰਡ ਹੈ — ਅੱਪਡੇਟ, ਸਮਾਗਮ, ਯਾਦ-ਦਹਾਨੀਆਂ ਅਤੇ ਫੌਰੀ ਬੰਦੀਆਂ ਪੋਸਟ ਕਰੋ, ਅਤੇ ਬੁਕਿੰਗ ਵਾਲਾ ਹਰ ਪਰਿਵਾਰ ਉਨ੍ਹਾਂ ਨੂੰ ਆਪਣੀ ਐਪ ਵਿੱਚ ਦੇਖਦਾ ਹੈ।", "এটি আপনার ঘোষণার বোর্ড — আপডেট, ইভেন্ট, অনুস্মারক ও জরুরি বন্ধের খবর পোস্ট করুন, আর বুকিং থাকা প্রতিটি পরিবার তা নিজের অ্যাপে দেখতে পায়।", "هذه لوحة إعلاناتك — انشر التحديثات والفعاليات والتذكيرات وإغلاقات الطوارئ، وستظهر لكل عائلة لديها حجز في تطبيقها الخاص.", "Este é o seu quadro de avisos — publique novidades, eventos, lembretes e encerramentos urgentes, e cada família com uma reserva vê-os na sua própria aplicação.", "Este es tu tablón de anuncios: publica novedades, eventos, recordatorios y cierres urgentes, y cada familia con una reserva los verá en su propia aplicación.", "Voici votre tableau d’annonces : publiez actualités, événements, rappels et fermetures urgentes, et chaque famille ayant une réservation les voit dans sa propre appli.", "Dyma’ch bwrdd hysbysiadau — postiwch ddiweddariadau, digwyddiadau, nodiadau atgoffa a chau brys, a bydd pob teulu ag archeb yn eu gweld yn eu ap eu hunain."],
  "lt_newsfeed_done": ["And that's the Newsfeed — pick a template, write it, choose who and when, then watch the seen counts and RSVPs roll in.", "I to cała Aktualność — wybierz szablon, napisz wpis, wskaż, kto i kiedy ma go zobaczyć, a potem obserwuj licznik wyświetleń i odpowiedzi.", "Gata cu Noutățile — alege un șablon, scrie postarea, stabilește cui și când, apoi urmărește cum cresc vizualizările și confirmările.", "بس یہی نیوز فیڈ ہے — ٹیمپلیٹ چنیں، لکھیں، طے کریں کس کو اور کب، اور پھر دیکھے جانے کی گنتی اور جوابات آتے دیکھیں۔", "ਬੱਸ ਇਹੀ ਨਿਊਜ਼ਫੀਡ ਹੈ — ਟੈਮਪਲੇਟ ਚੁਣੋ, ਲਿਖੋ, ਤੈਅ ਕਰੋ ਕਿਸ ਨੂੰ ਅਤੇ ਕਦੋਂ, ਫਿਰ ਦੇਖੇ ਜਾਣ ਦੀ ਗਿਣਤੀ ਅਤੇ ਜਵਾਬ ਆਉਂਦੇ ਦੇਖੋ।", "এই হলো নিউজফিড — একটি টেমপ্লেট বাছুন, লিখুন, ঠিক করুন কাকে ও কখন দেখাবেন, তারপর দেখার সংখ্যা আর আরএসভিপি আসতে দেখুন।", "وهذا هو آخر الأخبار — اختر قالبًا، واكتب، وحدّد لمن ومتى، ثم تابع أعداد المشاهدات وردود الحضور وهي تتوالى.", "E é isto, as Novidades — escolha um modelo, escreva, decida para quem e quando, e depois veja as contagens de visualizações e as respostas a chegar.", "Y eso es el Tablón de novedades: elige una plantilla, escríbelo, decide a quién y cuándo, y mira cómo llegan los recuentos de vistos y las confirmaciones.", "Et voilà le Fil d’actualité : choisissez un modèle, rédigez, décidez pour qui et quand, puis regardez arriver les compteurs de vues et les réponses.", "A dyna’r Ffrwd newyddion — dewiswch dempled, ysgrifennwch, dewiswch pwy a phryd, yna gwyliwch y cyfrifon gweld a’r atebion yn dod i mewn."],
  "lt_newsfeed_s0": ["This is your Newsfeed — post an update and every family with a booking sees it in their own app, from a quick reminder to an event with RSVPs or an urgent closure.", "To Twoje Aktualności — opublikuj wpis, a każda rodzina z rezerwacją zobaczy go w swojej aplikacji, od krótkiego przypomnienia po wydarzenie z potwierdzeniem obecności czy pilne zamknięcie.", "Acestea sunt Noutățile tale — postează o noutate și fiecare familie cu o rezervare o vede în propria aplicație, de la un mic memento până la un eveniment cu confirmări sau o închidere urgentă.", "یہ آپ کی نیوز فیڈ ہے — کوئی اپ ڈیٹ پوسٹ کریں اور بکنگ والا ہر خاندان اسے اپنی ایپ میں دیکھتا ہے، چاہے وہ مختصر یاد دہانی ہو، جوابات والا ایونٹ ہو یا فوری بندش۔", "ਇਹ ਤੁਹਾਡੀ ਨਿਊਜ਼ਫੀਡ ਹੈ — ਕੋਈ ਅੱਪਡੇਟ ਪੋਸਟ ਕਰੋ ਅਤੇ ਬੁਕਿੰਗ ਵਾਲਾ ਹਰ ਪਰਿਵਾਰ ਉਸਨੂੰ ਆਪਣੀ ਐਪ ਵਿੱਚ ਦੇਖਦਾ ਹੈ, ਭਾਵੇਂ ਛੋਟੀ ਯਾਦ-ਦਹਾਨੀ ਹੋਵੇ, ਜਵਾਬਾਂ ਵਾਲਾ ਸਮਾਗਮ ਹੋਵੇ ਜਾਂ ਫੌਰੀ ਬੰਦੀ।", "এটি আপনার নিউজফিড — একটি আপডেট পোস্ট করুন আর বুকিং থাকা প্রতিটি পরিবার তা নিজের অ্যাপে দেখে, ছোট অনুস্মারক থেকে আরএসভিপি-সহ ইভেন্ট বা জরুরি বন্ধ পর্যন্ত।", "هذا هو آخر الأخبار لديك — انشر تحديثًا وستراه كل عائلة لديها حجز في تطبيقها، من تذكير سريع إلى فعالية بردود حضور أو إغلاق طارئ.", "Estas são as suas Novidades — publique uma atualização e cada família com uma reserva vê-a na sua própria aplicação, desde um lembrete rápido a um evento com respostas ou um encerramento urgente.", "Este es tu Tablón de novedades: publica una actualización y cada familia con una reserva la verá en su propia aplicación, desde un recordatorio rápido hasta un evento con confirmaciones o un cierre urgente.", "Voici votre Fil d’actualité : publiez une nouveauté et chaque famille ayant une réservation la voit dans sa propre appli, d’un simple rappel à un événement avec réponses ou une fermeture urgente.", "Dyma’ch Ffrwd newyddion — postiwch ddiweddariad a bydd pob teulu ag archeb yn ei weld yn eu hap eu hunain, o nodyn atgoffa cyflym i ddigwyddiad gydag atebion neu gau brys."],
  "lt_newsfeed_s1": ["Everything starts with a template. The type you pick sets the card's colour, its fields and its defaults — so Urgent auto-pins and asks for an acknowledgement, while a Booking nudge adds a Book now button.", "Wszystko zaczyna się od szablonu. Wybrany typ określa kolor karty, pola i ustawienia domyślne — Pilne przypina się samo i prosi o potwierdzenie przeczytania, a Zachęta do rezerwacji dodaje przycisk Zarezerwuj teraz.", "Totul începe cu un șablon. Tipul ales stabilește culoarea cardului, câmpurile și valorile implicite — așa că Urgent se fixează automat și cere confirmare, iar o Invitație la rezervare adaugă un buton Rezervă acum.", "سب کچھ ایک ٹیمپلیٹ سے شروع ہوتا ہے۔ آپ کی چنی ہوئی قسم کارڈ کا رنگ، اس کے خانے اور ڈیفالٹس طے کرتی ہے — اس لیے فوری خود بخود اوپر لگ جاتا ہے اور تصدیق مانگتا ہے، جبکہ بکنگ کی یاد دہانی اب بک کریں کا بٹن جوڑتی ہے۔", "ਸਭ ਕੁਝ ਇੱਕ ਟੈਮਪਲੇਟ ਨਾਲ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ। ਤੁਹਾਡੀ ਚੁਣੀ ਕਿਸਮ ਕਾਰਡ ਦਾ ਰੰਗ, ਉਸ ਦੇ ਖਾਨੇ ਅਤੇ ਡਿਫ਼ਾਲਟ ਤੈਅ ਕਰਦੀ ਹੈ — ਇਸ ਲਈ ਫੌਰੀ ਆਪਣੇ ਆਪ ਉੱਪਰ ਪਿੰਨ ਹੋ ਜਾਂਦਾ ਹੈ ਅਤੇ ਪੁਸ਼ਟੀ ਮੰਗਦਾ ਹੈ, ਜਦਕਿ ਬੁਕਿੰਗ ਯਾਦ-ਦਹਾਨੀ ਹੁਣੇ ਬੁੱਕ ਕਰੋ ਬਟਨ ਜੋੜਦੀ ਹੈ।", "সবকিছু শুরু হয় একটি টেমপ্লেট দিয়ে। আপনার বাছা ধরন কার্ডের রং, তার ঘর ও ডিফল্ট ঠিক করে — তাই জরুরি নিজে থেকে পিন হয় ও স্বীকৃতি চায়, আর বুকিং নাজ এখনই বুক করুন বোতাম যোগ করে।", "كل شيء يبدأ بقالب. النوع الذي تختاره يحدد لون البطاقة وحقولها وإعداداتها الافتراضية — فالعاجل يُثبَّت تلقائيًا ويطلب إقرارًا بالاطلاع، أما تذكير الحجز فيضيف زر احجز الآن.", "Tudo começa com um modelo. O tipo que escolher define a cor do cartão, os campos e os valores predefinidos — assim o Urgente fixa-se sozinho e pede confirmação de leitura, enquanto um Incentivo à reserva junta um botão Reservar agora.", "Todo empieza con una plantilla. El tipo que elijas define el color de la tarjeta, sus campos y sus valores por defecto: así, Urgente se fija solo y pide confirmación de lectura, mientras que un Empujón de reserva añade un botón Reservar ahora.", "Tout commence par un modèle. Le type choisi définit la couleur de la carte, ses champs et ses valeurs par défaut — ainsi Urgent s’épingle tout seul et demande un accusé de lecture, tandis qu’un Coup de pouce réservation ajoute un bouton Réserver maintenant.", "Mae popeth yn dechrau gyda thempled. Mae’r math a ddewiswch yn gosod lliw’r cerdyn, ei feysydd a’i ragosodiadau — felly mae Brys yn pinio’n awtomatig ac yn gofyn am gydnabyddiaeth, tra bod Hwb archebu yn ychwanegu botwm Archebu nawr."],
  "lt_newsfeed_s2": ["To add one, you press Event, and this form opens.", "Aby dodać wydarzenie, naciskasz Wydarzenie i otwiera się ten formularz.", "Ca să adaugi unul, apeși Eveniment și se deschide acest formular.", "نیا شامل کرنے کے لیے آپ ایونٹ دباتے ہیں، اور یہ فارم کھل جاتا ہے۔", "ਇੱਕ ਜੋੜਨ ਲਈ ਤੁਸੀਂ ਸਮਾਗਮ ਦਬਾਉਂਦੇ ਹੋ, ਅਤੇ ਇਹ ਫਾਰਮ ਖੁੱਲ੍ਹ ਜਾਂਦਾ ਹੈ।", "একটি যোগ করতে আপনি ইভেন্ট চাপেন, আর এই ফর্মটি খুলে যায়।", "لإضافة واحدة تضغط على فعالية فيُفتح هذا النموذج.", "Para adicionar uma, prime Evento e este formulário abre-se.", "Para añadir una, pulsas Evento y se abre este formulario.", "Pour en ajouter une, vous appuyez sur Événement et ce formulaire s’ouvre.", "I ychwanegu un, pwyswch Digwyddiad ac mae’r ffurflen hon yn agor."],
  "lt_newsfeed_s3": ["Give it a title and a message — here, a Summer Sports Day for the families. Or drop a rough note into Help me write and the AI drafts it for you.", "Nadaj tytuł i treść — tu Letni Dzień Sportu dla rodzin. Możesz też wpisać szkic w Pomóż mi napisać, a AI przygotuje tekst za Ciebie.", "Dă-i un titlu și un mesaj — aici, o Zi Sportivă de Vară pentru familii. Sau scrie o notă aproximativă în Ajută-mă să scriu, iar AI-ul o redactează pentru tine.", "اسے ایک عنوان اور پیغام دیں — یہاں خاندانوں کے لیے گرمیوں کا سپورٹس ڈے۔ یا مدد کریں لکھنے میں میں ایک کچا نوٹ ڈال دیں اور اے آئی اسے آپ کے لیے لکھ دیتا ہے۔", "ਇਸਨੂੰ ਇੱਕ ਸਿਰਲੇਖ ਅਤੇ ਸੁਨੇਹਾ ਦਿਓ — ਇੱਥੇ ਪਰਿਵਾਰਾਂ ਲਈ ਗਰਮੀਆਂ ਦਾ ਸਪੋਰਟਸ ਡੇ। ਜਾਂ ਲਿਖਣ ਵਿੱਚ ਮੇਰੀ ਮਦਦ ਕਰੋ ਵਿੱਚ ਇੱਕ ਮੋਟਾ ਨੋਟ ਪਾਓ ਅਤੇ AI ਤੁਹਾਡੇ ਲਈ ਇਸ ਦਾ ਖਰੜਾ ਬਣਾ ਦਿੰਦਾ ਹੈ।", "একটি শিরোনাম ও বার্তা দিন — এখানে পরিবারগুলোর জন্য সামার স্পোর্টস ডে। অথবা লিখতে সাহায্য করুনে একটি মোটামুটি নোট দিন, আর এআই আপনার জন্য খসড়া করে দেবে।", "امنحها عنوانًا ورسالة — هنا يوم رياضي صيفي للعائلات. أو اكتب ملاحظة أولية في ساعدني في الكتابة ويصوغها الذكاء الاصطناعي لك.", "Dê-lhe um título e uma mensagem — aqui, um Dia de Desporto de Verão para as famílias. Ou escreva uma nota rápida em Ajude-me a escrever e a IA redige-a por si.", "Dale un título y un mensaje: aquí, un Día del Deporte de verano para las familias. O deja una nota rápida en Ayúdame a escribir y la IA te la redacta.", "Donnez-lui un titre et un message — ici, une Journée sportive d’été pour les familles. Ou déposez une note rapide dans Aidez-moi à écrire et l’IA la rédige pour vous.", "Rhowch deitl a neges iddo — yma, Diwrnod Chwaraeon Haf i’r teuluoedd. Neu gollyngwch nodyn bras yn Helpwch fi i ysgrifennu a bydd yr AI yn ei ddrafftio i chi."],
  "lt_newsfeed_s4": ["Because it's an event, you add the details — the 28th of August at ten o'clock on Meadow Park — and they show right on the card families see.", "Skoro to wydarzenie, dodajesz szczegóły — 28 sierpnia o dziesiątej w Meadow Park — i pokazują się one na karcie, którą widzą rodziny.", "Fiindcă este un eveniment, adaugi detaliile — 28 august, ora zece, la Meadow Park — și apar chiar pe cardul pe care îl văd familiile.", "چونکہ یہ ایک ایونٹ ہے، آپ تفصیلات ڈالتے ہیں — اٹھائیس اگست، دس بجے، میڈو پارک — اور وہ اسی کارڈ پر دکھائی دیتی ہیں جو خاندان دیکھتے ہیں۔", "ਕਿਉਂਕਿ ਇਹ ਇੱਕ ਸਮਾਗਮ ਹੈ, ਤੁਸੀਂ ਵੇਰਵੇ ਪਾਉਂਦੇ ਹੋ — ਅਠਾਈ ਅਗਸਤ, ਦਸ ਵਜੇ, ਮੀਡੋ ਪਾਰਕ — ਅਤੇ ਉਹ ਉਸੇ ਕਾਰਡ ਉੱਤੇ ਦਿਸਦੇ ਹਨ ਜੋ ਪਰਿਵਾਰ ਦੇਖਦੇ ਹਨ।", "যেহেতু এটি একটি ইভেন্ট, আপনি বিবরণ যোগ করেন — আটাশে আগস্ট, সকাল দশটায়, মিডো পার্কে — আর সেগুলি পরিবারগুলোর দেখা কার্ডেই দেখা যায়।", "وبما أنها فعالية، تضيف التفاصيل — الثامن والعشرين من أغسطس في العاشرة صباحًا في ميدو بارك — وتظهر مباشرة على البطاقة التي تراها العائلات.", "Por ser um evento, acrescenta os detalhes — 28 de agosto, às dez horas, no Meadow Park — e aparecem logo no cartão que as famílias veem.", "Como es un evento, añades los detalles (el 28 de agosto a las diez en Meadow Park) y aparecen justo en la tarjeta que ven las familias.", "Comme c’est un événement, vous ajoutez les détails — le 28 août à dix heures à Meadow Park — et ils s’affichent sur la carte que voient les familles.", "Gan ei fod yn ddigwyddiad, rydych yn ychwanegu’r manylion — yr wythfed ar hugain o Awst am ddeg o’r gloch ym Meadow Park — ac maent yn dangos ar y cerdyn y mae teuluoedd yn ei weld."],
  "lt_newsfeed_s5": ["Then you choose who's notified — all families or just chosen listings' parents — and flip the toggles that pin it to the top and let families react.", "Potem wybierasz, kogo powiadomić — wszystkie rodziny lub tylko rodziców wybranych ofert — i przełączasz opcje przypięcia na górze oraz reagowania przez rodziny.", "Apoi alegi cine e notificat — toate familiile sau doar părinții ofertelor alese — și activezi comutatoarele care îl fixează sus și permit familiilor să reacționeze.", "پھر آپ چنتے ہیں کہ کسے اطلاع ملے — تمام خاندان یا صرف چنی ہوئی لسٹنگز کے والدین — اور وہ سوئچ آن کرتے ہیں جو اسے اوپر پِن کرتے ہیں اور خاندانوں کو ردعمل دینے دیتے ہیں۔", "ਫਿਰ ਤੁਸੀਂ ਚੁਣਦੇ ਹੋ ਕਿ ਕਿਸ ਨੂੰ ਸੂਚਨਾ ਮਿਲੇ — ਸਾਰੇ ਪਰਿਵਾਰ ਜਾਂ ਸਿਰਫ਼ ਚੁਣੀਆਂ ਲਿਸਟਿੰਗਾਂ ਦੇ ਮਾਪੇ — ਅਤੇ ਉਹ ਸਵਿੱਚ ਚਾਲੂ ਕਰਦੇ ਹੋ ਜੋ ਇਸਨੂੰ ਸਿਖਰ ਉੱਤੇ ਪਿੰਨ ਕਰਦੇ ਹਨ ਅਤੇ ਪਰਿਵਾਰਾਂ ਨੂੰ ਪ੍ਰਤੀਕਿਰਿਆ ਦੇਣ ਦਿੰਦੇ ਹਨ।", "তারপর আপনি বেছে নেন কাকে জানানো হবে — সব পরিবার বা শুধু নির্বাচিত লিস্টিংয়ের অভিভাবকদের — আর সেই সুইচগুলো চালু করেন যা এটিকে উপরে পিন করে ও পরিবারগুলোকে প্রতিক্রিয়া জানাতে দেয়।", "ثم تختار من يُخطَر — كل العائلات أو أولياء أمور إعلانات محددة فقط — وتشغّل المفاتيح التي تثبّته في الأعلى وتتيح للعائلات التفاعل.", "Depois escolhe quem é notificado — todas as famílias ou só os pais de anúncios selecionados — e ativa os interruptores que o fixam no topo e deixam as famílias reagir.", "Luego eliges a quién se notifica (todas las familias o solo los padres de anuncios concretos) y activas los interruptores que lo fijan arriba y dejan que las familias reaccionen.", "Ensuite, vous choisissez qui est notifié — toutes les familles ou seulement les parents d’annonces choisies — et activez les commutateurs qui l’épinglent en haut et laissent les familles réagir.", "Yna dewiswch pwy sy’n cael ei hysbysu — pob teulu neu rieni rhestriadau dethol yn unig — a throi’r togiau sy’n ei binio ar y brig ac yn gadael i deuluoedd ymateb."],
  "lt_newsfeed_s6": ["Name it for your own search and file it in a folder, so you can find it again next year. Families never see this bit.", "Nazwij wpis dla własnego wyszukiwania i umieść go w folderze, żeby znaleźć go za rok. Rodziny nigdy tego nie widzą.", "Dă-i un nume pentru propria căutare și pune-l într-un dosar, ca să-l găsești la anul. Familiile nu văd niciodată această parte.", "اسے اپنی تلاش کے لیے نام دیں اور کسی فولڈر میں رکھیں تاکہ اگلے سال دوبارہ مل جائے۔ خاندان یہ حصہ کبھی نہیں دیکھتے۔", "ਇਸਨੂੰ ਆਪਣੀ ਖੋਜ ਲਈ ਨਾਮ ਦਿਓ ਅਤੇ ਕਿਸੇ ਫੋਲਡਰ ਵਿੱਚ ਰੱਖੋ, ਤਾਂ ਜੋ ਅਗਲੇ ਸਾਲ ਦੁਬਾਰਾ ਮਿਲ ਜਾਵੇ। ਪਰਿਵਾਰ ਇਹ ਹਿੱਸਾ ਕਦੇ ਨਹੀਂ ਦੇਖਦੇ।", "নিজের খোঁজার জন্য একটি নাম দিন এবং একটি ফোল্ডারে রাখুন, যাতে আগামী বছর আবার খুঁজে পান। পরিবারগুলো এই অংশ কখনও দেখে না।", "سمِّه ليسهل عليك البحث عنه وضعه في مجلد، لتجده من جديد في العام القادم. العائلات لا ترى هذا الجزء أبدًا.", "Dê-lhe um nome para a sua própria pesquisa e guarde-o numa pasta, para o encontrar no próximo ano. As famílias nunca veem esta parte.", "Ponle un nombre para tu propia búsqueda y archívalo en una carpeta, para encontrarlo el año que viene. Las familias nunca ven esta parte.", "Donnez-lui un nom pour votre propre recherche et classez-le dans un dossier, pour le retrouver l’an prochain. Les familles ne voient jamais cette partie.", "Enwch ef ar gyfer eich chwiliad eich hun a’i ffeilio mewn ffolder, fel y gallwch ddod o hyd iddo eto’r flwyddyn nesaf. Nid yw teuluoedd byth yn gweld y rhan hon."],
  "lt_newsfeed_s7": ["And when you press Post to Newsfeed you get a five-second countdown, then it goes live to every family — you can also send the same post as an image, a printable PDF, or an email instead.", "Gdy naciśniesz Opublikuj w Aktualnościach, zobaczysz pięciosekundowe odliczanie, a potem wpis trafia do każdej rodziny — możesz go też wysłać jako obraz, PDF do wydruku albo e-mail.", "Când apeși Postează în Noutăți, apare o numărătoare inversă de cinci secunde, apoi postarea merge live la toate familiile — o poți trimite și ca imagine, PDF imprimabil sau e-mail.", "جب آپ نیوز فیڈ میں پوسٹ کریں دباتے ہیں تو پانچ سیکنڈ کی الٹی گنتی چلتی ہے، پھر یہ ہر خاندان کے لیے لائیو ہو جاتا ہے — آپ اسی پوسٹ کو تصویر، پرنٹ کے قابل پی ڈی ایف یا ای میل کے طور پر بھی بھیج سکتے ہیں۔", "ਜਦੋਂ ਤੁਸੀਂ ਨਿਊਜ਼ਫੀਡ ਵਿੱਚ ਪੋਸਟ ਕਰੋ ਦਬਾਉਂਦੇ ਹੋ ਤਾਂ ਪੰਜ ਸਕਿੰਟ ਦੀ ਉਲਟੀ ਗਿਣਤੀ ਚੱਲਦੀ ਹੈ, ਫਿਰ ਇਹ ਹਰ ਪਰਿਵਾਰ ਲਈ ਲਾਈਵ ਹੋ ਜਾਂਦੀ ਹੈ — ਤੁਸੀਂ ਇਹੀ ਪੋਸਟ ਤਸਵੀਰ, ਛਾਪਣ ਯੋਗ PDF ਜਾਂ ਈਮੇਲ ਵਜੋਂ ਵੀ ਭੇਜ ਸਕਦੇ ਹੋ।", "আপনি নিউজফিডে পোস্ট করুন চাপলে পাঁচ সেকেন্ডের কাউন্টডাউন চলে, তারপর তা প্রতিটি পরিবারের কাছে লাইভ হয় — একই পোস্ট ছবি, প্রিন্টযোগ্য পিডিএফ বা ইমেইল হিসেবেও পাঠাতে পারেন।", "عندما تضغط نشر في آخر الأخبار يبدأ عدّ تنازلي لخمس ثوانٍ ثم يُنشر مباشرة لكل عائلة — ويمكنك أيضًا إرسال المنشور نفسه كصورة أو ملف PDF قابل للطباعة أو بريد إلكتروني.", "Quando prime Publicar nas Novidades aparece uma contagem decrescente de cinco segundos e depois fica disponível para todas as famílias — também pode enviar a mesma publicação como imagem, PDF para imprimir ou e-mail.", "Cuando pulsas Publicar en Novedades ves una cuenta atrás de cinco segundos y luego se publica para todas las familias; también puedes enviar la misma publicación como imagen, PDF imprimible o correo.", "Quand vous appuyez sur Publier dans le Fil d’actualité, un compte à rebours de cinq secondes s’affiche, puis elle passe en ligne pour toutes les familles — vous pouvez aussi envoyer la même publication sous forme d’image, de PDF imprimable ou d’e-mail.", "Pan bwyswch Postio i’r Ffrwd newyddion cewch gyfrif i lawr o bum eiliad, yna mae’n mynd yn fyw i bob teulu — gallwch hefyd anfon yr un postiad fel delwedd, PDF argraffadwy neu e-bost."],
  "lt_tasks_title": ["Task manager", "Menedżer zadań", "Manager de sarcini", "ٹاسک مینیجر", "ਕਾਰਜ ਪ੍ਰਬੰਧਕ", "টাস্ক ম্যানেজার", "مدير المهام", "Gestor de tarefas", "Gestor de tareas", "Gestionnaire de tâches", "Rheolwr tasgau"],
  "lt_tasks_intro": ["Welcome to your Task manager — proper to-dos tied to real listings, bookings and compliance, all in one tidy inbox.", "Witaj w Menedżerze zadań — prawdziwe listy rzeczy do zrobienia powiązane z ofertami, rezerwacjami i zgodnością, wszystko w jednej przejrzystej skrzynce.", "Bun venit în Managerul de sarcini — liste de treburi reale, legate de oferte, rezervări și conformitate, toate într-o singură căsuță ordonată.", "ٹاسک مینیجر میں خوش آمدید — اصل لسٹنگز، بکنگز اور تعمیل سے جڑے کام، سب ایک صاف ستھرے ان باکس میں۔", "ਕਾਰਜ ਪ੍ਰਬੰਧਕ ਵਿੱਚ ਜੀ ਆਇਆਂ ਨੂੰ — ਅਸਲ ਲਿਸਟਿੰਗਾਂ, ਬੁਕਿੰਗਾਂ ਅਤੇ ਪਾਲਣਾ ਨਾਲ ਜੁੜੇ ਕੰਮ, ਸਭ ਇੱਕ ਸਾਫ਼-ਸੁਥਰੇ ਇਨਬਾਕਸ ਵਿੱਚ।", "টাস্ক ম্যানেজারে স্বাগতম — আসল লিস্টিং, বুকিং ও সম্মতির সঙ্গে যুক্ত করণীয় তালিকা, সব একটি গোছানো ইনবক্সে।", "مرحبًا بك في مدير المهام — قوائم مهام حقيقية مرتبطة بالإعلانات والحجوزات والامتثال، كلها في صندوق وارد واحد مرتب.", "Bem-vindo ao Gestor de tarefas — listas de tarefas a sério, ligadas a anúncios, reservas e conformidade, tudo numa única caixa arrumada.", "Te damos la bienvenida al Gestor de tareas: pendientes de verdad ligados a anuncios, reservas y cumplimiento, todo en una bandeja ordenada.", "Bienvenue dans le Gestionnaire de tâches — de vraies listes de choses à faire liées aux annonces, aux réservations et à la conformité, dans une seule boîte bien rangée.", "Croeso i’ch Rheolwr tasgau — rhestrau i’w gwneud go iawn sydd ynghlwm wrth restriadau, archebion a chydymffurfiaeth, i gyd mewn un mewnflwch taclus."],
  "lt_tasks_done": ["Capture it, tick it off, and never lose track of what's due across all your gigs.", "Zapisz, odhacz i nigdy nie trać z oczu, co jest do zrobienia w całej Twojej działalności.", "Notează, bifează și nu mai pierde niciodată șirul a ceea ce e de făcut în toată activitatea ta.", "درج کریں، نشان لگائیں، اور اپنے تمام کاموں میں کبھی نہ بھولیں کہ کیا کرنا باقی ہے۔", "ਦਰਜ ਕਰੋ, ਨਿਸ਼ਾਨ ਲਗਾਓ, ਅਤੇ ਆਪਣੇ ਸਾਰੇ ਕੰਮਾਂ ਵਿੱਚ ਕਦੇ ਨਾ ਭੁੱਲੋ ਕਿ ਕੀ ਕਰਨਾ ਬਾਕੀ ਹੈ।", "লিখে রাখুন, টিক দিন, আর আপনার সব কাজে কী বাকি আছে তা কখনও হারাবেন না।", "دوّنها، وأنجزها، ولا تفقد أبدًا متابعة ما هو مستحق في كل أعمالك.", "Registe, marque como feito e nunca perca o rasto do que está por fazer em toda a sua atividade.", "Anótalo, tíchalo y no pierdas nunca el hilo de lo que toca hacer en todo tu trabajo.", "Notez-la, cochez-la et ne perdez plus jamais le fil de ce qu’il y a à faire dans toute votre activité.", "Cofnodwch, ticiwch a pheidiwch byth â cholli trac ar yr hyn sy’n ddyledus ar draws eich holl waith."],
  "lt_tasks_s0": ["A row of cards up top shows your whole workload at a glance — tap any one to filter the list below.", "Rząd kart na górze pokazuje całe Twoje obciążenie w skrócie — dotknij dowolnej, aby przefiltrować listę poniżej.", "Un rând de carduri sus îți arată întreaga încărcare dintr-o privire — atinge oricare ca să filtrezi lista de dedesubt.", "اوپر کارڈز کی ایک قطار آپ کا سارا کام ایک نظر میں دکھاتی ہے — نیچے کی فہرست کو فلٹر کرنے کے لیے کسی پر بھی ٹیپ کریں۔", "ਉੱਪਰ ਕਾਰਡਾਂ ਦੀ ਇੱਕ ਕਤਾਰ ਤੁਹਾਡਾ ਸਾਰਾ ਕੰਮ ਇੱਕ ਨਜ਼ਰ ਵਿੱਚ ਦਿਖਾਉਂਦੀ ਹੈ — ਹੇਠਲੀ ਸੂਚੀ ਨੂੰ ਫਿਲਟਰ ਕਰਨ ਲਈ ਕਿਸੇ ਉੱਤੇ ਵੀ ਟੈਪ ਕਰੋ।", "উপরে কার্ডের একটি সারি আপনার পুরো কাজের চাপ এক নজরে দেখায় — নিচের তালিকা ফিল্টার করতে যেকোনোটিতে ট্যাপ করুন।", "صف من البطاقات في الأعلى يعرض كل أعبائك في لمحة — اضغط على أي واحدة لتصفية القائمة أسفلها.", "Uma fila de cartões no topo mostra toda a sua carga de trabalho num relance — toque em qualquer um para filtrar a lista abaixo.", "Una fila de tarjetas arriba muestra toda tu carga de trabajo de un vistazo: toca cualquiera para filtrar la lista de abajo.", "Une rangée de cartes en haut montre toute votre charge de travail en un coup d’œil — touchez-en une pour filtrer la liste en dessous.", "Mae rhes o gardiau ar y brig yn dangos eich llwyth gwaith i gyd ar un olwg — tapiwch unrhyw un i hidlo’r rhestr isod."],
  "lt_tasks_s1": ["The heart of the page — your tasks grouped into Overdue, Today and Upcoming, each row showing who it's for and when it's due.", "Serce strony — zadania pogrupowane na Zaległe, Dzisiejsze i Nadchodzące, a każdy wiersz pokazuje, dla kogo jest i na kiedy.", "Inima paginii — sarcinile tale grupate în Întârziate, Azi și Viitoare, fiecare rând arătând pentru cine e și când scade.", "صفحے کا دل — آپ کے کام تاخیر شدہ، آج اور آئندہ میں بٹے ہوئے، ہر قطار دکھاتی ہے کہ یہ کس کے لیے ہے اور کب تک ہے۔", "ਪੰਨੇ ਦਾ ਦਿਲ — ਤੁਹਾਡੇ ਕੰਮ ਪਛੜੇ, ਅੱਜ ਅਤੇ ਆਉਣ ਵਾਲੇ ਵਿੱਚ ਵੰਡੇ ਹੋਏ, ਹਰ ਕਤਾਰ ਦੱਸਦੀ ਹੈ ਕਿ ਇਹ ਕਿਸ ਲਈ ਹੈ ਅਤੇ ਕਦੋਂ ਤੱਕ।", "পাতার প্রাণকেন্দ্র — আপনার কাজগুলো মেয়াদোত্তীর্ণ, আজ ও আসন্নে ভাগ করা, প্রতিটি সারিতে দেখা যায় এটি কার জন্য ও কবে শেষ।", "قلب الصفحة — مهامك مجمّعة في متأخرة واليوم والقادمة، وكل صف يبيّن لمن هي ومتى موعدها.", "O coração da página — as suas tarefas agrupadas em Em atraso, Hoje e Próximas, cada linha mostrando para quem é e quando termina.", "El corazón de la página: tus tareas agrupadas en Vencidas, Hoy y Próximas, y cada fila muestra para quién es y cuándo vence.", "Le cœur de la page — vos tâches regroupées en En retard, Aujourd’hui et À venir, chaque ligne indiquant pour qui elle est et pour quand.", "Calon’r dudalen — eich tasgau wedi’u grwpio’n Hwyr, Heddiw ac Ar y gweill, pob rhes yn dangos i bwy mae a phryd mae’n ddyledus."],
  "lt_tasks_s2": ["Flip to the Board to drag tasks between columns, or click any row to open it and add subtasks and comments.", "Przejdź na Tablicę, aby przeciągać zadania między kolumnami, albo kliknij dowolny wiersz, by go otworzyć i dodać podzadania oraz komentarze.", "Treci la Tablă ca să tragi sarcinile între coloane sau fă clic pe orice rând ca să-l deschizi și să adaugi subsarcini și comentarii.", "بورڈ پر جائیں تاکہ کاموں کو کالموں کے درمیان گھسیٹ سکیں، یا کسی بھی قطار پر کلک کر کے اسے کھولیں اور ذیلی کام اور تبصرے شامل کریں۔", "ਬੋਰਡ ਉੱਤੇ ਜਾਓ ਤਾਂ ਜੋ ਕੰਮਾਂ ਨੂੰ ਕਾਲਮਾਂ ਵਿਚਕਾਰ ਘਸੀਟ ਸਕੋ, ਜਾਂ ਕਿਸੇ ਵੀ ਕਤਾਰ ਉੱਤੇ ਕਲਿੱਕ ਕਰਕੇ ਉਸਨੂੰ ਖੋਲ੍ਹੋ ਅਤੇ ਉਪ-ਕੰਮ ਤੇ ਟਿੱਪਣੀਆਂ ਜੋੜੋ।", "বোর্ডে যান, কাজগুলো কলামের মধ্যে টেনে আনতে, অথবা যেকোনো সারিতে ক্লিক করে তা খুলে সাব-টাস্ক ও মন্তব্য যোগ করুন।", "انتقل إلى اللوحة لتسحب المهام بين الأعمدة، أو انقر على أي صف لفتحه وإضافة مهام فرعية وتعليقات.", "Mude para o Quadro para arrastar tarefas entre colunas, ou clique em qualquer linha para a abrir e juntar subtarefas e comentários.", "Cambia al Tablero para arrastrar tareas entre columnas, o haz clic en cualquier fila para abrirla y añadir subtareas y comentarios.", "Passez au Tableau pour glisser les tâches d’une colonne à l’autre, ou cliquez sur une ligne pour l’ouvrir et ajouter des sous-tâches et des commentaires.", "Newidiwch i’r Bwrdd i lusgo tasgau rhwng colofnau, neu cliciwch unrhyw res i’w hagor ac ychwanegu is-dasgau a sylwadau."],
  "lt_tasks_s3": ["The fastest way to add one — type it in plain English. An at-sign assigns it, an exclamation mark sets the priority, and a hash links a booking or family.", "Najszybszy sposób dodania zadania — wpisz je zwykłym językiem. Małpa przypisuje, wykrzyknik ustawia priorytet, a hasz łączy rezerwację lub rodzinę.", "Cea mai rapidă metodă de a adăuga una — scrie-o în limbaj obișnuit. Semnul @ o atribuie, semnul exclamării setează prioritatea, iar diezul leagă o rezervare sau o familie.", "نیا کام شامل کرنے کا تیز ترین طریقہ — اسے سادہ زبان میں لکھیں۔ ایٹ کا نشان اسے تفویض کرتا ہے، فجائیہ نشان ترجیح طے کرتا ہے، اور ہیش کسی بکنگ یا خاندان سے جوڑتا ہے۔", "ਇੱਕ ਜੋੜਨ ਦਾ ਸਭ ਤੋਂ ਤੇਜ਼ ਤਰੀਕਾ — ਇਸਨੂੰ ਆਮ ਭਾਸ਼ਾ ਵਿੱਚ ਲਿਖੋ। @ ਦਾ ਨਿਸ਼ਾਨ ਇਸਨੂੰ ਸੌਂਪਦਾ ਹੈ, ਵਿਸਮਿਕ ਚਿੰਨ੍ਹ ਤਰਜੀਹ ਤੈਅ ਕਰਦਾ ਹੈ, ਅਤੇ ਹੈਸ਼ ਕਿਸੇ ਬੁਕਿੰਗ ਜਾਂ ਪਰਿਵਾਰ ਨਾਲ ਜੋੜਦਾ ਹੈ।", "একটি যোগ করার সবচেয়ে দ্রুত উপায় — সহজ ভাষায় লিখে ফেলুন। অ্যাট চিহ্ন দায়িত্ব দেয়, বিস্ময়বোধক চিহ্ন অগ্রাধিকার ঠিক করে, আর হ্যাশ কোনো বুকিং বা পরিবারকে যুক্ত করে।", "أسرع طريقة لإضافة واحدة — اكتبها بلغة عادية. علامة @ تُسنِدها، وعلامة التعجب تحدد الأولوية، وعلامة # تربط حجزًا أو عائلة.", "A forma mais rápida de adicionar uma — escreva-a em linguagem simples. O arroba atribui, o ponto de exclamação define a prioridade e o cardinal liga uma reserva ou família.", "La forma más rápida de añadir una: escríbela en lenguaje normal. La arroba la asigna, el signo de exclamación fija la prioridad y la almohadilla enlaza una reserva o familia.", "La façon la plus rapide d’en ajouter une : tapez-la en langage courant. L’arobase l’assigne, le point d’exclamation fixe la priorité et le dièse relie une réservation ou une famille.", "Y ffordd gyflymaf o ychwanegu un — teipiwch hi mewn Cymraeg plaen. Mae’r arwydd at yn ei neilltuo, mae’r ebychnod yn gosod y flaenoriaeth, ac mae’r hash yn cysylltu archeb neu deulu."],
  "lt_tasks_s4": ["Or press New task for the full form.", "Albo naciśnij Nowe zadanie, aby otworzyć pełny formularz.", "Sau apasă Sarcină nouă pentru formularul complet.", "یا مکمل فارم کے لیے نیا کام دبائیں۔", "ਜਾਂ ਪੂਰੇ ਫਾਰਮ ਲਈ ਨਵਾਂ ਕੰਮ ਦਬਾਓ।", "অথবা পুরো ফর্মের জন্য নতুন টাস্ক চাপুন।", "أو اضغط مهمة جديدة للنموذج الكامل.", "Ou prima Nova tarefa para o formulário completo.", "O pulsa Nueva tarea para el formulario completo.", "Ou appuyez sur Nouvelle tâche pour le formulaire complet.", "Neu pwyswch Tasg newydd i gael y ffurflen lawn."],
  "lt_tasks_s5": ["Set who it's for, a priority and a deadline, link it to the real booking or child, then save — it lands in the list straight away.", "Wskaż, dla kogo jest, priorytet i termin, powiąż z prawdziwą rezerwacją lub dzieckiem, a potem zapisz — trafia od razu na listę.", "Setează pentru cine este, prioritatea și termenul, leag-o de rezervarea sau copilul real, apoi salvează — apare imediat în listă.", "طے کریں کہ یہ کس کے لیے ہے، ترجیح اور آخری تاریخ، اسے اصل بکنگ یا بچے سے جوڑیں، پھر محفوظ کریں — یہ فوراً فہرست میں آ جاتا ہے۔", "ਤੈਅ ਕਰੋ ਕਿ ਇਹ ਕਿਸ ਲਈ ਹੈ, ਤਰਜੀਹ ਅਤੇ ਆਖ਼ਰੀ ਤਾਰੀਖ਼, ਇਸਨੂੰ ਅਸਲ ਬੁਕਿੰਗ ਜਾਂ ਬੱਚੇ ਨਾਲ ਜੋੜੋ, ਫਿਰ ਸੰਭਾਲੋ — ਇਹ ਤੁਰੰਤ ਸੂਚੀ ਵਿੱਚ ਆ ਜਾਂਦਾ ਹੈ।", "কার জন্য, অগ্রাধিকার ও শেষ তারিখ ঠিক করুন, আসল বুকিং বা শিশুর সঙ্গে যুক্ত করুন, তারপর সংরক্ষণ করুন — এটি সঙ্গে সঙ্গে তালিকায় চলে আসে।", "حدّد لمن هي، والأولوية والموعد النهائي، واربطها بالحجز أو الطفل الفعلي، ثم احفظ — فتظهر في القائمة فورًا.", "Defina para quem é, a prioridade e o prazo, ligue-a à reserva ou criança em causa e guarde — fica logo na lista.", "Indica para quién es, la prioridad y la fecha límite, enlázala con la reserva o el niño real y guarda: aparece en la lista al instante.", "Indiquez pour qui elle est, la priorité et l’échéance, reliez-la à la réservation ou à l’enfant concerné, puis enregistrez — elle arrive aussitôt dans la liste.", "Gosodwch i bwy mae, blaenoriaeth a therfyn amser, cysylltwch hi â’r archeb neu’r plentyn go iawn, yna cadwch — mae’n glanio yn y rhestr ar unwaith."],
  "lt_referrals_title": ["Referrals", "Polecenia", "Recomandări", "ریفرلز", "ਰੈਫ਼ਰਲ", "রেফারেল", "الإحالات", "Indicações", "Referidos", "Parrainages", "Atgyfeiriadau"],
  "lt_referrals_intro": ["Welcome to your referrals scoreboard — a live read-out of the families bringing you new bookings, what those bookings are worth, and what the rewards cost.", "Witaj w tablicy wyników poleceń — na żywo widać rodziny, które przyprowadzają nowe rezerwacje, ile te rezerwacje są warte i ile kosztują nagrody.", "Bun venit la tabloul tău de recomandări — o imagine live a familiilor care îți aduc rezervări noi, cât valorează acestea și cât costă recompensele.", "ریفرلز کے اسکور بورڈ میں خوش آمدید — ان خاندانوں کا لائیو جائزہ جو آپ کے لیے نئی بکنگز لا رہے ہیں، ان بکنگز کی قدر، اور انعامات کی لاگت۔", "ਰੈਫ਼ਰਲ ਸਕੋਰਬੋਰਡ ਵਿੱਚ ਜੀ ਆਇਆਂ ਨੂੰ — ਉਨ੍ਹਾਂ ਪਰਿਵਾਰਾਂ ਦੀ ਲਾਈਵ ਝਲਕ ਜੋ ਤੁਹਾਡੇ ਲਈ ਨਵੀਆਂ ਬੁਕਿੰਗਾਂ ਲਿਆ ਰਹੇ ਹਨ, ਉਨ੍ਹਾਂ ਬੁਕਿੰਗਾਂ ਦੀ ਕੀਮਤ, ਅਤੇ ਇਨਾਮਾਂ ਦੀ ਲਾਗਤ।", "রেফারেল স্কোরবোর্ডে স্বাগতম — যেসব পরিবার আপনার জন্য নতুন বুকিং আনছে তাদের লাইভ চিত্র, সেই বুকিংয়ের মূল্য, আর পুরস্কারের খরচ।", "مرحبًا بك في لوحة نتائج الإحالات — عرض مباشر للعائلات التي تجلب لك حجوزات جديدة، وقيمة تلك الحجوزات، وتكلفة المكافآت.", "Bem-vindo ao seu placar de indicações — uma leitura em direto das famílias que lhe trazem novas reservas, do valor dessas reservas e do custo das recompensas.", "Te damos la bienvenida a tu marcador de referidos: una lectura en directo de las familias que te traen reservas nuevas, lo que valen esas reservas y lo que cuestan las recompensas.", "Bienvenue sur votre tableau des parrainages — une lecture en direct des familles qui vous apportent de nouvelles réservations, de ce que valent ces réservations et de ce que coûtent les récompenses.", "Croeso i’ch sgorfwrdd atgyfeiriadau — darlleniad byw o’r teuluoedd sy’n dod ag archebion newydd i chi, gwerth yr archebion hynny, a chost y gwobrau."],
  "lt_referrals_done": ["And that is Referrals — see who is bringing you new families, what it is earning, and what the rewards cost; change the offer itself over in Setup.", "I to są Polecenia — widzisz, kto przyprowadza nowe rodziny, ile to przynosi i ile kosztują nagrody; samą ofertę zmienisz w Konfiguracji.", "Acestea sunt Recomandările — vezi cine îți aduce familii noi, cât câștigi și cât costă recompensele; oferta în sine o schimbi în Configurare.", "یہ ہے ریفرلز — دیکھیں کون آپ کے لیے نئے خاندان لا رہا ہے، اس سے کیا کمائی ہو رہی ہے اور انعامات کی لاگت کیا ہے؛ پیشکش خود سیٹ اپ میں بدلیں۔", "ਇਹ ਹਨ ਰੈਫ਼ਰਲ — ਦੇਖੋ ਕੌਣ ਨਵੇਂ ਪਰਿਵਾਰ ਲਿਆ ਰਿਹਾ ਹੈ, ਉਸ ਤੋਂ ਕੀ ਕਮਾਈ ਹੋ ਰਹੀ ਹੈ ਅਤੇ ਇਨਾਮਾਂ ਦੀ ਲਾਗਤ ਕੀ ਹੈ; ਪੇਸ਼ਕਸ਼ ਆਪ ਸੈੱਟਅੱਪ ਵਿੱਚ ਬਦਲੋ।", "এই হলো রেফারেল — দেখুন কে নতুন পরিবার আনছে, তাতে কত আয় হচ্ছে, আর পুরস্কারের খরচ কত; অফারটি নিজে সেটআপে বদলান।", "وهذه هي الإحالات — شاهد من يجلب لك عائلات جديدة، وكم تربح منها، وكم تكلّف المكافآت؛ وغيّر العرض نفسه من الإعداد.", "E é isto, as Indicações — veja quem lhe traz famílias novas, quanto rende e quanto custam as recompensas; altere a própria oferta na Configuração.", "Y eso son los Referidos: ve quién te trae familias nuevas, lo que generan y lo que cuestan las recompensas; cambia la oferta en sí en Configuración.", "Et voilà les Parrainages : voyez qui vous apporte de nouvelles familles, ce que cela rapporte et ce que coûtent les récompenses ; modifiez l’offre elle-même dans Configuration.", "A dyna’r Atgyfeiriadau — gweld pwy sy’n dod â theuluoedd newydd i chi, beth mae’n ei ennill a beth mae’r gwobrau’n ei gostio; newidiwch yr cynnig ei hun yn y Gosodiad."],
  "lt_referrals_s0": ["A banner up top sums up your live offer, with three headline figures: friends booked, the revenue those bookings brought in, and how many families are referring — and Change settings takes you to Setup to adjust the reward itself.", "Baner na górze podsumowuje Twoją aktualną ofertę, z trzema głównymi liczbami: przyprowadzeni znajomi, przychód z ich rezerwacji i liczba rodzin, które polecają — a Zmień ustawienia przenosi do Konfiguracji, gdzie dostosujesz samą nagrodę.", "Un banner sus rezumă oferta ta activă, cu trei cifre principale: prietenii care au rezervat, veniturile aduse de acele rezervări și câte familii recomandă — iar Schimbă setările te duce în Configurare ca să ajustezi recompensa.", "اوپر کا بینر آپ کی موجودہ پیشکش کا خلاصہ دیتا ہے، تین اہم اعداد کے ساتھ: بکنگ کرنے والے دوست، ان بکنگز سے حاصل ہونے والی آمدن، اور کتنے خاندان ریفر کر رہے ہیں — اور سیٹنگز بدلیں آپ کو سیٹ اپ میں لے جاتا ہے تاکہ انعام خود ایڈجسٹ کریں۔", "ਉੱਪਰ ਦਾ ਬੈਨਰ ਤੁਹਾਡੀ ਮੌਜੂਦਾ ਪੇਸ਼ਕਸ਼ ਦਾ ਸਾਰ ਦਿੰਦਾ ਹੈ, ਤਿੰਨ ਮੁੱਖ ਅੰਕਾਂ ਨਾਲ: ਬੁਕਿੰਗ ਕਰਨ ਵਾਲੇ ਦੋਸਤ, ਉਨ੍ਹਾਂ ਬੁਕਿੰਗਾਂ ਤੋਂ ਆਈ ਆਮਦਨ, ਅਤੇ ਕਿੰਨੇ ਪਰਿਵਾਰ ਰੈਫ਼ਰ ਕਰ ਰਹੇ ਹਨ — ਅਤੇ ਸੈਟਿੰਗਾਂ ਬਦਲੋ ਤੁਹਾਨੂੰ ਸੈੱਟਅੱਪ ਵਿੱਚ ਲੈ ਜਾਂਦਾ ਹੈ ਤਾਂ ਜੋ ਇਨਾਮ ਆਪ ਬਦਲ ਸਕੋ।", "উপরের ব্যানারে আপনার চালু অফারের সারসংক্ষেপ, তিনটি মূল অঙ্কসহ: বুকিং করা বন্ধুরা, সেই বুকিং থেকে আসা আয়, আর কতগুলো পরিবার রেফার করছে — আর সেটিংস পরিবর্তন করুন আপনাকে সেটআপে নিয়ে যায়, পুরস্কার নিজে বদলাতে।", "يلخّص اللافتة في الأعلى عرضك الحالي بثلاثة أرقام رئيسية: الأصدقاء الذين حجزوا، والإيرادات التي جلبتها تلك الحجوزات، وعدد العائلات التي تحيل — ويأخذك تغيير الإعدادات إلى الإعداد لتعديل المكافأة نفسها.", "Um banner no topo resume a sua oferta ativa, com três números principais: amigos que reservaram, receitas que essas reservas trouxeram e quantas famílias estão a indicar — e Alterar definições leva-o à Configuração para ajustar a própria recompensa.", "Un banner arriba resume tu oferta activa, con tres cifras principales: amigos que han reservado, ingresos que trajeron esas reservas y cuántas familias están refiriendo; y Cambiar ajustes te lleva a Configuración para modificar la recompensa.", "Une bannière en haut résume votre offre en cours, avec trois chiffres clés : les amis qui ont réservé, le revenu de ces réservations et le nombre de familles qui parrainent — et Modifier les réglages vous mène à Configuration pour ajuster la récompense.", "Mae baner ar y brig yn crynhoi eich cynnig byw, gyda thri phrif ffigur: ffrindiau a archebodd, yr incwm a ddaeth o’r archebion hynny, a faint o deuluoedd sy’n atgyfeirio — ac mae Newid gosodiadau yn mynd â chi i’r Gosodiad i addasu’r wobr ei hun."],
  "lt_referrals_s1": ["This leaderboard ranks your five busiest referrers by how many friends they have brought in, with the reward each has earned alongside; if your offer is a percentage, it shows the count of codes used instead.", "Ta lista rankingowa pokazuje pięciu najaktywniejszych polecających według liczby przyprowadzonych znajomych, wraz z zarobioną nagrodą; jeśli oferta jest procentowa, zamiast tego widać liczbę użytych kodów.", "Acest clasament îți arată cei mai activi cinci recomandatori după câți prieteni au adus, alături de recompensa câștigată de fiecare; dacă oferta este procentuală, arată în schimb numărul de coduri folosite.", "یہ لیڈر بورڈ آپ کے پانچ مصروف ترین ریفر کرنے والوں کو اس ترتیب سے دکھاتا ہے کہ انہوں نے کتنے دوست لائے، اور ساتھ ہر ایک کا کمایا ہوا انعام؛ اگر آپ کی پیشکش فیصد کی ہے تو اس کی جگہ استعمال ہونے والے کوڈز کی تعداد دکھاتا ہے۔", "ਇਹ ਲੀਡਰਬੋਰਡ ਤੁਹਾਡੇ ਪੰਜ ਸਭ ਤੋਂ ਸਰਗਰਮ ਰੈਫ਼ਰ ਕਰਨ ਵਾਲਿਆਂ ਨੂੰ ਇਸ ਕ੍ਰਮ ਵਿੱਚ ਦਿਖਾਉਂਦਾ ਹੈ ਕਿ ਉਹ ਕਿੰਨੇ ਦੋਸਤ ਲਿਆਏ, ਨਾਲ ਹਰ ਇੱਕ ਦਾ ਕਮਾਇਆ ਇਨਾਮ; ਜੇ ਤੁਹਾਡੀ ਪੇਸ਼ਕਸ਼ ਪ੍ਰਤੀਸ਼ਤ ਵਾਲੀ ਹੈ, ਤਾਂ ਇਸ ਦੀ ਥਾਂ ਵਰਤੇ ਕੋਡਾਂ ਦੀ ਗਿਣਤੀ ਦਿਖਾਉਂਦਾ ਹੈ।", "এই লিডারবোর্ড আপনার পাঁচজন সবচেয়ে সক্রিয় রেফারারকে সাজায় কতজন বন্ধু এনেছেন সেই অনুযায়ী, পাশে প্রত্যেকের অর্জিত পুরস্কার; অফার শতাংশভিত্তিক হলে বদলে ব্যবহৃত কোডের সংখ্যা দেখায়।", "تصنّف هذه اللوحة أنشط خمسة محيلين لديك حسب عدد الأصدقاء الذين جلبوهم، مع المكافأة التي نالها كل منهم؛ وإن كان عرضك نسبة مئوية فتعرض بدلًا من ذلك عدد الرموز المستخدمة.", "Este quadro classifica os seus cinco indicadores mais ativos pelo número de amigos que trouxeram, com a recompensa que cada um ganhou; se a sua oferta for uma percentagem, mostra antes o número de códigos usados.", "Este ranking ordena a tus cinco referidores más activos por cuántos amigos han traído, con la recompensa que ha ganado cada uno; si tu oferta es un porcentaje, muestra en su lugar el número de códigos usados.", "Ce classement place vos cinq parrains les plus actifs selon le nombre d’amis amenés, avec la récompense gagnée par chacun ; si votre offre est un pourcentage, il affiche à la place le nombre de codes utilisés.", "Mae’r bwrdd arweinwyr hwn yn graddio eich pum atgyfeiriwr prysuraf yn ôl faint o ffrindiau maen nhw wedi’u cyflwyno, gyda’r wobr y mae pob un wedi’i hennill; os yw eich cynnig yn ganran, mae’n dangos nifer y codau a ddefnyddiwyd yn lle hynny."],
  "lt_referrals_s2": ["This strip weighs the win against the cost — revenue from referred bookings, the discounts you gave as a share of that revenue, and how many rewards have been redeemed versus how many are still owed.", "Ten pasek waży zysk wobec kosztu — przychód z poleconych rezerwacji, udzielone rabaty jako odsetek tego przychodu oraz ile nagród zrealizowano, a ile jeszcze czeka.", "Această bandă cântărește câștigul față de cost — veniturile din rezervările recomandate, reducerile oferite ca pondere din acele venituri și câte recompense au fost răscumpărate față de câte mai sunt datorate.", "یہ پٹی فائدے کو لاگت کے مقابل تولتی ہے — ریفر کی گئی بکنگز کی آمدن، دی گئی رعایتیں اس آمدن کے حصے کے طور پر، اور کتنے انعامات وصول ہوئے بمقابلہ کتنے ابھی واجب ہیں۔", "ਇਹ ਪੱਟੀ ਲਾਭ ਨੂੰ ਲਾਗਤ ਦੇ ਮੁਕਾਬਲੇ ਤੋਲਦੀ ਹੈ — ਰੈਫ਼ਰ ਕੀਤੀਆਂ ਬੁਕਿੰਗਾਂ ਦੀ ਆਮਦਨ, ਦਿੱਤੀਆਂ ਛੋਟਾਂ ਉਸ ਆਮਦਨ ਦੇ ਹਿੱਸੇ ਵਜੋਂ, ਅਤੇ ਕਿੰਨੇ ਇਨਾਮ ਵਰਤੇ ਗਏ ਬਨਾਮ ਕਿੰਨੇ ਅਜੇ ਦੇਣੇ ਹਨ।", "এই স্ট্রিপ লাভকে খরচের সঙ্গে তুলনা করে — রেফার করা বুকিং থেকে আয়, দেওয়া ছাড় সেই আয়ের অংশ হিসেবে, আর কতগুলো পুরস্কার ভাঙানো হয়েছে বনাম কতগুলো এখনও বাকি।", "يوازن هذا الشريط الربح بالتكلفة — إيرادات الحجوزات المُحالة، والخصومات التي منحتها كنسبة من تلك الإيرادات، وعدد المكافآت المستخدمة مقابل المتبقي منها.", "Esta faixa pesa o ganho contra o custo — receitas das reservas indicadas, os descontos que deu como parte dessas receitas e quantas recompensas foram usadas face às que ainda são devidas.", "Esta franja sopesa la ganancia frente al coste: ingresos de las reservas referidas, los descuentos que diste como parte de esos ingresos y cuántas recompensas se han canjeado frente a cuántas aún se deben.", "Ce bandeau met le gain en balance avec le coût — revenu des réservations parrainées, remises accordées en part de ce revenu, et nombre de récompenses utilisées par rapport à celles encore dues.", "Mae’r stribed hwn yn pwyso’r fantais yn erbyn y gost — incwm o archebion a atgyfeiriwyd, y gostyngiadau a roesoch fel cyfran o’r incwm hwnnw, a faint o wobrau a ddefnyddiwyd o’i gymharu â faint sy’n dal yn ddyledus."],
  "lt_referrals_s3": ["A quick three-month bar chart shows friends booked each month with the revenue beneath, so you can see whether referrals are picking up.", "Szybki wykres słupkowy z trzech miesięcy pokazuje przyprowadzonych znajomych w każdym miesiącu, a pod nim przychód — widać, czy polecenia nabierają tempa.", "Un grafic rapid pe trei luni arată prietenii care au rezervat în fiecare lună, cu veniturile dedesubt, ca să vezi dacă recomandările prind avânt.", "تین مہینوں کا ایک مختصر بار چارٹ ہر ماہ بکنگ کرنے والے دوست اور نیچے آمدن دکھاتا ہے، تاکہ آپ دیکھ سکیں کہ ریفرلز بڑھ رہے ہیں یا نہیں۔", "ਤਿੰਨ ਮਹੀਨਿਆਂ ਦਾ ਇੱਕ ਛੋਟਾ ਬਾਰ ਚਾਰਟ ਹਰ ਮਹੀਨੇ ਬੁਕਿੰਗ ਕਰਨ ਵਾਲੇ ਦੋਸਤ ਅਤੇ ਹੇਠਾਂ ਆਮਦਨ ਦਿਖਾਉਂਦਾ ਹੈ, ਤਾਂ ਜੋ ਤੁਸੀਂ ਦੇਖ ਸਕੋ ਕਿ ਰੈਫ਼ਰਲ ਵਧ ਰਹੇ ਹਨ ਜਾਂ ਨਹੀਂ।", "তিন মাসের একটি দ্রুত বার চার্টে প্রতি মাসে বুকিং করা বন্ধুরা আর নিচে আয় দেখায়, যাতে বোঝা যায় রেফারেল বাড়ছে কি না।", "مخطط أعمدة سريع لثلاثة أشهر يعرض الأصدقاء الذين حجزوا كل شهر مع الإيرادات أسفله، فترى إن كانت الإحالات في ازدياد.", "Um gráfico de barras rápido de três meses mostra os amigos que reservaram em cada mês, com as receitas por baixo, para ver se as indicações estão a aumentar.", "Un gráfico de barras rápido de tres meses muestra los amigos que reservaron cada mes con los ingresos debajo, para ver si los referidos van en aumento.", "Un petit graphique en barres sur trois mois montre les amis ayant réservé chaque mois, avec le revenu en dessous, pour voir si les parrainages augmentent.", "Mae siart bar cyflym tri mis yn dangos ffrindiau a archebodd bob mis gyda’r incwm oddi tano, fel y gallwch weld a yw atgyfeiriadau’n codi."],
  "lt_referrals_s4": ["Every referral is listed here — who referred whom, the date, what the friend spent and saved, a link through to their booking, and whether the reward has been used; search by name or booking, and sort by newest, top reward or top spend.", "Tu widać każde polecenie — kto kogo polecił, datę, ile przyjaciel wydał i zaoszczędził, link do jego rezerwacji i czy nagroda została wykorzystana; szukaj po nazwisku lub rezerwacji i sortuj według najnowszych, największej nagrody lub największych wydatków.", "Aici e listată fiecare recomandare — cine pe cine a recomandat, data, cât a cheltuit și a economisit prietenul, un link către rezervarea lui și dacă recompensa a fost folosită; caută după nume sau rezervare și sortează după cele mai noi, cea mai mare recompensă sau cea mai mare cheltuială.", "ہر ریفرل یہاں درج ہے — کس نے کسے ریفر کیا، تاریخ، دوست نے کتنا خرچ کیا اور کتنا بچایا، ان کی بکنگ کا لنک، اور آیا انعام استعمال ہوا یا نہیں؛ نام یا بکنگ سے تلاش کریں، اور تازہ ترین، سب سے بڑے انعام یا سب سے زیادہ خرچ کے حساب سے ترتیب دیں۔", "ਹਰ ਰੈਫ਼ਰਲ ਇੱਥੇ ਦਰਜ ਹੈ — ਕਿਸ ਨੇ ਕਿਸ ਨੂੰ ਰੈਫ਼ਰ ਕੀਤਾ, ਤਾਰੀਖ਼, ਦੋਸਤ ਨੇ ਕਿੰਨਾ ਖਰਚਿਆ ਤੇ ਕਿੰਨਾ ਬਚਾਇਆ, ਉਨ੍ਹਾਂ ਦੀ ਬੁਕਿੰਗ ਦਾ ਲਿੰਕ, ਅਤੇ ਇਨਾਮ ਵਰਤਿਆ ਗਿਆ ਜਾਂ ਨਹੀਂ; ਨਾਮ ਜਾਂ ਬੁਕਿੰਗ ਨਾਲ ਖੋਜੋ, ਅਤੇ ਨਵੀਨਤਮ, ਸਭ ਤੋਂ ਵੱਡੇ ਇਨਾਮ ਜਾਂ ਸਭ ਤੋਂ ਵੱਧ ਖਰਚ ਅਨੁਸਾਰ ਕ੍ਰਮ ਬਣਾਓ।", "প্রতিটি রেফারেল এখানে তালিকাভুক্ত — কে কাকে রেফার করল, তারিখ, বন্ধু কত খরচ ও কত সাশ্রয় করল, তাদের বুকিংয়ের লিংক, আর পুরস্কার ব্যবহার হয়েছে কি না; নাম বা বুকিং দিয়ে খুঁজুন, এবং নতুনতম, সর্বোচ্চ পুরস্কার বা সর্বোচ্চ খরচ অনুযায়ী সাজান।", "تُدرج هنا كل إحالة — من أحال من، والتاريخ، وما أنفقه الصديق وما وفّره، ورابط إلى حجزه، وهل استُخدمت المكافأة؛ ابحث بالاسم أو الحجز، وفرز حسب الأحدث أو أعلى مكافأة أو أعلى إنفاق.", "Cada indicação está listada aqui — quem indicou quem, a data, quanto o amigo gastou e poupou, uma ligação para a reserva e se a recompensa foi usada; pesquise por nome ou reserva e ordene por mais recente, maior recompensa ou maior gasto.", "Cada referido está listado aquí: quién refirió a quién, la fecha, lo que gastó y ahorró el amigo, un enlace a su reserva y si se ha usado la recompensa; busca por nombre o reserva y ordena por más reciente, mayor recompensa o mayor gasto.", "Chaque parrainage est listé ici — qui a parrainé qui, la date, ce que l’ami a dépensé et économisé, un lien vers sa réservation et si la récompense a été utilisée ; cherchez par nom ou réservation, et triez par plus récent, plus grosse récompense ou plus grosse dépense.", "Rhestrir pob atgyfeiriad yma — pwy atgyfeiriodd bwy, y dyddiad, beth wariodd ac arbedodd y ffrind, dolen i’w harcheb, ac a yw’r wobr wedi’i defnyddio; chwiliwch yn ôl enw neu archeb, a threfnwch yn ôl y diweddaraf, y wobr fwyaf neu’r gwariant uchaf."],
  "lt_trips_title": ["Trips and visits", "Wycieczki i wizyty", "Excursii și vizite", "سفر اور دورے", "ਯਾਤਰਾਵਾਂ ਅਤੇ ਦੌਰੇ", "ভ্রমণ ও পরিদর্শন", "الرحلات والزيارات", "Passeios e visitas", "Excursiones y visitas", "Sorties et visites", "Teithiau ac ymweliadau"],
  "lt_trips_intro": ["This is where you plan an off-site visit from start to finish — details, risk assessment, ratios, parent consent, sign-off and live head counts, all scored in one readiness-tracked planner.", "Tu zaplanujesz wyjazd poza teren od początku do końca — szczegóły, ocenę ryzyka, proporcje opiekunów, zgodę rodziców, akceptację i liczenie dzieci na żywo — wszystko w jednym planerze z paskiem gotowości.", "Aici planifici o vizită în afara locației de la cap la coadă — detalii, evaluarea riscurilor, rapoarte, consimțământul părinților, aprobare și numărători live — totul într-un singur planificator cu indicator de pregătire.", "یہاں آپ سائٹ سے باہر کے دورے کی ابتدا سے انتہا تک منصوبہ بندی کرتے ہیں — تفصیلات، خطرے کا جائزہ، تناسب، والدین کی رضامندی، منظوری اور لائیو گنتی — سب ایک ہی تیاری کی پیمائش والے پلانر میں۔", "ਇੱਥੇ ਤੁਸੀਂ ਸਾਈਟ ਤੋਂ ਬਾਹਰ ਦੇ ਦੌਰੇ ਦੀ ਸ਼ੁਰੂ ਤੋਂ ਅੰਤ ਤੱਕ ਯੋਜਨਾ ਬਣਾਉਂਦੇ ਹੋ — ਵੇਰਵੇ, ਜੋਖਮ ਮੁਲਾਂਕਣ, ਅਨੁਪਾਤ, ਮਾਪਿਆਂ ਦੀ ਸਹਿਮਤੀ, ਮਨਜ਼ੂਰੀ ਅਤੇ ਲਾਈਵ ਗਿਣਤੀ — ਸਭ ਇੱਕੋ ਤਿਆਰੀ-ਟਰੈਕ ਵਾਲੇ ਪਲਾਨਰ ਵਿੱਚ।", "এখানে আপনি সাইটের বাইরের ভ্রমণ শুরু থেকে শেষ পর্যন্ত পরিকল্পনা করেন — বিবরণ, ঝুঁকি মূল্যায়ন, অনুপাত, অভিভাবকের সম্মতি, অনুমোদন ও লাইভ গণনা — সব একটি প্রস্তুতি-ট্র্যাকিং প্ল্যানারে।", "هنا تخطط لزيارة خارج الموقع من البداية إلى النهاية — التفاصيل وتقييم المخاطر والنِّسب وموافقة أولياء الأمور والاعتماد والعدّ المباشر — كل ذلك في مخطط واحد يتتبع الجاهزية.", "Aqui planeia uma visita fora do local do princípio ao fim — detalhes, avaliação de riscos, rácios, consentimento dos pais, aprovação e contagens em direto — tudo num único planeador com acompanhamento de prontidão.", "Aquí planificas una salida fuera del centro de principio a fin: detalles, evaluación de riesgos, ratios, consentimiento de los padres, aprobación y recuentos en directo, todo en un único planificador con seguimiento de preparación.", "Ici, vous planifiez une sortie hors site du début à la fin — détails, évaluation des risques, taux d’encadrement, consentement des parents, validation et comptages en direct — le tout dans un seul planificateur avec suivi de préparation.", "Yma rydych yn cynllunio ymweliad oddi ar y safle o’r dechrau i’r diwedd — manylion, asesiad risg, cymarebau, caniatâd rhieni, cymeradwyo a chyfrif byw — i gyd mewn un cynlluniwr sy’n olrhain parodrwydd."],
  "lt_trips_done": ["And that is the full loop — from first idea to everyone safely back at base, all in one place.", "I to cała pętla — od pierwszego pomysłu po to, że wszyscy bezpiecznie wrócili do bazy, wszystko w jednym miejscu.", "Și asta e tot circuitul — de la prima idee până când toți sunt înapoi în siguranță la bază, totul într-un singur loc.", "اور یہ مکمل چکر ہے — پہلے خیال سے لے کر سب کے بحفاظت واپس بیس پر پہنچنے تک، سب ایک ہی جگہ۔", "ਅਤੇ ਇਹ ਪੂਰਾ ਚੱਕਰ ਹੈ — ਪਹਿਲੇ ਵਿਚਾਰ ਤੋਂ ਲੈ ਕੇ ਸਭ ਦੇ ਸੁਰੱਖਿਅਤ ਬੇਸ ਉੱਤੇ ਵਾਪਸ ਪਹੁੰਚਣ ਤੱਕ, ਸਭ ਇੱਕੋ ਥਾਂ।", "আর এটাই পুরো চক্র — প্রথম ধারণা থেকে সবাই নিরাপদে বেসে ফিরে আসা পর্যন্ত, সব এক জায়গায়।", "وهذه هي الحلقة الكاملة — من الفكرة الأولى حتى عودة الجميع سالمين إلى المقر، كل ذلك في مكان واحد.", "E este é o ciclo completo — da primeira ideia até todos estarem de volta à base em segurança, tudo num só lugar.", "Y ese es el ciclo completo: desde la primera idea hasta que todos vuelven sanos y salvos a la base, todo en un solo lugar.", "Et voilà la boucle complète — de la première idée jusqu’au retour de tous en sécurité à la base, le tout au même endroit.", "A dyna’r cylch llawn — o’r syniad cyntaf nes bod pawb yn ôl yn ddiogel yn y ganolfan, i gyd mewn un lle."],
  "lt_trips_s0": ["This is your home base for every off-site visit — plan each one end to end, from the first details right through to everyone safely back at base.", "To Twoja baza dla każdego wyjazdu poza teren — zaplanujesz każdy od początku do końca, od pierwszych szczegółów aż po powrót wszystkich bezpiecznie do bazy.", "Aceasta este baza ta pentru fiecare vizită în afara locației — planifici fiecare vizită de la cap la coadă, de la primele detalii până când toți sunt înapoi în siguranță la bază.", "یہ سائٹ سے باہر ہر دورے کے لیے آپ کا مرکز ہے — ہر ایک کی ابتدا سے انتہا تک منصوبہ بندی کریں، پہلی تفصیلات سے لے کر سب کے بحفاظت واپس بیس پر آنے تک۔", "ਇਹ ਸਾਈਟ ਤੋਂ ਬਾਹਰ ਹਰ ਦੌਰੇ ਲਈ ਤੁਹਾਡਾ ਟਿਕਾਣਾ ਹੈ — ਹਰ ਇੱਕ ਦੀ ਸ਼ੁਰੂ ਤੋਂ ਅੰਤ ਤੱਕ ਯੋਜਨਾ ਬਣਾਓ, ਪਹਿਲੇ ਵੇਰਵਿਆਂ ਤੋਂ ਲੈ ਕੇ ਸਭ ਦੇ ਸੁਰੱਖਿਅਤ ਬੇਸ ਉੱਤੇ ਵਾਪਸ ਆਉਣ ਤੱਕ।", "সাইটের বাইরের প্রতিটি ভ্রমণের জন্য এটি আপনার হোম বেস — প্রতিটি শুরু থেকে শেষ পর্যন্ত পরিকল্পনা করুন, প্রথম বিবরণ থেকে সবাই নিরাপদে বেসে ফেরা পর্যন্ত।", "هذا هو مقرّك لكل زيارة خارج الموقع — خطّط لكل واحدة من البداية إلى النهاية، من التفاصيل الأولى حتى عودة الجميع سالمين إلى المقر.", "Esta é a sua base para cada visita fora do local — planeie cada uma do princípio ao fim, desde os primeiros detalhes até todos estarem de volta à base em segurança.", "Esta es tu base para cada salida fuera del centro: planifica cada una de principio a fin, desde los primeros detalles hasta que todos vuelven sanos y salvos a la base.", "C’est votre base pour chaque sortie hors site — planifiez chacune du début à la fin, des premiers détails jusqu’au retour de tous en sécurité à la base.", "Dyma’ch cartref ar gyfer pob ymweliad oddi ar y safle — cynlluniwch bob un o’r dechrau i’r diwedd, o’r manylion cyntaf nes bod pawb yn ôl yn ddiogel yn y ganolfan."],
  "lt_trips_s1": ["Up top, four tiles keep score — trips coming up, how many this month, which ones still need action, and your running total.", "Na górze cztery kafelki liczą wyniki — nadchodzące wyjazdy, ile w tym miesiącu, które wciąż wymagają działania i łączna liczba.", "Sus, patru casete țin scorul — vizitele viitoare, câte sunt luna aceasta, care mai cer acțiune și totalul cumulat.", "اوپر چار ٹائلیں حساب رکھتی ہیں — آنے والے دورے، اس مہینے کتنے ہیں، کن پر ابھی کام باقی ہے، اور آپ کا مجموعی شمار۔", "ਉੱਪਰ ਚਾਰ ਟਾਈਲਾਂ ਹਿਸਾਬ ਰੱਖਦੀਆਂ ਹਨ — ਆਉਣ ਵਾਲੇ ਦੌਰੇ, ਇਸ ਮਹੀਨੇ ਕਿੰਨੇ ਹਨ, ਕਿਨ੍ਹਾਂ ਉੱਤੇ ਅਜੇ ਕਾਰਵਾਈ ਬਾਕੀ ਹੈ, ਅਤੇ ਤੁਹਾਡਾ ਕੁੱਲ ਜੋੜ।", "উপরে চারটি টাইল হিসাব রাখে — আসন্ন ভ্রমণ, এই মাসে কতগুলো, কোনগুলোতে এখনও পদক্ষেপ দরকার, আর আপনার মোট সংখ্যা।", "في الأعلى أربع بطاقات تحتفظ بالنتيجة — الرحلات القادمة، وكم منها هذا الشهر، وأيها ما زال يحتاج إلى إجراء، وإجماليك المتراكم.", "No topo, quatro mosaicos mantêm a pontuação — visitas próximas, quantas este mês, quais ainda precisam de ação e o seu total acumulado.", "Arriba, cuatro mosaicos llevan la cuenta: salidas próximas, cuántas este mes, cuáles aún necesitan acción y tu total acumulado.", "En haut, quatre tuiles tiennent le score — sorties à venir, combien ce mois-ci, lesquelles demandent encore une action, et votre total cumulé.", "Ar y brig, mae pedair teilsen yn cadw sgôr — teithiau i ddod, faint y mis hwn, pa rai sy’n dal angen gweithredu, a’ch cyfanswm cronnus."],
  "lt_trips_s2": ["Open any trip, or start a fresh one, and it becomes a seven-step planner with a readiness ring that fills up as you complete the details, risk assessment, staffing, consent, sign-off and head counts.", "Otwórz dowolny wyjazd lub zacznij nowy, a stanie się siedmiostopniowym planerem z pierścieniem gotowości, który wypełnia się w miarę uzupełniania szczegółów, oceny ryzyka, obsady, zgód, akceptacji i liczenia dzieci.", "Deschide orice vizită sau începe una nouă și devine un planificator în șapte pași, cu un inel de pregătire care se umple pe măsură ce completezi detaliile, evaluarea riscurilor, personalul, consimțământul, aprobarea și numărătorile.", "کوئی بھی دورہ کھولیں یا نیا شروع کریں اور یہ سات مرحلوں کا پلانر بن جاتا ہے جس میں ایک تیاری کا دائرہ ہے جو تفصیلات، خطرے کے جائزے، عملے، رضامندی، منظوری اور گنتی مکمل کرنے کے ساتھ بھرتا جاتا ہے۔", "ਕੋਈ ਵੀ ਦੌਰਾ ਖੋਲ੍ਹੋ ਜਾਂ ਨਵਾਂ ਸ਼ੁਰੂ ਕਰੋ ਅਤੇ ਇਹ ਸੱਤ ਕਦਮਾਂ ਦਾ ਪਲਾਨਰ ਬਣ ਜਾਂਦਾ ਹੈ ਜਿਸ ਵਿੱਚ ਤਿਆਰੀ ਦਾ ਚੱਕਰ ਹੈ ਜੋ ਵੇਰਵੇ, ਜੋਖਮ ਮੁਲਾਂਕਣ, ਸਟਾਫ਼, ਸਹਿਮਤੀ, ਮਨਜ਼ੂਰੀ ਅਤੇ ਗਿਣਤੀ ਪੂਰੀ ਕਰਨ ਨਾਲ ਭਰਦਾ ਜਾਂਦਾ ਹੈ।", "যেকোনো ভ্রমণ খুলুন বা নতুন শুরু করুন, আর তা সাত ধাপের প্ল্যানার হয়ে যায়, যেখানে প্রস্তুতির রিং বিবরণ, ঝুঁকি মূল্যায়ন, কর্মী, সম্মতি, অনুমোদন ও গণনা সম্পূর্ণ করার সঙ্গে সঙ্গে ভরে ওঠে।", "افتح أي رحلة أو ابدأ واحدة جديدة فتصبح مخططًا من سبع خطوات مع حلقة جاهزية تمتلئ كلما أكملت التفاصيل وتقييم المخاطر والتوظيف والموافقات والاعتماد والعدّ.", "Abra qualquer visita ou comece uma nova e torna-se um planeador de sete passos com um anel de prontidão que se vai enchendo à medida que completa os detalhes, a avaliação de riscos, a equipa, o consentimento, a aprovação e as contagens.", "Abre cualquier salida o empieza una nueva y se convierte en un planificador de siete pasos con un anillo de preparación que se llena a medida que completas los detalles, la evaluación de riesgos, el personal, el consentimiento, la aprobación y los recuentos.", "Ouvrez une sortie ou démarrez-en une nouvelle, et elle devient un planificateur en sept étapes avec un anneau de préparation qui se remplit à mesure que vous complétez les détails, l’évaluation des risques, le personnel, le consentement, la validation et les comptages.", "Agorwch unrhyw daith neu dechreuwch un newydd a daw’n gynlluniwr saith cam gyda chylch parodrwydd sy’n llenwi wrth i chi gwblhau’r manylion, yr asesiad risg, staffio, caniatâd, cymeradwyo a chyfrif."],
  "lt_trips_s3": ["To start one, you press Plan a trip, and the planner opens on the details.", "Aby zacząć, naciskasz Zaplanuj wyjazd i planer otwiera się na szczegółach.", "Ca să începi una, apeși Planifică o vizită și planificatorul se deschide la detalii.", "شروع کرنے کے لیے آپ دورے کی منصوبہ بندی کریں دباتے ہیں، اور پلانر تفصیلات پر کھل جاتا ہے۔", "ਇੱਕ ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਤੁਸੀਂ ਦੌਰੇ ਦੀ ਯੋਜਨਾ ਬਣਾਓ ਦਬਾਉਂਦੇ ਹੋ, ਅਤੇ ਪਲਾਨਰ ਵੇਰਵਿਆਂ ਉੱਤੇ ਖੁੱਲ੍ਹਦਾ ਹੈ।", "একটি শুরু করতে আপনি ভ্রমণের পরিকল্পনা করুন চাপেন, আর প্ল্যানার বিবরণে খুলে যায়।", "للبدء تضغط على خطّط لرحلة فيُفتح المخطط على التفاصيل.", "Para começar uma, prime Planear uma visita e o planeador abre-se nos detalhes.", "Para empezar una, pulsas Planificar una salida y el planificador se abre en los detalles.", "Pour en démarrer une, vous appuyez sur Planifier une sortie et le planificateur s’ouvre sur les détails.", "I ddechrau un, pwyswch Cynllunio taith ac mae’r cynlluniwr yn agor ar y manylion."],
  "lt_trips_s4": ["First the basics — where you are going: Woodland Wonders in Epping Forest, the address, and the date, the twenty-fifth of August.", "Najpierw podstawy — dokąd jedziecie: Woodland Wonders w Epping Forest, adres i data, dwudziesty piąty sierpnia.", "Mai întâi bazele — încotro mergeți: Woodland Wonders în Epping Forest, adresa și data, douăzeci și cinci august.", "پہلے بنیادی باتیں — آپ کہاں جا رہے ہیں: ایپنگ فارسٹ میں ووڈ لینڈ ونڈرز، پتہ اور تاریخ، پچیس اگست۔", "ਪਹਿਲਾਂ ਮੁੱਢਲੀਆਂ ਗੱਲਾਂ — ਤੁਸੀਂ ਕਿੱਥੇ ਜਾ ਰਹੇ ਹੋ: ਐਪਿੰਗ ਫੌਰੈਸਟ ਵਿੱਚ ਵੁੱਡਲੈਂਡ ਵੰਡਰਜ਼, ਪਤਾ ਅਤੇ ਤਾਰੀਖ਼, ਪੱਚੀ ਅਗਸਤ।", "প্রথমে মূল বিষয় — আপনারা কোথায় যাচ্ছেন: এপিং ফরেস্টে উডল্যান্ড ওয়ান্ডার্স, ঠিকানা ও তারিখ, পঁচিশে আগস্ট।", "أولًا الأساسيات — وجهتكم: وودلاند ووندرز في غابة إبينغ، والعنوان، والتاريخ، الخامس والعشرون من أغسطس.", "Primeiro o essencial — para onde vão: Woodland Wonders na Epping Forest, a morada e a data, vinte e cinco de agosto.", "Primero lo básico: adónde vais, Woodland Wonders en Epping Forest, la dirección y la fecha, el veinticinco de agosto.", "D’abord l’essentiel — où vous allez : Woodland Wonders dans la forêt d’Epping, l’adresse et la date, le vingt-cinq août.", "Yn gyntaf y pethau sylfaenol — ble rydych yn mynd: Woodland Wonders yng Nghoedwig Epping, y cyfeiriad, a’r dyddiad, pumed ar hugain o Awst."],
  "lt_trips_s5": ["Then the cost per child, eighteen pounds, your depart and return times, and one tap picks the transport — Coach.", "Potem koszt na dziecko, osiemnaście funtów, godziny wyjazdu i powrotu, a jedno dotknięcie wybiera transport — Autokar.", "Apoi costul pe copil, optsprezece lire, orele de plecare și de întoarcere, iar o singură atingere alege transportul — Autocar.", "پھر فی بچہ لاگت، اٹھارہ پاؤنڈ، روانگی اور واپسی کے اوقات، اور ایک ٹیپ سے ٹرانسپورٹ چنی جاتی ہے — کوچ۔", "ਫਿਰ ਪ੍ਰਤੀ ਬੱਚਾ ਲਾਗਤ, ਅਠਾਰਾਂ ਪੌਂਡ, ਰਵਾਨਗੀ ਅਤੇ ਵਾਪਸੀ ਦਾ ਸਮਾਂ, ਅਤੇ ਇੱਕ ਟੈਪ ਨਾਲ ਆਵਾਜਾਈ ਚੁਣੀ ਜਾਂਦੀ ਹੈ — ਕੋਚ।", "তারপর প্রতি শিশুর খরচ, আঠারো পাউন্ড, যাত্রা ও ফেরার সময়, আর এক ট্যাপে পরিবহন বাছা — কোচ।", "ثم التكلفة لكل طفل، ثمانية عشر جنيهًا، وأوقات المغادرة والعودة، وبنقرة واحدة تختار وسيلة النقل — حافلة سياحية.", "Depois o custo por criança, dezoito libras, as horas de partida e regresso, e um toque escolhe o transporte — Autocarro.", "Luego el coste por niño, dieciocho libras, las horas de salida y regreso, y un toque elige el transporte: autocar.", "Puis le coût par enfant, dix-huit livres, les heures de départ et de retour, et une touche choisit le transport — Car.", "Yna’r gost y plentyn, deunaw punt, yr amseroedd gadael a dychwelyd, ac mae un tap yn dewis y cludiant — Bws moethus."],
  "lt_trips_s6": ["Name your trip lead, Priya Sharma, with a mobile number, so everyone knows who is in charge on the day.", "Wskaż szefową wyjazdu, Priya Sharma, z numerem komórkowym, aby każdy wiedział, kto dowodzi w danym dniu.", "Numește conducătoarea vizitei, Priya Sharma, cu un număr de mobil, ca toată lumea să știe cine răspunde în ziua respectivă.", "اپنے دورے کی سربراہ کا نام دیں، پریا شرما، موبائل نمبر کے ساتھ، تاکہ سب کو معلوم ہو کہ اس دن انچارج کون ہے۔", "ਆਪਣੇ ਦੌਰੇ ਦੀ ਮੁਖੀ ਦਾ ਨਾਮ ਦਿਓ, ਪ੍ਰੀਆ ਸ਼ਰਮਾ, ਮੋਬਾਈਲ ਨੰਬਰ ਨਾਲ, ਤਾਂ ਜੋ ਸਭ ਨੂੰ ਪਤਾ ਹੋਵੇ ਕਿ ਉਸ ਦਿਨ ਇੰਚਾਰਜ ਕੌਣ ਹੈ।", "আপনার ভ্রমণের নেতার নাম দিন, প্রিয়া শর্মা, মোবাইল নম্বরসহ, যাতে সবাই জানে সেদিন দায়িত্বে কে।", "سمِّ قائدة الرحلة، بريا شارما، مع رقم جوال، ليعرف الجميع من المسؤول في ذلك اليوم.", "Indique a responsável pela visita, Priya Sharma, com um número de telemóvel, para que todos saibam quem está no comando no dia.", "Indica a la responsable de la salida, Priya Sharma, con un número de móvil, para que todos sepan quién está al mando ese día.", "Nommez la responsable de la sortie, Priya Sharma, avec un numéro de portable, pour que chacun sache qui est aux commandes ce jour-là.", "Enwch arweinydd eich taith, Priya Sharma, gyda rhif ffôn symudol, fel bod pawb yn gwybod pwy sy’n gyfrifol ar y diwrnod."],
  "lt_trips_s7": ["And that is the details done. Pressing Save and close creates the trip, then you work through the risk assessment, staffing, consent and manager sign-off.", "I szczegóły gotowe. Naciśnięcie Zapisz i zamknij tworzy wyjazd, a potem przechodzisz przez ocenę ryzyka, obsadę, zgody i akceptację kierownika.", "Și detaliile sunt gata. Apăsarea pe Salvează și închide creează vizita, apoi parcurgi evaluarea riscurilor, personalul, consimțământul și aprobarea managerului.", "اور تفصیلات مکمل۔ محفوظ کریں اور بند کریں دبانے سے دورہ بن جاتا ہے، پھر آپ خطرے کے جائزے، عملے، رضامندی اور مینیجر کی منظوری سے گزرتے ہیں۔", "ਅਤੇ ਵੇਰਵੇ ਪੂਰੇ। ਸੰਭਾਲੋ ਅਤੇ ਬੰਦ ਕਰੋ ਦਬਾਉਣ ਨਾਲ ਦੌਰਾ ਬਣ ਜਾਂਦਾ ਹੈ, ਫਿਰ ਤੁਸੀਂ ਜੋਖਮ ਮੁਲਾਂਕਣ, ਸਟਾਫ਼, ਸਹਿਮਤੀ ਅਤੇ ਮੈਨੇਜਰ ਦੀ ਮਨਜ਼ੂਰੀ ਵਿੱਚੋਂ ਲੰਘਦੇ ਹੋ।", "আর বিবরণ সম্পূর্ণ। সংরক্ষণ করে বন্ধ করুন চাপলে ভ্রমণ তৈরি হয়, তারপর ঝুঁকি মূল্যায়ন, কর্মী, সম্মতি ও ম্যানেজারের অনুমোদনের কাজ করবেন।", "وهكذا اكتملت التفاصيل. يؤدي الضغط على حفظ وإغلاق إلى إنشاء الرحلة، ثم تتابع تقييم المخاطر والتوظيف والموافقات واعتماد المدير.", "E os detalhes estão feitos. Premir Guardar e fechar cria a visita, e depois avança pela avaliação de riscos, equipa, consentimento e aprovação do gestor.", "Y los detalles están hechos. Al pulsar Guardar y cerrar se crea la salida, y luego sigues con la evaluación de riesgos, el personal, el consentimiento y la aprobación del responsable.", "Et les détails sont faits. Appuyer sur Enregistrer et fermer crée la sortie, puis vous passez à l’évaluation des risques, au personnel, au consentement et à la validation du responsable.", "A dyna’r manylion wedi’u gwneud. Mae pwyso Cadw a chau yn creu’r daith, yna rydych yn gweithio trwy’r asesiad risg, staffio, caniatâd a chymeradwyaeth y rheolwr."],
  "lt_marketing_title": ["Discount codes", "Kody rabatowe", "Coduri de reducere", "ڈسکاؤنٹ کوڈز", "ਛੋਟ ਕੋਡ", "ডিসকাউন্ট কোড", "رموز الخصم", "Códigos de desconto", "Códigos de descuento", "Codes de réduction", "Codau disgownt"],
  "lt_marketing_intro": ["This is where all your promo codes live — the little codes families type at checkout for money off, whether that is a public sale, a private thank-you, or an offer for a whole group. Let me build one with you so you can see the form fill itself in.", "Tu mieszkają wszystkie Twoje kody promocyjne — małe kody, które rodziny wpisują przy płatności, by dostać zniżkę, czy to publiczna wyprzedaż, prywatne podziękowanie, czy oferta dla całej grupy. Zbudujmy jeden razem, abyś zobaczył, jak formularz wypełnia się sam.", "Aici trăiesc toate codurile tale promoționale — micile coduri pe care familiile le scriu la finalizarea comenzii pentru reducere, fie că e o promoție publică, un mulțumesc privat sau o ofertă pentru un grup întreg. Hai să construim unul împreună, ca să vezi cum se completează singur formularul.", "آپ کے تمام پرومو کوڈز یہاں رہتے ہیں — وہ چھوٹے کوڈ جو خاندان ادائیگی کے وقت رعایت کے لیے لکھتے ہیں، چاہے عوامی سیل ہو، نجی شکریہ ہو یا پورے گروپ کے لیے پیشکش۔ آئیں آپ کے ساتھ ایک بناتے ہیں تاکہ آپ فارم کو خود بھرتے دیکھ سکیں۔", "ਤੁਹਾਡੇ ਸਾਰੇ ਪ੍ਰੋਮੋ ਕੋਡ ਇੱਥੇ ਰਹਿੰਦੇ ਹਨ — ਉਹ ਛੋਟੇ ਕੋਡ ਜੋ ਪਰਿਵਾਰ ਭੁਗਤਾਨ ਵੇਲੇ ਛੋਟ ਲਈ ਲਿਖਦੇ ਹਨ, ਭਾਵੇਂ ਜਨਤਕ ਸੇਲ ਹੋਵੇ, ਨਿੱਜੀ ਧੰਨਵਾਦ ਹੋਵੇ ਜਾਂ ਪੂਰੇ ਗਰੁੱਪ ਲਈ ਪੇਸ਼ਕਸ਼। ਆਓ ਤੁਹਾਡੇ ਨਾਲ ਇੱਕ ਬਣਾਈਏ ਤਾਂ ਜੋ ਤੁਸੀਂ ਫਾਰਮ ਨੂੰ ਆਪਣੇ ਆਪ ਭਰਦੇ ਦੇਖ ਸਕੋ।", "আপনার সব প্রোমো কোড এখানে থাকে — পরিবারগুলো চেকআউটে ছাড়ের জন্য যে ছোট কোড লেখে, তা পাবলিক সেল, ব্যক্তিগত ধন্যবাদ বা পুরো গ্রুপের অফার যা-ই হোক। আসুন আপনার সঙ্গে একটি বানাই, যাতে ফর্মটি নিজে নিজে ভরে যেতে দেখতে পান।", "هنا تعيش كل رموزك الترويجية — الرموز الصغيرة التي تكتبها العائلات عند الدفع للحصول على خصم، سواء كان تخفيضًا عامًا أو شكرًا خاصًا أو عرضًا لمجموعة كاملة. دعنا نبني رمزًا معك لترى النموذج يملأ نفسه.", "É aqui que vivem todos os seus códigos promocionais — os pequenos códigos que as famílias escrevem no pagamento para obter desconto, seja uma promoção pública, um agradecimento privado ou uma oferta para um grupo inteiro. Vamos criar um consigo para ver o formulário a preencher-se sozinho.", "Aquí viven todos tus códigos promocionales: los pequeños códigos que las familias escriben al pagar para obtener descuento, ya sea una oferta pública, un agradecimiento privado o una oferta para todo un grupo. Vamos a crear uno juntos para que veas cómo se rellena solo el formulario.", "C’est ici que vivent tous vos codes promo — ces petits codes que les familles saisissent au paiement pour obtenir une remise, qu’il s’agisse d’une vente publique, d’un remerciement privé ou d’une offre pour tout un groupe. Construisons-en un ensemble pour voir le formulaire se remplir tout seul.", "Yma mae eich holl godau hyrwyddo yn byw — y codau bach y mae teuluoedd yn eu teipio wrth dalu i gael arian oddi ar y pris, boed yn werthiant cyhoeddus, yn ddiolch preifat neu’n gynnig i grŵp cyfan. Gadewch i ni adeiladu un gyda’n gilydd er mwyn i chi weld y ffurflen yn llenwi ei hun."],
  "lt_marketing_done": ["And that is a real code built end to end — named, priced, capped and ready to save. You now know how to spin one up, target who sees it, and keep an eye on how it is doing.", "I to prawdziwy kod zbudowany od początku do końca — nazwany, wyceniony, z limitem i gotowy do zapisania. Wiesz już, jak go utworzyć, wskazać, kto go widzi, i śledzić, jak się sprawdza.", "Și acesta e un cod real construit de la cap la coadă — numit, evaluat, plafonat și gata de salvat. Acum știi cum să creezi unul, să stabilești cine îl vede și să urmărești cum se descurcă.", "اور یہ ایک اصل کوڈ شروع سے آخر تک تیار ہو گیا — نام، قیمت، حد، اور محفوظ کرنے کے لیے تیار۔ اب آپ جانتے ہیں کہ کوڈ کیسے بنانا ہے، کسے دکھانا ہے، اور اس کی کارکردگی پر نظر کیسے رکھنی ہے۔", "ਅਤੇ ਇਹ ਇੱਕ ਅਸਲ ਕੋਡ ਸ਼ੁਰੂ ਤੋਂ ਅੰਤ ਤੱਕ ਬਣ ਗਿਆ — ਨਾਮ, ਕੀਮਤ, ਹੱਦ, ਅਤੇ ਸੰਭਾਲਣ ਲਈ ਤਿਆਰ। ਹੁਣ ਤੁਸੀਂ ਜਾਣਦੇ ਹੋ ਕਿ ਇੱਕ ਕੋਡ ਕਿਵੇਂ ਬਣਾਉਣਾ ਹੈ, ਕਿਸ ਨੂੰ ਦਿਖਾਉਣਾ ਹੈ, ਅਤੇ ਉਸ ਦੀ ਕਾਰਗੁਜ਼ਾਰੀ ਉੱਤੇ ਨਜ਼ਰ ਕਿਵੇਂ ਰੱਖਣੀ ਹੈ।", "আর এটি একটি আসল কোড শুরু থেকে শেষ পর্যন্ত তৈরি — নাম, মূল্য, সীমা, আর সংরক্ষণের জন্য প্রস্তুত। এখন আপনি জানেন কীভাবে একটি বানাবেন, কে দেখবে তা ঠিক করবেন, আর কেমন চলছে তার দিকে নজর রাখবেন।", "وهذا رمز حقيقي بُني من البداية إلى النهاية — له اسم وسعر وحد أقصى وجاهز للحفظ. صرت تعرف الآن كيف تُنشئ واحدًا، وتحدد من يراه، وتتابع أداءه.", "E aqui está um código real criado de ponta a ponta — com nome, preço, limite e pronto a guardar. Agora sabe como criar um, definir quem o vê e acompanhar o seu desempenho.", "Y ese es un código real construido de principio a fin: con nombre, precio, tope y listo para guardar. Ya sabes cómo crear uno, decidir quién lo ve y seguir cómo le va.", "Et voilà un vrai code construit de bout en bout — nommé, chiffré, plafonné et prêt à être enregistré. Vous savez maintenant en créer un, choisir qui le voit et suivre ses résultats.", "A dyna god go iawn wedi’i adeiladu o’r dechrau i’r diwedd — wedi’i enwi, ei brisio, ei gapio ac yn barod i’w gadw. Nawr rydych yn gwybod sut i greu un, targedu pwy sy’n ei weld, a chadw llygad ar sut mae’n dod yn ei flaen."],
  "lt_marketing_s0": ["Right at the top you get a quick pulse on your codes — how many are live, how often they have been redeemed, and how many you have made in total.", "Na samej górze masz szybki puls swoich kodów — ile jest aktywnych, jak często je wykorzystano i ile utworzyłeś łącznie.", "Chiar sus ai pulsul rapid al codurilor tale — câte sunt active, de câte ori au fost folosite și câte ai creat în total.", "سب سے اوپر آپ کو اپنے کوڈز کی فوری نبض ملتی ہے — کتنے فعال ہیں، کتنی بار استعمال ہوئے، اور آپ نے کل کتنے بنائے۔", "ਬਿਲਕੁਲ ਉੱਪਰ ਤੁਹਾਨੂੰ ਆਪਣੇ ਕੋਡਾਂ ਦੀ ਤੁਰੰਤ ਨਬਜ਼ ਮਿਲਦੀ ਹੈ — ਕਿੰਨੇ ਚਾਲੂ ਹਨ, ਕਿੰਨੀ ਵਾਰ ਵਰਤੇ ਗਏ, ਅਤੇ ਤੁਸੀਂ ਕੁੱਲ ਕਿੰਨੇ ਬਣਾਏ।", "একদম উপরে আপনার কোডগুলোর দ্রুত নাড়ি — কতগুলো চালু, কতবার ব্যবহৃত, আর মোট কতগুলো বানিয়েছেন।", "في الأعلى تحصل على نبضة سريعة لرموزك — كم منها فعّال، وكم مرة استُخدمت، وكم أنشأت في المجموع.", "No topo tem uma leitura rápida dos seus códigos — quantos estão ativos, quantas vezes foram usados e quantos criou no total.", "Arriba tienes un pulso rápido de tus códigos: cuántos están activos, cuántas veces se han canjeado y cuántos has creado en total.", "Tout en haut, un aperçu rapide de vos codes — combien sont actifs, combien de fois ils ont été utilisés et combien vous en avez créé au total.", "Reit ar y brig cewch guriad cyflym o’ch codau — faint sy’n fyw, pa mor aml y cawsant eu defnyddio, a faint rydych wedi’u gwneud i gyd."],
  "lt_marketing_s1": ["Build named sets of families once here — like your NHS parents or your term-time regulars — and the reserve-for-a-group picker will feed straight off them.", "Zbuduj tutaj raz nazwane grupy rodzin — na przykład rodziców z NHS lub stałych bywalców w trakcie semestru — a selektor rezerwacji dla grupy będzie z nich korzystał.", "Construiește aici, o singură dată, seturi numite de familii — de pildă părinții din NHS sau clienții tăi constanți din timpul semestrului — iar selectorul de rezervare pentru un grup le va folosi direct.", "یہاں خاندانوں کے نام والے سیٹ ایک بار بنائیں — جیسے آپ کے این ایچ ایس والے والدین یا ٹرم ٹائم کے مستقل گاہک — اور گروپ کے لیے مخصوص کرنے والا انتخابی ٹول براہِ راست انہی سے چلے گا۔", "ਇੱਥੇ ਪਰਿਵਾਰਾਂ ਦੇ ਨਾਮ ਵਾਲੇ ਸੈੱਟ ਇੱਕ ਵਾਰ ਬਣਾਓ — ਜਿਵੇਂ ਤੁਹਾਡੇ NHS ਵਾਲੇ ਮਾਪੇ ਜਾਂ ਟਰਮ-ਟਾਈਮ ਦੇ ਨਿਯਮਿਤ ਗਾਹਕ — ਅਤੇ ਗਰੁੱਪ ਲਈ ਰਾਖਵਾਂ ਕਰਨ ਵਾਲਾ ਚੋਣਕਾਰ ਸਿੱਧਾ ਉਨ੍ਹਾਂ ਤੋਂ ਹੀ ਚੱਲੇਗਾ।", "এখানে পরিবারের নামযুক্ত সেট একবারই তৈরি করুন — যেমন আপনার এনএইচএস অভিভাবক বা টার্ম-টাইমের নিয়মিতরা — আর গ্রুপের জন্য সংরক্ষণ বাছাইকারী সরাসরি সেগুলো থেকেই নেবে।", "ابنِ هنا مرة واحدة مجموعات مسمّاة من العائلات — مثل أولياء أمور هيئة الخدمات الصحية أو المنتظمين في فترة الدراسة — وسيأخذ منها منتقي الحجز لمجموعة مباشرةً.", "Crie aqui, uma só vez, conjuntos com nome de famílias — como os pais do NHS ou os habituais do período letivo — e o seletor de reserva para um grupo vai buscá-los diretamente.", "Crea aquí una sola vez conjuntos con nombre de familias, como tus padres del NHS o tus habituales de curso, y el selector de reservar para un grupo se nutrirá directamente de ellos.", "Créez ici une seule fois des ensembles nommés de familles — comme vos parents du NHS ou vos habitués de la période scolaire — et le sélecteur de réservation pour un groupe s’en servira directement.", "Adeiladwch setiau a enwir o deuluoedd unwaith yma — fel eich rhieni GIG neu eich cwsmeriaid tymor rheolaidd — a bydd y dewisydd neilltuo ar gyfer grŵp yn bwydo’n syth oddi arnynt."],
  "lt_marketing_s2": ["To add one, you press New code, and this form opens. Watch — I will fill in a real summer sale as we go.", "Aby dodać kod, naciskasz Nowy kod i otwiera się ten formularz. Patrz — wypełnię prawdziwą letnią wyprzedaż w trakcie.", "Ca să adaugi unul, apeși Cod nou și se deschide acest formular. Uite — voi completa o reducere reală de vară pe parcurs.", "نیا کوڈ شامل کرنے کے لیے آپ نیا کوڈ دباتے ہیں، اور یہ فارم کھل جاتا ہے۔ دیکھیں — میں ساتھ ساتھ گرمیوں کی ایک اصل سیل بھرتا ہوں۔", "ਇੱਕ ਜੋੜਨ ਲਈ ਤੁਸੀਂ ਨਵਾਂ ਕੋਡ ਦਬਾਉਂਦੇ ਹੋ, ਅਤੇ ਇਹ ਫਾਰਮ ਖੁੱਲ੍ਹ ਜਾਂਦਾ ਹੈ। ਦੇਖੋ — ਮੈਂ ਨਾਲੋ-ਨਾਲ ਗਰਮੀਆਂ ਦੀ ਇੱਕ ਅਸਲ ਸੇਲ ਭਰਦਾ ਹਾਂ।", "একটি যোগ করতে আপনি নতুন কোড চাপেন, আর এই ফর্মটি খুলে যায়। দেখুন — আমি সঙ্গে সঙ্গে গ্রীষ্মের একটি আসল সেল ভরে দিচ্ছি।", "لإضافة رمز تضغط على رمز جديد فيُفتح هذا النموذج. شاهد — سأملأ تخفيضًا صيفيًا حقيقيًا أثناء ذلك.", "Para adicionar um, prime Novo código e este formulário abre-se. Veja — vou preencher uma promoção de verão a sério à medida que avançamos.", "Para añadir uno, pulsas Nuevo código y se abre este formulario. Mira: iré rellenando unas rebajas de verano reales sobre la marcha.", "Pour en ajouter un, vous appuyez sur Nouveau code et ce formulaire s’ouvre. Regardez — je remplis de vrais soldes d’été au fur et à mesure.", "I ychwanegu un, pwyswch Cod newydd ac mae’r ffurflen hon yn agor. Gwyliwch — llenwaf werthiant haf go iawn wrth i ni fynd."],
  "lt_marketing_s3": ["First, name the code — or tap Generate to mint a fresh one — then pick how the money comes off. We will give parents fifteen percent off with the code SUMMER25.", "Najpierw nazwij kod — albo dotknij Generuj, by wymyślić nowy — a potem wybierz, jak obniżka ma działać. Damy rodzicom piętnaście procent zniżki z kodem SUMMER25.", "Mai întâi dă-i un nume codului — sau atinge Generează ca să creezi unul nou — apoi alege cum se scade prețul. Le vom da părinților cincisprezece la sută reducere cu codul SUMMER25.", "پہلے کوڈ کو نام دیں — یا نیا بنانے کے لیے بنائیں پر ٹیپ کریں — پھر چنیں کہ رعایت کیسے ہوگی۔ ہم والدین کو کوڈ SUMMER25 کے ساتھ پندرہ فیصد رعایت دیں گے۔", "ਪਹਿਲਾਂ ਕੋਡ ਨੂੰ ਨਾਮ ਦਿਓ — ਜਾਂ ਨਵਾਂ ਬਣਾਉਣ ਲਈ ਬਣਾਓ ਉੱਤੇ ਟੈਪ ਕਰੋ — ਫਿਰ ਚੁਣੋ ਕਿ ਛੋਟ ਕਿਵੇਂ ਮਿਲੇਗੀ। ਅਸੀਂ ਮਾਪਿਆਂ ਨੂੰ ਕੋਡ SUMMER25 ਨਾਲ ਪੰਦਰਾਂ ਪ੍ਰਤੀਸ਼ਤ ਛੋਟ ਦੇਵਾਂਗੇ।", "প্রথমে কোডের নাম দিন — বা নতুন একটি তৈরি করতে জেনারেট ট্যাপ করুন — তারপর বেছে নিন ছাড় কীভাবে হবে। আমরা অভিভাবকদের SUMMER25 কোডে পনেরো শতাংশ ছাড় দেব।", "أولًا سمِّ الرمز — أو اضغط توليد لإنشاء رمز جديد — ثم اختر كيف يُخصم المبلغ. سنمنح أولياء الأمور خصمًا بنسبة خمسة عشر بالمئة بالرمز SUMMER25.", "Primeiro dê um nome ao código — ou toque em Gerar para criar um novo — e depois escolha como sai o dinheiro. Vamos dar aos pais quinze por cento de desconto com o código SUMMER25.", "Primero ponle nombre al código, o toca Generar para crear uno nuevo, y luego elige cómo se descuenta el dinero. Daremos a los padres un quince por ciento de descuento con el código SUMMER25.", "D’abord, nommez le code — ou touchez Générer pour en créer un — puis choisissez comment la remise s’applique. Nous offrirons aux parents quinze pour cent de réduction avec le code SUMMER25.", "Yn gyntaf enwch y cod — neu tapiwch Cynhyrchu i greu un newydd — yna dewiswch sut mae’r arian yn dod i ffwrdd. Byddwn yn rhoi pymtheg y cant i ffwrdd i rieni gyda’r cod SUMMER25."],
  "lt_marketing_s4": ["Now the guardrails — a sixty pound minimum spend, an expiry of the thirty-first of August, a cap of one hundred redemptions, and it applies right across all your listings.", "Teraz zabezpieczenia — minimalne wydatki sześćdziesiąt funtów, ważność do trzydziestego pierwszego sierpnia, limit stu użyć, a kod działa na wszystkie Twoje oferty.", "Acum limitele — o cheltuială minimă de șaizeci de lire, expirare la treizeci și unu august, un plafon de o sută de utilizări, iar se aplică tuturor ofertelor tale.", "اب حفاظتی حدود — کم از کم ساٹھ پاؤنڈ کا خرچ، اکتیس اگست کی میعاد، سو بار استعمال کی حد، اور یہ آپ کی تمام لسٹنگز پر لاگو ہوتا ہے۔", "ਹੁਣ ਸੁਰੱਖਿਆ ਹੱਦਾਂ — ਘੱਟੋ-ਘੱਟ ਸੱਠ ਪੌਂਡ ਦਾ ਖਰਚ, ਇਕੱਤੀ ਅਗਸਤ ਦੀ ਮਿਆਦ, ਸੌ ਵਾਰ ਵਰਤਣ ਦੀ ਸੀਮਾ, ਅਤੇ ਇਹ ਤੁਹਾਡੀਆਂ ਸਾਰੀਆਂ ਲਿਸਟਿੰਗਾਂ ਉੱਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ।", "এবার সীমারেখা — সর্বনিম্ন ষাট পাউন্ড খরচ, একত্রিশে আগস্ট মেয়াদ শেষ, একশো বার ব্যবহারের সীমা, আর এটি আপনার সব লিস্টিংয়ে প্রযোজ্য।", "الآن الضوابط — حد أدنى للإنفاق ستون جنيهًا، وانتهاء في الحادي والثلاثين من أغسطس، وسقف مئة استخدام، ويسري على جميع إعلاناتك.", "Agora os limites — um gasto mínimo de sessenta libras, validade até trinta e um de agosto, um teto de cem utilizações, e aplica-se a todos os seus anúncios.", "Ahora las salvaguardas: un gasto mínimo de sesenta libras, caducidad el treinta y uno de agosto, un tope de cien canjes, y se aplica a todos tus anuncios.", "Maintenant les garde-fous — une dépense minimale de soixante livres, une expiration au trente et un août, un plafond de cent utilisations, et il s’applique à toutes vos annonces.", "Nawr y canllawiau — isafswm gwariant o drigain punt, dod i ben ar yr unfed ar ddeg ar hugain o Awst, cap o gant o ddefnyddiau, ac mae’n berthnasol ar draws eich holl restriadau."],
  "lt_marketing_s5": ["Two handy switches — cap a code to one use per family, or stop it stacking with any other at checkout. For a headline sale we will tick the no-combining switch so it stays a tidy fifteen percent.", "Dwa przydatne przełączniki — ogranicz kod do jednego użycia na rodzinę albo zablokuj łączenie go z innymi przy płatności. Przy głównej wyprzedaży zaznaczymy brak łączenia, by zostało równe piętnaście procent.", "Două comutatoare utile — limitează codul la o singură folosire pe familie sau oprește cumularea lui cu alte coduri la finalizare. Pentru o promoție principală bifăm comutatorul fără combinare, ca să rămână un curat cincisprezece la sută.", "دو کارآمد سوئچ — کوڈ کو فی خاندان ایک استعمال تک محدود کریں، یا ادائیگی کے وقت اسے کسی اور کے ساتھ ملنے سے روکیں۔ مرکزی سیل کے لیے ہم ملانے کی ممانعت کا سوئچ آن کریں گے تاکہ یہ صاف پندرہ فیصد ہی رہے۔", "ਦੋ ਕੰਮ ਦੇ ਸਵਿੱਚ — ਕੋਡ ਨੂੰ ਪ੍ਰਤੀ ਪਰਿਵਾਰ ਇੱਕ ਵਰਤੋਂ ਤੱਕ ਸੀਮਤ ਕਰੋ, ਜਾਂ ਭੁਗਤਾਨ ਵੇਲੇ ਉਸਨੂੰ ਕਿਸੇ ਹੋਰ ਨਾਲ ਜੁੜਨ ਤੋਂ ਰੋਕੋ। ਮੁੱਖ ਸੇਲ ਲਈ ਅਸੀਂ ਨਾ-ਮਿਲਾਉਣ ਵਾਲਾ ਸਵਿੱਚ ਚਾਲੂ ਕਰਾਂਗੇ ਤਾਂ ਜੋ ਇਹ ਸਾਫ਼ ਪੰਦਰਾਂ ਪ੍ਰਤੀਸ਼ਤ ਹੀ ਰਹੇ।", "দুটি কাজের সুইচ — কোডকে প্রতি পরিবারে একবার ব্যবহারে সীমিত করুন, অথবা চেকআউটে অন্য কোডের সঙ্গে জোড়া লাগা আটকান। প্রধান সেলের জন্য আমরা মেলানো-নিষেধ সুইচ চালু করব, যাতে এটি পরিষ্কার পনেরো শতাংশই থাকে।", "مفتاحان مفيدان — اقصر الرمز على استخدام واحد لكل عائلة، أو امنعه من التراكم مع أي رمز آخر عند الدفع. في تخفيض رئيسي سنفعّل مفتاح عدم الدمج ليبقى خمسة عشر بالمئة نظيفة.", "Dois interruptores úteis — limite o código a uma utilização por família ou impeça-o de se acumular com outro no pagamento. Numa promoção principal vamos ativar o de não combinar, para ficar nos quinze por cento certinhos.", "Dos interruptores útiles: limita un código a un uso por familia o impide que se acumule con otro al pagar. Para unas rebajas principales marcaremos el de no combinar, para que quede un quince por ciento limpio.", "Deux interrupteurs pratiques — limitez le code à une utilisation par famille, ou empêchez-le de se cumuler avec un autre au paiement. Pour une grosse promo, nous cocherons l’option sans cumul pour que ça reste un quinze pour cent net.", "Dau switsh defnyddiol — cyfyngwch god i un defnydd y teulu, neu atal y cod rhag cyfuno ag unrhyw god arall wrth dalu. Ar gyfer gwerthiant pennawd byddwn yn ticio’r switsh dim cyfuno fel ei fod yn aros yn bymtheg y cant taclus."],
  "lt_marketing_s6": ["You could reserve this for a single family or a saved group — that messages and emails them and drops it into their Coupons area. We will leave it public, so it shows in every family's Coupons banner instead.", "Możesz zarezerwować go dla jednej rodziny lub zapisanej grupy — wtedy wysyłana jest do nich wiadomość i e-mail, a kod trafia do ich sekcji Kupony. Zostawimy go publicznym, więc pojawi się w banerze Kuponów każdej rodziny.", "Îl poți rezerva pentru o singură familie sau un grup salvat — asta le trimite mesaj și e-mail și îl pune în zona lor de Cupoane. Îl lăsăm public, așa că apare în bannerul de Cupoane al fiecărei familii.", "آپ اسے کسی ایک خاندان یا محفوظ کردہ گروپ کے لیے مخصوص کر سکتے ہیں — اس سے انہیں پیغام اور ای میل جاتی ہے اور کوڈ ان کے کوپنز والے حصے میں آ جاتا ہے۔ ہم اسے عوامی رکھتے ہیں، اس لیے یہ ہر خاندان کے کوپنز بینر میں دکھائی دے گا۔", "ਤੁਸੀਂ ਇਸਨੂੰ ਕਿਸੇ ਇੱਕ ਪਰਿਵਾਰ ਜਾਂ ਸੰਭਾਲੇ ਗਰੁੱਪ ਲਈ ਰਾਖਵਾਂ ਕਰ ਸਕਦੇ ਹੋ — ਇਸ ਨਾਲ ਉਨ੍ਹਾਂ ਨੂੰ ਸੁਨੇਹਾ ਅਤੇ ਈਮੇਲ ਜਾਂਦੀ ਹੈ ਅਤੇ ਕੋਡ ਉਨ੍ਹਾਂ ਦੇ ਕੂਪਨ ਖੇਤਰ ਵਿੱਚ ਆ ਜਾਂਦਾ ਹੈ। ਅਸੀਂ ਇਸਨੂੰ ਜਨਤਕ ਰੱਖਦੇ ਹਾਂ, ਇਸ ਲਈ ਇਹ ਹਰ ਪਰਿਵਾਰ ਦੇ ਕੂਪਨ ਬੈਨਰ ਵਿੱਚ ਦਿਸੇਗਾ।", "আপনি এটি একটি পরিবার বা সংরক্ষিত গ্রুপের জন্য সংরক্ষিত রাখতে পারেন — তাতে তাদের বার্তা ও ইমেইল যায় এবং কোডটি তাদের কুপন অংশে ঢুকে যায়। আমরা এটি পাবলিক রাখছি, তাই এটি প্রতিটি পরিবারের কুপন ব্যানারে দেখা যাবে।", "يمكنك حجزه لعائلة واحدة أو لمجموعة محفوظة — فيُرسَل إليهم رسالة وبريد إلكتروني ويُضاف إلى قسم القسائم الخاص بهم. سنتركه عامًا، فيظهر في لافتة القسائم لدى كل عائلة.", "Pode reservá-lo para uma só família ou um grupo guardado — isso envia-lhes mensagem e e-mail e coloca-o na sua área de Cupões. Vamos deixá-lo público, por isso aparece no banner de Cupões de todas as famílias.", "Puedes reservarlo para una sola familia o un grupo guardado: eso les envía un mensaje y un correo y lo pone en su área de Cupones. Lo dejaremos público, así que aparece en el banner de Cupones de todas las familias.", "Vous pouvez le réserver à une seule famille ou à un groupe enregistré — cela leur envoie un message et un e-mail et le place dans leur espace Coupons. Nous le laissons public, donc il apparaît dans la bannière Coupons de chaque famille.", "Gallwch ei neilltuo ar gyfer un teulu neu grŵp wedi’i gadw — mae hynny’n anfon neges ac e-bost atynt ac yn ei roi yn eu hardal Cwponau. Gadawn ef yn gyhoeddus, felly mae’n dangos ym maner Cwponau pob teulu yn lle hynny."],
  "lt_marketing_s7": ["And that is the lot. Pressing Create code saves it and it goes live straight away — parents can type SUMMER25 at checkout and the fifteen percent comes off automatically.", "I to wszystko. Naciśnięcie Utwórz kod zapisuje go i od razu działa — rodzice wpisują SUMMER25 przy płatności, a piętnaście procent odejmuje się automatycznie.", "Asta e tot. Apăsarea pe Creează cod îl salvează și intră imediat în vigoare — părinții pot scrie SUMMER25 la finalizare, iar cele cincisprezece la sută se scad automat.", "بس یہی سب کچھ ہے۔ کوڈ بنائیں دبانے سے یہ محفوظ ہو کر فوراً لائیو ہو جاتا ہے — والدین ادائیگی پر SUMMER25 لکھیں اور پندرہ فیصد رعایت خود بخود لگ جاتی ہے۔", "ਬੱਸ ਇੰਨਾ ਹੀ। ਕੋਡ ਬਣਾਓ ਦਬਾਉਣ ਨਾਲ ਇਹ ਸੰਭਲ ਜਾਂਦਾ ਹੈ ਅਤੇ ਤੁਰੰਤ ਲਾਈਵ ਹੋ ਜਾਂਦਾ ਹੈ — ਮਾਪੇ ਭੁਗਤਾਨ ਵੇਲੇ SUMMER25 ਲਿਖਣ ਅਤੇ ਪੰਦਰਾਂ ਪ੍ਰਤੀਸ਼ਤ ਛੋਟ ਆਪਣੇ ਆਪ ਲੱਗ ਜਾਂਦੀ ਹੈ।", "এটুকুই। কোড তৈরি করুন চাপলে এটি সংরক্ষিত হয়ে সঙ্গে সঙ্গে লাইভ হয় — অভিভাবকরা চেকআউটে SUMMER25 লিখলেই পনেরো শতাংশ ছাড় নিজে থেকে কেটে যায়।", "وهذا كل شيء. بالضغط على إنشاء رمز يُحفظ ويصبح فعّالًا فورًا — يكتب أولياء الأمور SUMMER25 عند الدفع فيُخصم خمسة عشر بالمئة تلقائيًا.", "E é tudo. Premir Criar código guarda-o e fica logo ativo — os pais podem escrever SUMMER25 no pagamento e os quinze por cento saem automaticamente.", "Y eso es todo. Al pulsar Crear código se guarda y se activa enseguida: los padres pueden escribir SUMMER25 al pagar y el quince por ciento se descuenta automáticamente.", "Et c’est tout. Appuyer sur Créer le code l’enregistre et il est actif aussitôt — les parents peuvent saisir SUMMER25 au paiement et les quinze pour cent se déduisent automatiquement.", "A dyna’r cyfan. Mae pwyso Creu cod yn ei gadw ac mae’n mynd yn fyw ar unwaith — gall rhieni deipio SUMMER25 wrth dalu ac mae’r pymtheg y cant yn dod i ffwrdd yn awtomatig."],
  "lt_listings_title": ["Listings, services & tickets", "Oferty, usługi i bilety", "Oferte, servicii și bilete", "لسٹنگز، خدمات اور ٹکٹ", "ਲਿਸਟਿੰਗਾਂ, ਸੇਵਾਵਾਂ ਅਤੇ ਟਿਕਟਾਂ", "লিস্টিং, সেবা ও টিকিট", "الإعلانات والخدمات والتذاكر", "Anúncios, serviços e bilhetes", "Anuncios, servicios y entradas", "Annonces, services et billets", "Rhestriadau, gwasanaethau a thocynnau"],
  "lt_listings_intro": ["Every camp, club and class you offer is a listing — its own page parents can find and book. Three things live in your setup first: your venues, their locations, and your seasons. With those ready, let me build a listing with you.", "Każdy obóz, zajęcia i kurs, które oferujesz, to oferta — własna strona, którą rodzice mogą znaleźć i zarezerwować. Najpierw w konfiguracji są trzy rzeczy: miejsca, ich lokalizacje i sezony. Gdy są gotowe, zbudujmy razem ofertę.", "Fiecare tabără, club și curs pe care îl oferi este o ofertă — propria pagină pe care părinții o pot găsi și rezerva. Trei lucruri există mai întâi în configurare: locurile, locațiile lor și sezoanele. Când sunt gata, hai să construim o ofertă împreună.", "آپ جو بھی کیمپ، کلب اور کلاس پیش کرتے ہیں وہ ایک لسٹنگ ہے — اس کا اپنا صفحہ جو والدین تلاش کر کے بک کر سکتے ہیں۔ تین چیزیں پہلے آپ کے سیٹ اپ میں ہوتی ہیں: آپ کے مقامات، ان کی لوکیشنز اور آپ کے سیزن۔ وہ تیار ہوں تو آئیں آپ کے ساتھ ایک لسٹنگ بناتے ہیں۔", "ਤੁਹਾਡਾ ਹਰ ਕੈਂਪ, ਕਲੱਬ ਅਤੇ ਕਲਾਸ ਇੱਕ ਲਿਸਟਿੰਗ ਹੈ — ਉਸਦਾ ਆਪਣਾ ਪੰਨਾ ਜੋ ਮਾਪੇ ਲੱਭ ਕੇ ਬੁੱਕ ਕਰ ਸਕਦੇ ਹਨ। ਤਿੰਨ ਚੀਜ਼ਾਂ ਪਹਿਲਾਂ ਤੁਹਾਡੇ ਸੈੱਟਅੱਪ ਵਿੱਚ ਹੁੰਦੀਆਂ ਹਨ: ਤੁਹਾਡੀਆਂ ਥਾਵਾਂ, ਉਨ੍ਹਾਂ ਦੀਆਂ ਲੋਕੇਸ਼ਨਾਂ ਅਤੇ ਤੁਹਾਡੇ ਸੀਜ਼ਨ। ਉਹ ਤਿਆਰ ਹੋਣ ਤਾਂ ਆਓ ਤੁਹਾਡੇ ਨਾਲ ਇੱਕ ਲਿਸਟਿੰਗ ਬਣਾਈਏ।", "আপনার দেওয়া প্রতিটি ক্যাম্প, ক্লাব ও ক্লাস একটি লিস্টিং — তার নিজস্ব পাতা, যা অভিভাবকরা খুঁজে বুক করতে পারেন। আগে সেটআপে তিনটি জিনিস থাকে: আপনার ভেন্যু, তাদের লোকেশন ও আপনার সিজন। সেগুলো তৈরি হলে আসুন আপনার সঙ্গে একটি লিস্টিং বানাই।", "كل مخيم ونادٍ وحصة تقدمها هو إعلان — له صفحته الخاصة التي يمكن لأولياء الأمور العثور عليها وحجزها. ثلاثة أمور تكون أولًا في الإعداد: أماكنك ومواقعها ومواسمك. وعندما تكون جاهزة، دعنا نبني إعلانًا معك.", "Cada campo, clube e aula que oferece é um anúncio — a sua própria página que os pais podem encontrar e reservar. Três coisas existem primeiro na configuração: os seus espaços, as suas localizações e as suas épocas. Com isso pronto, vamos criar um anúncio consigo.", "Cada campamento, club y clase que ofreces es un anuncio: su propia página que los padres pueden encontrar y reservar. Tres cosas viven antes en tu configuración: tus locales, sus ubicaciones y tus temporadas. Con eso listo, vamos a crear un anuncio juntos.", "Chaque camp, club et cours que vous proposez est une annonce — sa propre page que les parents peuvent trouver et réserver. Trois choses existent d’abord dans votre configuration : vos lieux, leurs emplacements et vos saisons. Une fois prêts, construisons une annonce ensemble.", "Mae pob gwersyll, clwb a dosbarth rydych yn ei gynnig yn rhestriad — ei dudalen ei hun y gall rhieni ddod o hyd iddi a’i harchebu. Mae tri pheth yn eich gosodiad yn gyntaf: eich lleoliadau, eu safleoedd a’ch tymhorau. Gyda’r rheini’n barod, gadewch i ni adeiladu rhestriad gyda’n gilydd."],
  "lt_listings_done": ["That's a listing built — a polished page parents can find and book in minutes.", "Oferta gotowa — dopracowana strona, którą rodzice mogą znaleźć i zarezerwować w kilka minut.", "Oferta e gata — o pagină îngrijită pe care părinții o pot găsi și rezerva în câteva minute.", "لسٹنگ تیار ہو گئی — ایک نفیس صفحہ جو والدین منٹوں میں تلاش کر کے بک کر سکتے ہیں۔", "ਲਿਸਟਿੰਗ ਤਿਆਰ ਹੋ ਗਈ — ਇੱਕ ਸੁਚੱਜਾ ਪੰਨਾ ਜੋ ਮਾਪੇ ਮਿੰਟਾਂ ਵਿੱਚ ਲੱਭ ਕੇ ਬੁੱਕ ਕਰ ਸਕਦੇ ਹਨ।", "লিস্টিং তৈরি — একটি পরিপাটি পাতা, যা অভিভাবকরা মিনিটের মধ্যে খুঁজে বুক করতে পারেন।", "تم بناء الإعلان — صفحة أنيقة يمكن لأولياء الأمور العثور عليها وحجزها في دقائق.", "O anúncio está feito — uma página cuidada que os pais podem encontrar e reservar em minutos.", "Anuncio creado: una página pulida que los padres pueden encontrar y reservar en minutos.", "L’annonce est prête — une page soignée que les parents peuvent trouver et réserver en quelques minutes.", "Mae’r rhestriad wedi’i adeiladu — tudalen raenus y gall rhieni ddod o hyd iddi a’i harchebu mewn munudau."],
  "lt_listings_s0": ["Press New listing, and the step-by-step builder opens.", "Naciśnij Nowa oferta, a otworzy się kreator krok po kroku.", "Apasă Ofertă nouă și se deschide generatorul pas cu pas.", "نئی لسٹنگ دبائیں، اور قدم بہ قدم بنانے والا کھل جاتا ہے۔", "ਨਵੀਂ ਲਿਸਟਿੰਗ ਦਬਾਓ, ਅਤੇ ਕਦਮ-ਦਰ-ਕਦਮ ਬਿਲਡਰ ਖੁੱਲ੍ਹ ਜਾਂਦਾ ਹੈ।", "নতুন লিস্টিং চাপুন, আর ধাপে ধাপে তৈরির টুল খুলে যায়।", "اضغط إعلان جديد فيفتح المُنشئ خطوة بخطوة.", "Prima Novo anúncio e abre-se o assistente passo a passo.", "Pulsa Nuevo anuncio y se abre el asistente paso a paso.", "Appuyez sur Nouvelle annonce et l’assistant pas à pas s’ouvre.", "Pwyswch Rhestriad newydd ac mae’r adeiladwr cam wrth gam yn agor."],
  "lt_listings_s1": ["First, a clear name — Summer Holiday Multi-Sports Camp.", "Najpierw czytelna nazwa — Letni Obóz Wielosportowy.", "Mai întâi un nume clar — Tabăra de vară multisport.", "پہلے ایک واضح نام — سمر ہالیڈے ملٹی سپورٹس کیمپ۔", "ਪਹਿਲਾਂ ਇੱਕ ਸਾਫ਼ ਨਾਮ — ਸਮਰ ਹੌਲੀਡੇ ਮਲਟੀ-ਸਪੋਰਟਸ ਕੈਂਪ।", "প্রথমে একটি স্পষ্ট নাম — সামার হলিডে মাল্টি-স্পোর্টস ক্যাম্প।", "أولًا اسم واضح — مخيم العطلة الصيفية متعدد الرياضات.", "Primeiro, um nome claro — Campo de Férias de Verão Multidesportos.", "Primero, un nombre claro: Campamento multideporte de vacaciones de verano.", "D’abord un nom clair — Camp multisports des vacances d’été.", "Yn gyntaf, enw clir — Gwersyll Aml-chwaraeon Gwyliau’r Haf."],
  "lt_listings_s2": ["Add your main photo, then crop and move it with these sliders — this preview is exactly what parents see. Smaller shots go in the gallery below, which parents swipe through on the booking page.", "Dodaj główne zdjęcie, a potem przytnij je i przesuń tymi suwakami — ten podgląd to dokładnie to, co widzą rodzice. Mniejsze zdjęcia trafiają do galerii poniżej, którą rodzice przewijają na stronie rezerwacji.", "Adaugă fotografia principală, apoi decupeaz-o și mut-o cu aceste glisoare — această previzualizare este exact ce văd părinții. Pozele mai mici merg în galeria de dedesubt, pe care părinții o derulează pe pagina de rezervare.", "اپنی مرکزی تصویر شامل کریں، پھر ان سلائیڈرز سے اسے کاٹیں اور ہلائیں — یہ پیش منظر بالکل وہی ہے جو والدین دیکھتے ہیں۔ چھوٹی تصاویر نیچے گیلری میں جاتی ہیں، جسے والدین بکنگ کے صفحے پر سوائپ کرتے ہیں۔", "ਆਪਣੀ ਮੁੱਖ ਫੋਟੋ ਜੋੜੋ, ਫਿਰ ਇਨ੍ਹਾਂ ਸਲਾਈਡਰਾਂ ਨਾਲ ਉਸਨੂੰ ਕੱਟੋ ਅਤੇ ਹਿਲਾਓ — ਇਹ ਝਲਕ ਬਿਲਕੁਲ ਉਹੀ ਹੈ ਜੋ ਮਾਪੇ ਦੇਖਦੇ ਹਨ। ਛੋਟੀਆਂ ਫੋਟੋਆਂ ਹੇਠਾਂ ਗੈਲਰੀ ਵਿੱਚ ਜਾਂਦੀਆਂ ਹਨ, ਜਿਸਨੂੰ ਮਾਪੇ ਬੁਕਿੰਗ ਪੰਨੇ ਉੱਤੇ ਸਵਾਈਪ ਕਰਦੇ ਹਨ।", "আপনার প্রধান ছবি যোগ করুন, তারপর এই স্লাইডার দিয়ে ক্রপ করে সরান — এই প্রিভিউ ঠিক তা-ই যা অভিভাবকরা দেখেন। ছোট ছবিগুলো নিচের গ্যালারিতে যায়, যা অভিভাবকরা বুকিং পাতায় সোয়াইপ করে দেখেন।", "أضف صورتك الرئيسية، ثم اقصّها وحرّكها بهذه المنزلقات — هذه المعاينة هي بالضبط ما يراه أولياء الأمور. الصور الأصغر تذهب إلى المعرض أدناه، ويتصفحه أولياء الأمور بالسحب في صفحة الحجز.", "Adicione a foto principal, depois recorte-a e mova-a com estes controlos — esta pré-visualização é exatamente o que os pais veem. As fotos mais pequenas vão para a galeria abaixo, que os pais deslizam na página de reserva.", "Añade tu foto principal y luego recórtala y muévela con estos deslizadores: esta vista previa es exactamente lo que ven los padres. Las fotos más pequeñas van a la galería de abajo, que los padres recorren deslizando en la página de reserva.", "Ajoutez votre photo principale, puis recadrez-la et déplacez-la avec ces curseurs — cet aperçu est exactement ce que voient les parents. Les photos plus petites vont dans la galerie en dessous, que les parents font défiler sur la page de réservation.", "Ychwanegwch eich prif lun, yna ei docio a’i symud gyda’r llithrwyr hyn — mae’r rhagolwg hwn yn union yr hyn y mae rhieni’n ei weld. Mae lluniau llai yn mynd yn yr oriel isod, y mae rhieni’n swipio trwyddi ar y dudalen archebu."],
  "lt_listings_s3": ["Now where and who. Your venues, locations and seasons are set up beforehand — here you just pick them. If you haven't yet, use the link below. I'll choose Riverside, ages five to twelve.", "Teraz gdzie i dla kogo. Miejsca, lokalizacje i sezony są ustawione wcześniej — tu tylko je wybierasz. Jeśli jeszcze ich nie masz, skorzystaj z linku poniżej. Wybiorę Riverside, wiek od pięciu do dwunastu lat.", "Acum unde și pentru cine. Locurile, locațiile și sezoanele sunt configurate dinainte — aici doar le alegi. Dacă încă nu le ai, folosește linkul de mai jos. Eu aleg Riverside, vârste de la cinci la doisprezece ani.", "اب کہاں اور کن کے لیے۔ آپ کے مقامات، لوکیشنز اور سیزن پہلے سے سیٹ اپ میں ہوتے ہیں — یہاں بس انہیں چننا ہے۔ اگر ابھی نہیں بنائے تو نیچے کا لنک استعمال کریں۔ میں ریور سائیڈ چنتا ہوں، عمر پانچ سے بارہ سال۔", "ਹੁਣ ਕਿੱਥੇ ਅਤੇ ਕਿਨ੍ਹਾਂ ਲਈ। ਤੁਹਾਡੀਆਂ ਥਾਵਾਂ, ਲੋਕੇਸ਼ਨਾਂ ਅਤੇ ਸੀਜ਼ਨ ਪਹਿਲਾਂ ਹੀ ਸੈੱਟਅੱਪ ਵਿੱਚ ਹੁੰਦੇ ਹਨ — ਇੱਥੇ ਬੱਸ ਚੁਣਨੇ ਹਨ। ਜੇ ਅਜੇ ਨਹੀਂ ਬਣਾਏ ਤਾਂ ਹੇਠਾਂ ਦਾ ਲਿੰਕ ਵਰਤੋ। ਮੈਂ ਰਿਵਰਸਾਈਡ ਚੁਣਦਾ ਹਾਂ, ਉਮਰ ਪੰਜ ਤੋਂ ਬਾਰਾਂ ਸਾਲ।", "এবার কোথায় ও কাদের জন্য। আপনার ভেন্যু, লোকেশন ও সিজন আগেই সেটআপে থাকে — এখানে শুধু বেছে নেবেন। এখনও না করে থাকলে নিচের লিংক ব্যবহার করুন। আমি রিভারসাইড বাছছি, বয়স পাঁচ থেকে বারো।", "الآن أين ولمن. أماكنك ومواقعك ومواسمك مُعدّة مسبقًا — وهنا تختارها فقط. وإن لم تنشئها بعد فاستخدم الرابط أدناه. سأختار ريفرسايد، لأعمار من خمس إلى اثنتي عشرة سنة.", "Agora onde e para quem. Os seus espaços, localizações e épocas são definidos antes — aqui só os escolhe. Se ainda não o fez, use a ligação abaixo. Vou escolher Riverside, idades dos cinco aos doze anos.", "Ahora dónde y para quién. Tus locales, ubicaciones y temporadas se configuran antes; aquí solo los eliges. Si aún no lo has hecho, usa el enlace de abajo. Yo elegiré Riverside, de cinco a doce años.", "Maintenant, où et pour qui. Vos lieux, emplacements et saisons sont configurés au préalable — ici, vous les choisissez simplement. Si ce n’est pas encore fait, utilisez le lien ci-dessous. Je choisis Riverside, de cinq à douze ans.", "Nawr ble a phwy. Mae eich lleoliadau, eich safleoedd a’ch tymhorau wedi’u gosod ymlaen llaw — yma dim ond eu dewis sydd angen. Os nad ydych wedi gwneud eto, defnyddiwch y ddolen isod. Dewisaf Riverside, oedrannau pump i ddeuddeg."],
  "lt_listings_s3k": ["Set up your venues, locations & seasons ↗", "Skonfiguruj miejsca, lokalizacje i sezony ↗", "Configurează locurile, locațiile și sezoanele ↗", "اپنے مقامات، لوکیشنز اور سیزن سیٹ اپ کریں ↗", "ਆਪਣੀਆਂ ਥਾਵਾਂ, ਲੋਕੇਸ਼ਨਾਂ ਅਤੇ ਸੀਜ਼ਨ ਸੈੱਟਅੱਪ ਕਰੋ ↗", "আপনার ভেন্যু, লোকেশন ও সিজন সেটআপ করুন ↗", "أعدّ أماكنك ومواقعك ومواسمك ↗", "Configure os seus espaços, localizações e épocas ↗", "Configura tus locales, ubicaciones y temporadas ↗", "Configurez vos lieux, emplacements et saisons ↗", "Gosodwch eich lleoliadau, safleoedd a thymhorau ↗"],
  "lt_listings_s4": ["Tick a category so parents can find it — a holiday multi-activity camp.", "Zaznacz kategorię, żeby rodzice mogli ją znaleźć — wakacyjny obóz wielozajęciowy.", "Bifează o categorie ca părinții să o găsească — o tabără de vacanță multi-activități.", "ایک زمرہ چنیں تاکہ والدین اسے ڈھونڈ سکیں — چھٹیوں کا ملٹی ایکٹیویٹی کیمپ۔", "ਇੱਕ ਸ਼੍ਰੇਣੀ ਚੁਣੋ ਤਾਂ ਜੋ ਮਾਪੇ ਇਸਨੂੰ ਲੱਭ ਸਕਣ — ਛੁੱਟੀਆਂ ਦਾ ਮਲਟੀ-ਐਕਟੀਵਿਟੀ ਕੈਂਪ।", "একটি বিভাগ টিক দিন যাতে অভিভাবকরা খুঁজে পান — ছুটির মাল্টি-অ্যাক্টিভিটি ক্যাম্প।", "اختر فئة ليجده أولياء الأمور — مخيم عطلة متعدد الأنشطة.", "Assinale uma categoria para os pais o encontrarem — um campo de férias multiatividades.", "Marca una categoría para que los padres lo encuentren: un campamento de vacaciones multiactividad.", "Cochez une catégorie pour que les parents la trouvent — un camp de vacances multi-activités.", "Ticiwch gategori fel bod rhieni’n gallu dod o hyd iddo — gwersyll gwyliau aml-weithgaredd."],
  "lt_listings_s5": ["How many can come — I'll cap this at sixty for the whole listing.", "Ile osób może przyjść — ustawię limit sześćdziesięciu na całą ofertę.", "Câți pot veni — aici pun o limită de șaizeci pentru întreaga ofertă.", "کتنے لوگ آ سکتے ہیں — میں پوری لسٹنگ کے لیے حد ساٹھ رکھتا ہوں۔", "ਕਿੰਨੇ ਆ ਸਕਦੇ ਹਨ — ਮੈਂ ਪੂਰੀ ਲਿਸਟਿੰਗ ਲਈ ਹੱਦ ਸੱਠ ਰੱਖਦਾ ਹਾਂ।", "কতজন আসতে পারবে — আমি পুরো লিস্টিংয়ের জন্য সীমা ষাট রাখছি।", "كم عدد من يمكنهم الحضور — سأحدد السقف بستين للإعلان كله.", "Quantos podem vir — vou limitar a sessenta para todo o anúncio.", "Cuántos pueden venir: pondré un tope de sesenta para todo el anuncio.", "Combien peuvent venir — je plafonne à soixante pour toute l’annonce.", "Faint all ddod — capiaf hyn ar chwe deg ar gyfer y rhestriad cyfan."],
  "lt_listings_s6": ["And you can cap places per age group on top of that — so only so many of your sixty go to the youngest.", "A dodatkowo możesz ograniczyć miejsca dla każdej grupy wiekowej — tak, by najmłodszym przypadła tylko część z sześćdziesięciu.", "Și poți plafona locurile pe grupe de vârstă în plus — astfel încât doar un anumit număr din cele șaizeci să meargă la cei mai mici.", "اس کے علاوہ آپ ہر عمر کے گروپ کے لیے نشستوں کی حد بھی رکھ سکتے ہیں — تاکہ ساٹھ میں سے سب سے چھوٹوں کو صرف اتنی جگہیں ملیں۔", "ਇਸ ਤੋਂ ਇਲਾਵਾ ਤੁਸੀਂ ਹਰ ਉਮਰ-ਗਰੁੱਪ ਲਈ ਥਾਵਾਂ ਦੀ ਹੱਦ ਵੀ ਰੱਖ ਸਕਦੇ ਹੋ — ਤਾਂ ਜੋ ਸੱਠ ਵਿੱਚੋਂ ਸਭ ਤੋਂ ਛੋਟਿਆਂ ਨੂੰ ਸਿਰਫ਼ ਇੰਨੀਆਂ ਹੀ ਮਿਲਣ।", "এর ওপর আপনি প্রতিটি বয়স-গ্রুপের জন্যও আসন সীমা দিতে পারেন — যাতে ষাটের মধ্যে ছোটদের জন্য নির্দিষ্ট সংখ্যকই থাকে।", "ويمكنك أيضًا تحديد سقف للأماكن لكل فئة عمرية — فلا يذهب سوى عدد معين من الستين إلى الأصغر سنًا.", "E pode ainda limitar os lugares por grupo etário — para que só tantos dos sessenta vão para os mais novos.", "Y además puedes limitar las plazas por grupo de edad, de modo que solo unas cuantas de las sesenta vayan a los más pequeños.", "Et vous pouvez en plus plafonner les places par tranche d’âge — pour que seule une partie des soixante aille aux plus jeunes.", "Gallwch hefyd gapio lleoedd fesul grŵp oedran ar ben hynny — fel mai dim ond cymaint o’r chwe deg sy’n mynd i’r ieuengaf."],
  "lt_listings_s7": ["Describe it — type a few words, then Write with AI turns them into a polished paragraph for you.", "Opisz ofertę — wpisz kilka słów, a Napisz z AI zamieni je w dopracowany akapit.", "Descrie oferta — scrie câteva cuvinte, apoi Scrie cu AI le transformă într-un paragraf îngrijit.", "اسے بیان کریں — چند الفاظ لکھیں، پھر اے آئی سے لکھیں انہیں ایک نفیس پیراگراف بنا دیتا ہے۔", "ਇਸਦਾ ਵੇਰਵਾ ਲਿਖੋ — ਕੁਝ ਸ਼ਬਦ ਲਿਖੋ, ਫਿਰ AI ਨਾਲ ਲਿਖੋ ਉਨ੍ਹਾਂ ਨੂੰ ਇੱਕ ਸੁਚੱਜਾ ਪੈਰਾ ਬਣਾ ਦਿੰਦਾ ਹੈ।", "এর বর্ণনা দিন — কয়েকটি শব্দ লিখুন, তারপর এআই দিয়ে লিখুন সেগুলোকে একটি পরিপাটি অনুচ্ছেদে বদলে দেয়।", "صِف الإعلان — اكتب بضع كلمات ثم يحوّلها اكتب بالذكاء الاصطناعي إلى فقرة متقنة.", "Descreva-o — escreva algumas palavras e Escrever com IA transforma-as num parágrafo cuidado.", "Descríbelo: escribe unas palabras y Escribir con IA las convierte en un párrafo pulido.", "Décrivez-la — tapez quelques mots, puis Rédiger avec l’IA les transforme en un paragraphe soigné.", "Disgrifiwch ef — teipiwch ychydig eiriau, yna mae Ysgrifennu gydag AI yn eu troi’n baragraff caboledig i chi."],
  "lt_listings_s8": ["Tick everything that's included — a hot lunch, all equipment, a certificate — it all shows on the listing.", "Zaznacz wszystko, co jest w cenie — ciepły lunch, cały sprzęt, certyfikat — wszystko to pojawi się w ofercie.", "Bifează tot ce este inclus — un prânz cald, toate echipamentele, o diplomă — totul apare în ofertă.", "وہ سب چنیں جو شامل ہے — گرم دوپہر کا کھانا، تمام سامان، سرٹیفکیٹ — یہ سب لسٹنگ پر دکھائی دیتا ہے۔", "ਉਹ ਸਭ ਕੁਝ ਚੁਣੋ ਜੋ ਸ਼ਾਮਲ ਹੈ — ਗਰਮ ਦੁਪਹਿਰ ਦਾ ਖਾਣਾ, ਸਾਰਾ ਸਾਮਾਨ, ਸਰਟੀਫਿਕੇਟ — ਇਹ ਸਭ ਲਿਸਟਿੰਗ ਉੱਤੇ ਦਿਸਦਾ ਹੈ।", "যা যা অন্তর্ভুক্ত সব টিক দিন — গরম দুপুরের খাবার, সব সরঞ্জাম, একটি সার্টিফিকেট — সবই লিস্টিংয়ে দেখা যায়।", "حدّد كل ما هو مشمول — وجبة غداء ساخنة وجميع المعدات وشهادة — وكله يظهر في الإعلان.", "Assinale tudo o que está incluído — um almoço quente, todo o equipamento, um certificado — tudo aparece no anúncio.", "Marca todo lo que está incluido (una comida caliente, todo el equipo, un certificado) y todo aparece en el anuncio.", "Cochez tout ce qui est inclus — un déjeuner chaud, tout le matériel, un certificat — tout s’affiche dans l’annonce.", "Ticiwch bopeth sydd wedi’i gynnwys — cinio poeth, yr holl offer, tystysgrif — mae’r cyfan yn dangos ar y rhestriad."],
  "lt_listings_s9": ["Tick your safety features and SEND support, so families know everyone's looked after.", "Zaznacz swoje zabezpieczenia i wsparcie SEND, aby rodziny wiedziały, że każdym się zajęto.", "Bifează măsurile de siguranță și sprijinul SEND, ca familiile să știe că toți sunt în grija cuiva.", "اپنی حفاظتی خصوصیات اور SEND سپورٹ چنیں تاکہ خاندان جان لیں کہ ہر کسی کا خیال رکھا جاتا ہے۔", "ਆਪਣੀਆਂ ਸੁਰੱਖਿਆ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਅਤੇ SEND ਸਹਾਇਤਾ ਚੁਣੋ, ਤਾਂ ਜੋ ਪਰਿਵਾਰਾਂ ਨੂੰ ਪਤਾ ਲੱਗੇ ਕਿ ਹਰ ਕਿਸੇ ਦੀ ਸੰਭਾਲ ਹੁੰਦੀ ਹੈ।", "আপনার নিরাপত্তা ব্যবস্থা ও এসইএনডি সহায়তা টিক দিন, যাতে পরিবারগুলো জানে সবার যত্ন নেওয়া হয়।", "حدّد ميزات السلامة لديك ودعم ذوي الاحتياجات التعليمية الخاصة (SEND)، ليعرف الأهالي أن الجميع في رعاية جيدة.", "Assinale as suas características de segurança e o apoio SEND, para que as famílias saibam que todos são bem cuidados.", "Marca tus medidas de seguridad y el apoyo SEND, para que las familias sepan que todos están bien cuidados.", "Cochez vos dispositifs de sécurité et votre soutien SEND, pour que les familles sachent que chacun est bien pris en charge.", "Ticiwch eich nodweddion diogelwch a’ch cymorth ADY, fel bod teuluoedd yn gwybod bod pawb yn cael gofal."],
  "lt_listings_s10": ["Set the dates — the first week of August — and the calendar builds every session for you.", "Ustaw daty — pierwszy tydzień sierpnia — a kalendarz sam zbuduje wszystkie sesje.", "Setează datele — prima săptămână din august — iar calendarul construiește singur fiecare sesiune.", "تاریخیں مقرر کریں — اگست کا پہلا ہفتہ — اور کیلنڈر خود ہر سیشن بنا دیتا ہے۔", "ਤਾਰੀਖ਼ਾਂ ਤੈਅ ਕਰੋ — ਅਗਸਤ ਦਾ ਪਹਿਲਾ ਹਫ਼ਤਾ — ਅਤੇ ਕੈਲੰਡਰ ਆਪਣੇ ਆਪ ਹਰ ਸੈਸ਼ਨ ਬਣਾ ਦਿੰਦਾ ਹੈ।", "তারিখ ঠিক করুন — আগস্টের প্রথম সপ্তাহ — আর ক্যালেন্ডার নিজেই প্রতিটি সেশন তৈরি করে দেয়।", "حدّد التواريخ — الأسبوع الأول من أغسطس — ويبني التقويم كل جلسة من تلقاء نفسه.", "Defina as datas — a primeira semana de agosto — e o calendário cria cada sessão por si.", "Fija las fechas (la primera semana de agosto) y el calendario construye todas las sesiones por ti.", "Fixez les dates — la première semaine d’août — et le calendrier construit chaque séance pour vous.", "Gosodwch y dyddiadau — wythnos gyntaf Awst — ac mae’r calendr yn adeiladu pob sesiwn i chi."],
  "lt_listings_s11": ["Your tickets come from a block you built in Blocks — I'll pick this one and its passes and prices drop straight in. Not built one yet? Use the link below. And you can Save draft at any time and come back to finish this listing later.", "Bilety pochodzą z bloku, który zbudowałeś w Blokach — wybiorę ten, a jego karnety i ceny wskoczą od razu. Jeszcze nie masz bloku? Użyj linku poniżej. W każdej chwili możesz Zapisać wersję roboczą i wrócić do tej oferty później.", "Biletele vin dintr-un bloc pe care l-ai construit în Blocuri — îl aleg pe acesta, iar abonamentele și prețurile lui apar direct. Nu ai construit încă unul? Folosește linkul de mai jos. Poți salva oricând o ciornă și reveni mai târziu la această ofertă.", "آپ کے ٹکٹ اس بلاک سے آتے ہیں جو آپ نے بلاکس میں بنایا — میں یہ والا چنتا ہوں اور اس کے پاسز اور قیمتیں سیدھی آ جاتی ہیں۔ ابھی کوئی نہیں بنایا؟ نیچے کا لنک استعمال کریں۔ اور آپ کسی بھی وقت مسودہ محفوظ کر کے بعد میں یہ لسٹنگ مکمل کر سکتے ہیں۔", "ਤੁਹਾਡੀਆਂ ਟਿਕਟਾਂ ਉਸ ਬਲਾਕ ਤੋਂ ਆਉਂਦੀਆਂ ਹਨ ਜੋ ਤੁਸੀਂ ਬਲਾਕਾਂ ਵਿੱਚ ਬਣਾਇਆ — ਮੈਂ ਇਹ ਵਾਲਾ ਚੁਣਦਾ ਹਾਂ ਅਤੇ ਉਸ ਦੇ ਪਾਸ ਤੇ ਕੀਮਤਾਂ ਸਿੱਧੇ ਆ ਜਾਂਦੇ ਹਨ। ਅਜੇ ਕੋਈ ਨਹੀਂ ਬਣਾਇਆ? ਹੇਠਾਂ ਦਾ ਲਿੰਕ ਵਰਤੋ। ਅਤੇ ਤੁਸੀਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਖਰੜਾ ਸੰਭਾਲ ਕੇ ਬਾਅਦ ਵਿੱਚ ਇਹ ਲਿਸਟਿੰਗ ਪੂਰੀ ਕਰ ਸਕਦੇ ਹੋ।", "আপনার টিকিট আসে আপনার ব্লকস-এ বানানো ব্লক থেকে — আমি এটি বাছছি, আর এর পাস ও দাম সরাসরি চলে আসে। এখনও বানাননি? নিচের লিংক ব্যবহার করুন। আর যেকোনো সময় খসড়া সংরক্ষণ করে পরে এই লিস্টিং শেষ করতে পারেন।", "تأتي تذاكرك من كتلة بنيتها في الكتل — سأختار هذه فتنزل تصاريحها وأسعارها مباشرة. لم تبنِ واحدة بعد؟ استخدم الرابط أدناه. ويمكنك حفظ مسودة في أي وقت والعودة لإنهاء هذا الإعلان لاحقًا.", "Os seus bilhetes vêm de um bloco que criou em Blocos — vou escolher este e os seus passes e preços entram logo. Ainda não criou nenhum? Use a ligação abaixo. E pode Guardar rascunho a qualquer momento e voltar para terminar este anúncio mais tarde.", "Tus entradas vienen de un bloque que creaste en Bloques: elegiré este y sus pases y precios entran directamente. ¿Aún no has creado ninguno? Usa el enlace de abajo. Y puedes Guardar borrador en cualquier momento y volver para terminar este anuncio más tarde.", "Vos billets viennent d’un bloc que vous avez créé dans Blocs — je choisis celui-ci et ses forfaits et prix s’insèrent directement. Vous n’en avez pas encore créé ? Utilisez le lien ci-dessous. Et vous pouvez Enregistrer le brouillon à tout moment et revenir terminer cette annonce plus tard.", "Daw eich tocynnau o floc a adeiladoch yn Blociau — dewisaf yr un hwn ac mae ei docynnau a’i brisiau’n disgyn yn syth i mewn. Heb adeiladu un eto? Defnyddiwch y ddolen isod. A gallwch Gadw drafft unrhyw bryd a dod yn ôl i orffen y rhestriad hwn yn nes ymlaen."],
  "lt_listings_s11k": ["No block yet? Build one in Blocks ↗", "Nie masz jeszcze bloku? Zbuduj go w Blokach ↗", "Nu ai încă un bloc? Construiește unul în Blocuri ↗", "ابھی کوئی بلاک نہیں؟ بلاکس میں بنائیں ↗", "ਅਜੇ ਕੋਈ ਬਲਾਕ ਨਹੀਂ? ਬਲਾਕਾਂ ਵਿੱਚ ਬਣਾਓ ↗", "এখনও ব্লক নেই? ব্লকস-এ একটি বানান ↗", "لا توجد كتلة بعد؟ ابنِ واحدة في الكتل ↗", "Ainda sem bloco? Crie um em Blocos ↗", "¿Aún no tienes un bloque? Crea uno en Bloques ↗", "Pas encore de bloc ? Créez-en un dans Blocs ↗", "Dim bloc eto? Adeiladwch un yn Blociau ↗"],
  "lt_listings_s12": ["Add automatic discounts if you like — a sibling or early-bird deal that comes off at checkout, no codes needed.", "Dodaj automatyczne rabaty, jeśli chcesz — okazję dla rodzeństwa lub wczesnej rezerwacji, która odejmuje się przy płatności bez żadnych kodów.", "Adaugă reduceri automate dacă vrei — o ofertă pentru frați sau una early-bird, care se scade la finalizare, fără coduri.", "چاہیں تو خودکار رعایتیں شامل کریں — بہن بھائیوں یا جلد بکنگ کی پیشکش جو ادائیگی پر خود لگ جاتی ہے، کسی کوڈ کی ضرورت نہیں۔", "ਜੇ ਚਾਹੋ ਤਾਂ ਆਪਣੇ ਆਪ ਲੱਗਣ ਵਾਲੀਆਂ ਛੋਟਾਂ ਜੋੜੋ — ਭੈਣ-ਭਰਾਵਾਂ ਜਾਂ ਜਲਦੀ ਬੁਕਿੰਗ ਦੀ ਪੇਸ਼ਕਸ਼ ਜੋ ਭੁਗਤਾਨ ਵੇਲੇ ਆਪਣੇ ਆਪ ਲੱਗ ਜਾਂਦੀ ਹੈ, ਕਿਸੇ ਕੋਡ ਦੀ ਲੋੜ ਨਹੀਂ।", "চাইলে স্বয়ংক্রিয় ছাড় যোগ করুন — ভাইবোন বা আগাম বুকিংয়ের অফার যা চেকআউটে নিজে থেকে কেটে যায়, কোনো কোডের দরকার নেই।", "أضف خصومات تلقائية إن أردت — عرضًا للإخوة أو للحجز المبكر يُخصم عند الدفع دون حاجة إلى رموز.", "Adicione descontos automáticos se quiser — uma oferta para irmãos ou de reserva antecipada que sai no pagamento, sem códigos.", "Añade descuentos automáticos si quieres: una oferta para hermanos o de reserva anticipada que se descuenta al pagar, sin códigos.", "Ajoutez des remises automatiques si vous le souhaitez — une offre fratrie ou réservation anticipée qui se déduit au paiement, sans code.", "Ychwanegwch ostyngiadau awtomatig os hoffech — cynnig brodyr a chwiorydd neu archebu cynnar sy’n dod i ffwrdd wrth dalu, dim codau angenrheidiol."],
  "lt_listings_s13": ["Add-ons are optional extras — tick the ones for this camp, like a late pick-up or a t-shirt, and parents add them when they book.", "Dodatki to opcjonalne extra — zaznacz te do tego obozu, jak późniejszy odbiór czy koszulka, a rodzice dodają je przy rezerwacji.", "Add-on-urile sunt extra opționale — bifează-le pe cele pentru această tabără, precum ridicarea târzie sau un tricou, iar părinții le adaugă la rezervare.", "ایڈ آنز اختیاری اضافے ہیں — اس کیمپ کے لیے چنیں، جیسے دیر سے لینا یا ٹی شرٹ، اور والدین بکنگ کے وقت انہیں شامل کرتے ہیں۔", "ਐਡ-ਆਨ ਵਿਕਲਪਿਕ ਵਾਧੂ ਹਨ — ਇਸ ਕੈਂਪ ਲਈ ਚੁਣੋ, ਜਿਵੇਂ ਦੇਰ ਨਾਲ ਲੈਣਾ ਜਾਂ ਟੀ-ਸ਼ਰਟ, ਅਤੇ ਮਾਪੇ ਬੁਕਿੰਗ ਵੇਲੇ ਉਨ੍ਹਾਂ ਨੂੰ ਜੋੜਦੇ ਹਨ।", "অ্যাড-অন হলো ঐচ্ছিক অতিরিক্ত — এই ক্যাম্পের জন্য বাছুন, যেমন দেরিতে নেওয়া বা টি-শার্ট, আর অভিভাবকরা বুকিংয়ের সময় সেগুলো যোগ করেন।", "الإضافات هي ملحقات اختيارية — حدّد ما يناسب هذا المخيم، مثل الاستلام المتأخر أو قميص، ويضيفها أولياء الأمور عند الحجز.", "Os extras são opcionais — assinale os deste campo, como uma recolha tardia ou uma t-shirt, e os pais juntam-nos ao reservar.", "Los complementos son extras opcionales: marca los de este campamento, como una recogida tardía o una camiseta, y los padres los añaden al reservar.", "Les options sont des extras facultatifs — cochez celles de ce camp, comme une récupération tardive ou un t-shirt, et les parents les ajoutent en réservant.", "Mae ychwanegion yn ychwanegion dewisol — ticiwch y rhai ar gyfer y gwersyll hwn, fel casglu hwyr neu grys-t, ac mae rhieni’n eu hychwanegu wrth archebu."],
  "lt_listings_s14": ["Add your team, then tap Assign next to whoever's onsite — their name and bio then show on the listing.", "Dodaj swój zespół, a potem dotknij Przypisz przy osobie, która będzie na miejscu — jej imię i krótki opis pojawią się w ofercie.", "Adaugă-ți echipa, apoi atinge Alocă lângă cine e la fața locului — numele și biografia apar apoi în ofertă.", "اپنی ٹیم شامل کریں، پھر جو موقع پر ہو اس کے ساتھ تفویض کریں پر ٹیپ کریں — پھر ان کا نام اور تعارف لسٹنگ پر دکھائی دیتا ہے۔", "ਆਪਣੀ ਟੀਮ ਜੋੜੋ, ਫਿਰ ਜੋ ਮੌਕੇ ਉੱਤੇ ਹੈ ਉਸ ਦੇ ਕੋਲ ਸੌਂਪੋ ਉੱਤੇ ਟੈਪ ਕਰੋ — ਫਿਰ ਉਨ੍ਹਾਂ ਦਾ ਨਾਮ ਅਤੇ ਜਾਣ-ਪਛਾਣ ਲਿਸਟਿੰਗ ਉੱਤੇ ਦਿਸਦੀ ਹੈ।", "আপনার টিম যোগ করুন, তারপর যিনি সাইটে থাকবেন তাঁর পাশে বরাদ্দ করুন ট্যাপ করুন — তাঁর নাম ও পরিচিতি তখন লিস্টিংয়ে দেখা যায়।", "أضف فريقك، ثم اضغط تعيين بجوار من سيكون في الموقع — فيظهر اسمه ونبذته في الإعلان.", "Adicione a sua equipa e depois toque em Atribuir junto de quem estará no local — o nome e a biografia aparecem então no anúncio.", "Añade a tu equipo y toca Asignar junto a quien estará en el lugar: su nombre y su biografía aparecen entonces en el anuncio.", "Ajoutez votre équipe, puis touchez Affecter à côté de la personne présente sur place — son nom et sa bio s’affichent alors dans l’annonce.", "Ychwanegwch eich tîm, yna tapiwch Neilltuo wrth ymyl pwy bynnag fydd ar y safle — mae eu henw a’u bywgraffiad wedyn yn dangos ar y rhestriad."],
  "lt_listings_s15": ["Preview is exactly what parents see — the full page, top to bottom. Give it a quick read to make sure it looks right.", "Podgląd to dokładnie to, co widzą rodzice — cała strona od góry do dołu. Przeczytaj ją szybko, by upewnić się, że wygląda dobrze.", "Previzualizarea este exact ce văd părinții — pagina întreagă, de sus până jos. Dă-i o citire rapidă ca să te asiguri că arată bine.", "پیش منظر بالکل وہی ہے جو والدین دیکھتے ہیں — پورا صفحہ اوپر سے نیچے تک۔ اسے ایک نظر پڑھ کر یقین کر لیں کہ یہ ٹھیک لگ رہا ہے۔", "ਝਲਕ ਬਿਲਕੁਲ ਉਹੀ ਹੈ ਜੋ ਮਾਪੇ ਦੇਖਦੇ ਹਨ — ਪੂਰਾ ਪੰਨਾ ਉੱਪਰ ਤੋਂ ਹੇਠਾਂ ਤੱਕ। ਇਸਨੂੰ ਇੱਕ ਵਾਰ ਪੜ੍ਹ ਲਓ ਤਾਂ ਜੋ ਪੱਕਾ ਹੋ ਜਾਵੇ ਕਿ ਇਹ ਠੀਕ ਲੱਗ ਰਿਹਾ ਹੈ।", "প্রিভিউ ঠিক তা-ই যা অভিভাবকরা দেখেন — পুরো পাতা, উপর থেকে নিচ। একবার চোখ বুলিয়ে নিন যাতে ঠিকঠাক দেখাচ্ছে কি না নিশ্চিত হন।", "المعاينة هي بالضبط ما يراه أولياء الأمور — الصفحة كاملة من الأعلى إلى الأسفل. اقرأها سريعًا للتأكد من أنها تبدو سليمة.", "A pré-visualização é exatamente o que os pais veem — a página completa, de cima a baixo. Leia-a rapidamente para ter a certeza de que está bem.", "La vista previa es exactamente lo que ven los padres: la página completa, de arriba abajo. Échale una lectura rápida para asegurarte de que queda bien.", "L’aperçu est exactement ce que voient les parents — la page entière, de haut en bas. Relisez-la rapidement pour vous assurer qu’elle est bien.", "Mae’r Rhagolwg yn union yr hyn y mae rhieni’n ei weld — y dudalen lawn, o’r top i’r gwaelod. Rhowch ddarlleniad cyflym iddi i wneud yn siŵr ei bod yn edrych yn iawn."],
  "lt_listings_s16": ["Last step — choose who can see it, your booking style and cancellation policy. When you're happy, press Publish, top right, and it's live for parents to book.", "Ostatni krok — wybierz, kto może ją widzieć, swój styl rezerwacji i politykę anulowania. Gdy jesteś zadowolony, naciśnij Opublikuj w prawym górnym rogu, a oferta jest aktywna dla rodziców.", "Ultimul pas — alege cine o poate vedea, stilul tău de rezervare și politica de anulare. Când ești mulțumit, apasă Publică, sus în dreapta, și oferta e live pentru părinți.", "آخری مرحلہ — چنیں کہ اسے کون دیکھ سکتا ہے، آپ کا بکنگ کا انداز اور منسوخی کی پالیسی۔ جب مطمئن ہوں تو اوپر دائیں جانب شائع کریں دبائیں، اور یہ والدین کے لیے بکنگ کو لائیو ہو جاتی ہے۔", "ਆਖ਼ਰੀ ਕਦਮ — ਚੁਣੋ ਕਿ ਇਸਨੂੰ ਕੌਣ ਦੇਖ ਸਕਦਾ ਹੈ, ਤੁਹਾਡਾ ਬੁਕਿੰਗ ਦਾ ਢੰਗ ਅਤੇ ਰੱਦ ਕਰਨ ਦੀ ਨੀਤੀ। ਜਦੋਂ ਤੁਸੀਂ ਸੰਤੁਸ਼ਟ ਹੋਵੋ ਤਾਂ ਉੱਪਰ ਸੱਜੇ ਪਾਸੇ ਪ੍ਰਕਾਸ਼ਿਤ ਕਰੋ ਦਬਾਓ, ਅਤੇ ਇਹ ਮਾਪਿਆਂ ਲਈ ਬੁਕਿੰਗ ਵਾਸਤੇ ਲਾਈਵ ਹੋ ਜਾਂਦੀ ਹੈ।", "শেষ ধাপ — কারা এটি দেখতে পারবেন, আপনার বুকিংয়ের ধরন ও বাতিলের নীতি বেছে নিন। সন্তুষ্ট হলে উপরে ডানে প্রকাশ করুন চাপুন, আর অভিভাবকদের বুকিংয়ের জন্য এটি লাইভ হয়ে যায়।", "الخطوة الأخيرة — اختر من يمكنه رؤيته، وأسلوب الحجز وسياسة الإلغاء. وعندما ترضى اضغط نشر في أعلى اليمين فيصبح متاحًا لأولياء الأمور للحجز.", "Último passo — escolha quem o pode ver, o seu estilo de reserva e a política de cancelamento. Quando estiver satisfeito, prima Publicar, no canto superior direito, e fica disponível para os pais reservarem.", "Último paso: elige quién puede verlo, tu estilo de reserva y la política de cancelación. Cuando estés conforme, pulsa Publicar, arriba a la derecha, y queda activo para que los padres reserven.", "Dernière étape — choisissez qui peut la voir, votre style de réservation et la politique d’annulation. Quand vous êtes satisfait, appuyez sur Publier, en haut à droite, et elle est en ligne pour que les parents réservent.", "Y cam olaf — dewiswch pwy all ei weld, eich arddull archebu a’ch polisi canslo. Pan fyddwch yn fodlon, pwyswch Cyhoeddi, ar y dde uchaf, ac mae’n fyw i rieni archebu."],
  "lt_blocks_title": ["Sessions & blocks", "Sesje i bloki", "Sesiuni și blocuri", "سیشنز اور بلاکس", "ਸੈਸ਼ਨ ਅਤੇ ਬਲਾਕ", "সেশন ও ব্লক", "الجلسات والكتل", "Sessões e blocos", "Sesiones y bloques", "Séances et blocs", "Sesiynau a blociau"],
  "lt_blocks_intro": ["This is where you build the patterns parents book — sessions grouped into a block, priced once and reused on any listing. Let me build one.", "Tu budujesz schematy, które rezerwują rodzice — sesje zgrupowane w blok, wycenione raz i używane w dowolnej ofercie. Zbudujmy jeden.", "Aici construiești modelele pe care le rezervă părinții — sesiuni grupate într-un bloc, cu preț stabilit o singură dată și refolosite în orice ofertă. Hai să construim unul.", "یہاں آپ وہ ڈھانچے بناتے ہیں جنہیں والدین بک کرتے ہیں — سیشنز جو ایک بلاک میں جمع ہوتے ہیں، ایک بار قیمت طے ہوتی ہے اور کسی بھی لسٹنگ پر دوبارہ استعمال ہوتے ہیں۔ آئیں ایک بناتے ہیں۔", "ਇੱਥੇ ਤੁਸੀਂ ਉਹ ਪੈਟਰਨ ਬਣਾਉਂਦੇ ਹੋ ਜੋ ਮਾਪੇ ਬੁੱਕ ਕਰਦੇ ਹਨ — ਸੈਸ਼ਨ ਜੋ ਇੱਕ ਬਲਾਕ ਵਿੱਚ ਗਰੁੱਪ ਹੁੰਦੇ ਹਨ, ਇੱਕ ਵਾਰ ਕੀਮਤ ਤੈਅ ਹੁੰਦੀ ਹੈ ਅਤੇ ਕਿਸੇ ਵੀ ਲਿਸਟਿੰਗ ਉੱਤੇ ਦੁਬਾਰਾ ਵਰਤੇ ਜਾਂਦੇ ਹਨ। ਆਓ ਇੱਕ ਬਣਾਈਏ।", "এখানে আপনি সেই কাঠামো বানান যা অভিভাবকরা বুক করেন — সেশনগুলো একটি ব্লকে গোছানো, একবার দাম ঠিক করা এবং যেকোনো লিস্টিংয়ে পুনরায় ব্যবহারযোগ্য। আসুন একটি বানাই।", "هنا تبني الأنماط التي يحجزها أولياء الأمور — جلسات مجمّعة في كتلة، تُسعَّر مرة واحدة وتُعاد استخدامها في أي إعلان. دعنا نبني واحدة.", "É aqui que cria os padrões que os pais reservam — sessões agrupadas num bloco, com preço definido uma vez e reutilizadas em qualquer anúncio. Vamos criar um.", "Aquí creas los patrones que reservan los padres: sesiones agrupadas en un bloque, con precio fijado una vez y reutilizadas en cualquier anuncio. Vamos a crear uno.", "Ici, vous construisez les modèles que réservent les parents — des séances regroupées en un bloc, tarifées une fois et réutilisées sur n’importe quelle annonce. Construisons-en un.", "Yma rydych yn adeiladu’r patrymau y mae rhieni’n eu harchebu — sesiynau wedi’u grwpio’n floc, wedi’u prisio unwaith a’u hailddefnyddio ar unrhyw restriad. Gadewch i ni adeiladu un."],
  "lt_blocks_done": ["Build a block once here, price it, and drop it onto any camp, club or class.", "Zbuduj blok tutaj raz, wyceń go i dodaj do dowolnego obozu, zajęć czy kursu.", "Construiește un bloc o singură dată aici, stabilește-i prețul și pune-l în orice tabără, club sau curs.", "یہاں ایک بار بلاک بنائیں، اس کی قیمت طے کریں، اور اسے کسی بھی کیمپ، کلب یا کلاس میں لگا دیں۔", "ਇੱਥੇ ਇੱਕ ਵਾਰ ਬਲਾਕ ਬਣਾਓ, ਉਸ ਦੀ ਕੀਮਤ ਤੈਅ ਕਰੋ, ਅਤੇ ਉਸਨੂੰ ਕਿਸੇ ਵੀ ਕੈਂਪ, ਕਲੱਬ ਜਾਂ ਕਲਾਸ ਉੱਤੇ ਲਗਾ ਦਿਓ।", "এখানে একবার ব্লক বানান, দাম ঠিক করুন, আর যেকোনো ক্যাম্প, ক্লাব বা ক্লাসে বসিয়ে দিন।", "ابنِ كتلة مرة واحدة هنا، وسعّرها، ثم ضعها في أي مخيم أو نادٍ أو حصة.", "Crie um bloco aqui uma só vez, defina o preço e aplique-o a qualquer campo, clube ou aula.", "Crea un bloque una vez aquí, ponle precio y colócalo en cualquier campamento, club o clase.", "Construisez un bloc une seule fois ici, tarifez-le et déposez-le sur n’importe quel camp, club ou cours.", "Adeiladwch floc unwaith yma, prisiwch ef, a’i ollwng ar unrhyw wersyll, clwb neu ddosbarth."],
  "lt_blocks_s0": ["First, your periods — the time windows in a day. Click Add a period, give it a name, and set the start and finish times.", "Najpierw okresy — przedziały czasu w ciągu dnia. Kliknij Dodaj okres, nadaj mu nazwę i ustaw godzinę rozpoczęcia i zakończenia.", "Mai întâi perioadele — intervalele de timp dintr-o zi. Fă clic pe Adaugă o perioadă, dă-i un nume și setează ora de început și de sfârșit.", "پہلے آپ کے پیریڈز — دن کے وقت کے دورانیے۔ پیریڈ شامل کریں پر کلک کریں، نام دیں، اور آغاز اور اختتام کا وقت طے کریں۔", "ਪਹਿਲਾਂ ਤੁਹਾਡੇ ਪੀਰੀਅਡ — ਦਿਨ ਦੇ ਸਮੇਂ ਦੇ ਦਾਇਰੇ। ਪੀਰੀਅਡ ਜੋੜੋ ਉੱਤੇ ਕਲਿੱਕ ਕਰੋ, ਨਾਮ ਦਿਓ, ਅਤੇ ਸ਼ੁਰੂ ਤੇ ਅੰਤ ਦਾ ਸਮਾਂ ਤੈਅ ਕਰੋ।", "প্রথমে আপনার পিরিয়ড — দিনের সময়-সীমা। পিরিয়ড যোগ করুন ক্লিক করুন, একটি নাম দিন, আর শুরু ও শেষের সময় ঠিক করুন।", "أولًا الفترات — النوافذ الزمنية في اليوم. انقر إضافة فترة، وأعطها اسمًا، وحدّد وقت البداية والنهاية.", "Primeiro os períodos — as janelas de tempo de um dia. Clique em Adicionar período, dê-lhe um nome e defina as horas de início e fim.", "Primero tus periodos: las franjas horarias de un día. Haz clic en Añadir un periodo, dale un nombre y fija la hora de inicio y fin.", "D’abord vos périodes — les plages horaires d’une journée. Cliquez sur Ajouter une période, donnez-lui un nom et réglez les heures de début et de fin.", "Yn gyntaf eich cyfnodau — y ffenestri amser mewn diwrnod. Cliciwch Ychwanegu cyfnod, rhowch enw iddo, a gosodwch yr amseroedd dechrau a gorffen."],
  "lt_blocks_s1": ["Then your passes — how long a parent books. Click Add a pass, name it, and set the number of days.", "Potem karnety — na jak długo rodzic rezerwuje. Kliknij Dodaj karnet, nazwij go i ustaw liczbę dni.", "Apoi abonamentele — pentru cât timp rezervă un părinte. Fă clic pe Adaugă un abonament, dă-i un nume și setează numărul de zile.", "پھر آپ کے پاسز — والدین کتنی دیر کے لیے بک کرتے ہیں۔ پاس شامل کریں پر کلک کریں، نام دیں، اور دنوں کی تعداد طے کریں۔", "ਫਿਰ ਤੁਹਾਡੇ ਪਾਸ — ਮਾਪੇ ਕਿੰਨੇ ਸਮੇਂ ਲਈ ਬੁੱਕ ਕਰਦੇ ਹਨ। ਪਾਸ ਜੋੜੋ ਉੱਤੇ ਕਲਿੱਕ ਕਰੋ, ਨਾਮ ਦਿਓ, ਅਤੇ ਦਿਨਾਂ ਦੀ ਗਿਣਤੀ ਤੈਅ ਕਰੋ।", "তারপর আপনার পাস — অভিভাবক কতদিনের জন্য বুক করেন। পাস যোগ করুন ক্লিক করুন, নাম দিন, আর দিনের সংখ্যা ঠিক করুন।", "ثم التصاريح — مدة حجز ولي الأمر. انقر إضافة تصريح، وسمِّه، وحدّد عدد الأيام.", "Depois os passes — por quanto tempo um pai reserva. Clique em Adicionar passe, dê-lhe um nome e defina o número de dias.", "Después tus pases: cuánto tiempo reserva un padre. Haz clic en Añadir un pase, ponle nombre y fija el número de días.", "Ensuite vos forfaits — la durée pour laquelle un parent réserve. Cliquez sur Ajouter un forfait, nommez-le et réglez le nombre de jours.", "Yna eich tocynnau — am ba hyd y mae rhiant yn archebu. Cliciwch Ychwanegu tocyn, enwch ef, a gosodwch nifer y diwrnodau."],
  "lt_blocks_s2": ["Now build the block — click Add to block on the periods and passes you want, and they drop in here on the right.", "Teraz zbuduj blok — kliknij Dodaj do bloku przy okresach i karnetach, które chcesz, a wskoczą tutaj po prawej.", "Acum construiește blocul — fă clic pe Adaugă la bloc pentru perioadele și abonamentele dorite și apar aici, în dreapta.", "اب بلاک بنائیں — جن پیریڈز اور پاسز کو چاہیں ان پر بلاک میں شامل کریں پر کلک کریں، اور وہ یہاں دائیں طرف آ جاتے ہیں۔", "ਹੁਣ ਬਲਾਕ ਬਣਾਓ — ਜਿਨ੍ਹਾਂ ਪੀਰੀਅਡਾਂ ਅਤੇ ਪਾਸਾਂ ਨੂੰ ਚਾਹੁੰਦੇ ਹੋ ਉਨ੍ਹਾਂ ਉੱਤੇ ਬਲਾਕ ਵਿੱਚ ਜੋੜੋ ਉੱਤੇ ਕਲਿੱਕ ਕਰੋ, ਅਤੇ ਉਹ ਇੱਥੇ ਸੱਜੇ ਪਾਸੇ ਆ ਜਾਂਦੇ ਹਨ।", "এবার ব্লক বানান — যে পিরিয়ড ও পাস চান সেগুলোতে ব্লকে যোগ করুন ক্লিক করুন, আর সেগুলো এখানে ডানদিকে চলে আসবে।", "الآن ابنِ الكتلة — انقر إضافة إلى الكتلة على الفترات والتصاريح التي تريدها، فتنزل هنا في الجانب الأيمن.", "Agora crie o bloco — clique em Adicionar ao bloco nos períodos e passes que quer e eles entram aqui, à direita.", "Ahora crea el bloque: haz clic en Añadir al bloque en los periodos y pases que quieras y se colocan aquí, a la derecha.", "Construisez maintenant le bloc — cliquez sur Ajouter au bloc sur les périodes et forfaits voulus, et ils se placent ici, à droite.", "Nawr adeiladwch y bloc — cliciwch Ychwanegu at y bloc ar y cyfnodau a’r tocynnau rydych eu heisiau, ac maent yn disgyn i mewn yma ar y dde."],
  "lt_blocks_s3": ["Name the block, then Move to Block Library.", "Nazwij blok, a potem Przenieś do Biblioteki bloków.", "Dă-i blocului un nume, apoi Mută în Biblioteca de blocuri.", "بلاک کو نام دیں، پھر بلاک لائبریری میں منتقل کریں۔", "ਬਲਾਕ ਨੂੰ ਨਾਮ ਦਿਓ, ਫਿਰ ਬਲਾਕ ਲਾਇਬ੍ਰੇਰੀ ਵਿੱਚ ਭੇਜੋ।", "ব্লকের নাম দিন, তারপর ব্লক লাইব্রেরিতে সরান।", "سمِّ الكتلة ثم انقلها إلى مكتبة الكتل.", "Dê um nome ao bloco e depois Mover para a Biblioteca de blocos.", "Ponle nombre al bloque y luego Mover a la Biblioteca de bloques.", "Nommez le bloc, puis Déplacer vers la Bibliothèque de blocs.", "Enwch y bloc, yna Symud i’r Llyfrgell Blociau."],
  "lt_blocks_s4": ["Every saved block gets a pricing calculator. Set the full price for the longest pass — I'll make it a hundred and ninety-five pounds — and watch each shorter pass price itself automatically.", "Każdy zapisany blok ma kalkulator cen. Ustaw pełną cenę najdłuższego karnetu — zrobię sto dziewięćdziesiąt pięć funtów — i patrz, jak każdy krótszy karnet sam się wycenia.", "Fiecare bloc salvat primește un calculator de prețuri. Setează prețul întreg pentru cel mai lung abonament — îl pun la o sută nouăzeci și cinci de lire — și urmărește cum fiecare abonament mai scurt își calculează singur prețul.", "ہر محفوظ شدہ بلاک کو قیمت کا کیلکولیٹر ملتا ہے۔ سب سے لمبے پاس کی پوری قیمت طے کریں — میں اسے ایک سو پچانوے پاؤنڈ رکھتا ہوں — اور دیکھیں ہر چھوٹے پاس کی قیمت خود بخود بن جاتی ہے۔", "ਹਰ ਸੰਭਾਲੇ ਬਲਾਕ ਨੂੰ ਕੀਮਤ ਕੈਲਕੁਲੇਟਰ ਮਿਲਦਾ ਹੈ। ਸਭ ਤੋਂ ਲੰਮੇ ਪਾਸ ਦੀ ਪੂਰੀ ਕੀਮਤ ਤੈਅ ਕਰੋ — ਮੈਂ ਇਸਨੂੰ ਇੱਕ ਸੌ ਪੰਝਾਨਵੇਂ ਪੌਂਡ ਕਰਦਾ ਹਾਂ — ਅਤੇ ਦੇਖੋ ਹਰ ਛੋਟੇ ਪਾਸ ਦੀ ਕੀਮਤ ਆਪਣੇ ਆਪ ਬਣ ਜਾਂਦੀ ਹੈ।", "প্রতিটি সংরক্ষিত ব্লক একটি দাম ক্যালকুলেটর পায়। দীর্ঘতম পাসের পূর্ণ দাম ঠিক করুন — আমি একশো পঁচানব্বই পাউন্ড দিচ্ছি — আর দেখুন প্রতিটি ছোট পাসের দাম নিজে থেকে বসে যায়।", "تحصل كل كتلة محفوظة على حاسبة أسعار. حدّد السعر الكامل لأطول تصريح — سأجعله مئة وخمسة وتسعين جنيهًا — وشاهد كل تصريح أقصر يُسعَّر نفسه تلقائيًا.", "Cada bloco guardado ganha uma calculadora de preços. Defina o preço total do passe mais longo — vou pôr cento e noventa e cinco libras — e veja cada passe mais curto a calcular o seu preço automaticamente.", "Cada bloque guardado recibe una calculadora de precios. Fija el precio completo del pase más largo (yo pondré ciento noventa y cinco libras) y mira cómo cada pase más corto se calcula solo.", "Chaque bloc enregistré dispose d’une calculatrice de prix. Fixez le prix plein du forfait le plus long — je mets cent quatre-vingt-quinze livres — et regardez chaque forfait plus court se chiffrer automatiquement.", "Mae pob bloc a gadwyd yn cael cyfrifiannell prisio. Gosodwch y pris llawn ar gyfer y tocyn hiraf — gwnaf ef yn gant naw deg pump o bunnoedd — a gwyliwch bob tocyn byrrach yn prisio ei hun yn awtomatig."],
  "lt_blocks_s5": ["That's a block built and priced — in your library now, ready to drop onto any listing. Build it once, reuse it everywhere.", "Blok zbudowany i wyceniony — jest teraz w Twojej bibliotece, gotowy do użycia w dowolnej ofercie. Zbuduj go raz, używaj wszędzie.", "Blocul e construit și cu prețul stabilit — acum e în biblioteca ta, gata de pus în orice ofertă. Construiește-l o dată, refolosește-l peste tot.", "بلاک بن گیا اور اس کی قیمت طے ہو گئی — اب یہ آپ کی لائبریری میں ہے، کسی بھی لسٹنگ پر لگانے کے لیے تیار۔ ایک بار بنائیں، ہر جگہ دوبارہ استعمال کریں۔", "ਬਲਾਕ ਬਣ ਗਿਆ ਅਤੇ ਕੀਮਤ ਤੈਅ ਹੋ ਗਈ — ਹੁਣ ਇਹ ਤੁਹਾਡੀ ਲਾਇਬ੍ਰੇਰੀ ਵਿੱਚ ਹੈ, ਕਿਸੇ ਵੀ ਲਿਸਟਿੰਗ ਉੱਤੇ ਲਗਾਉਣ ਲਈ ਤਿਆਰ। ਇੱਕ ਵਾਰ ਬਣਾਓ, ਹਰ ਥਾਂ ਦੁਬਾਰਾ ਵਰਤੋ।", "ব্লক বানানো ও দাম ঠিক করা হয়ে গেছে — এখন এটি আপনার লাইব্রেরিতে, যেকোনো লিস্টিংয়ে বসানোর জন্য প্রস্তুত। একবার বানান, সবখানে পুনরায় ব্যবহার করুন।", "تم بناء الكتلة وتسعيرها — وهي الآن في مكتبتك جاهزة لوضعها في أي إعلان. ابنها مرة واحدة وأعد استخدامها في كل مكان.", "O bloco está criado e com preço — já está na sua biblioteca, pronto a aplicar a qualquer anúncio. Crie-o uma vez, reutilize-o em todo o lado.", "Bloque creado y con precio: ya está en tu biblioteca, listo para colocarlo en cualquier anuncio. Créalo una vez y reutilízalo en todas partes.", "Le bloc est construit et tarifé — il est maintenant dans votre bibliothèque, prêt à être déposé sur n’importe quelle annonce. Construisez-le une fois, réutilisez-le partout.", "Mae’r bloc wedi’i adeiladu a’i brisio — mae yn eich llyfrgell nawr, yn barod i’w ollwng ar unrhyw restriad. Adeiladwch ef unwaith, ailddefnyddiwch ef ym mhobman."],
  "lt_schedule_title": ["Schedule & rota", "Grafik i rota", "Program și tură", "شیڈول اور روٹا", "ਸ਼ਡਿਊਲ ਅਤੇ ਰੋਟਾ", "সময়সূচি ও রোটা", "الجدول والمناوبات", "Escala e horário", "Horario y turnos", "Planning et rotation", "Amserlen a rota"],
  "lt_schedule_intro": ["This is your rota. Let me build a shift, staff the week, sort everyone's availability and send it out — start to finish.", "To Twój grafik dyżurów. Zbuduję zmianę, obsadzę tydzień, uporządkuję dostępność wszystkich i wyślę całość — od początku do końca.", "Aceasta este tura ta. Hai să construiesc o tură, să încadrez săptămâna cu personal, să pun în ordine disponibilitatea tuturor și s-o trimit — de la cap la coadă.", "یہ آپ کا روٹا ہے۔ میں ایک شفٹ بناتا ہوں، ہفتے کا عملہ لگاتا ہوں، سب کی دستیابی ٹھیک کرتا ہوں اور اسے بھیج دیتا ہوں — شروع سے آخر تک۔", "ਇਹ ਤੁਹਾਡਾ ਰੋਟਾ ਹੈ। ਮੈਂ ਇੱਕ ਸ਼ਿਫ਼ਟ ਬਣਾਉਂਦਾ ਹਾਂ, ਹਫ਼ਤੇ ਦਾ ਸਟਾਫ਼ ਲਗਾਉਂਦਾ ਹਾਂ, ਸਭ ਦੀ ਉਪਲਬਧਤਾ ਠੀਕ ਕਰਦਾ ਹਾਂ ਅਤੇ ਇਸਨੂੰ ਭੇਜ ਦਿੰਦਾ ਹਾਂ — ਸ਼ੁਰੂ ਤੋਂ ਅੰਤ ਤੱਕ।", "এটি আপনার রোটা। আমি একটি শিফট বানাই, সপ্তাহের কর্মী ঠিক করি, সবার উপস্থিতির সময় গুছিয়ে নিই এবং পাঠিয়ে দিই — শুরু থেকে শেষ পর্যন্ত।", "هذا هو جدول مناوباتك. دعني أبني وردية، وأوزّع موظفي الأسبوع، وأرتّب توفر الجميع، ثم أرسله — من البداية إلى النهاية.", "Esta é a sua escala. Vou criar um turno, escalar a semana, organizar a disponibilidade de todos e enviá-la — do princípio ao fim.", "Este es tu cuadrante. Voy a crear un turno, asignar personal a la semana, ordenar la disponibilidad de todos y enviarlo: de principio a fin.", "Voici votre planning. Je vais créer un créneau, pourvoir la semaine, régler les disponibilités de chacun et l’envoyer — du début à la fin.", "Dyma’ch rota. Gadewch i mi adeiladu shifft, staffio’r wythnos, trefnu argaeledd pawb a’i hanfon allan — o’r dechrau i’r diwedd."],
  "lt_schedule_done": ["Shift added, week auto-staffed, availability chased and filled in, and the rota published to your team. That's the whole loop.", "Zmiana dodana, tydzień automatycznie obsadzony, dostępność przypomniana i uzupełniona, a grafik opublikowany dla zespołu. To cała pętla.", "Tură adăugată, săptămână încadrată automat, disponibilități urmărite și completate, iar programul publicat echipei tale. Asta e tot circuitul.", "شفٹ شامل ہو گئی، ہفتے کا عملہ خود لگ گیا، دستیابی کی یاد دہانی اور اندراج ہو گیا، اور روٹا آپ کی ٹیم کے لیے شائع ہو گیا۔ یہ پورا چکر ہے۔", "ਸ਼ਿਫ਼ਟ ਜੁੜ ਗਈ, ਹਫ਼ਤੇ ਦਾ ਸਟਾਫ਼ ਆਪਣੇ ਆਪ ਲੱਗ ਗਿਆ, ਉਪਲਬਧਤਾ ਦੀ ਯਾਦ ਕਰਾਈ ਅਤੇ ਭਰੀ ਗਈ, ਅਤੇ ਰੋਟਾ ਤੁਹਾਡੀ ਟੀਮ ਲਈ ਪ੍ਰਕਾਸ਼ਿਤ ਹੋ ਗਿਆ। ਇਹ ਪੂਰਾ ਚੱਕਰ ਹੈ।", "শিফট যোগ হলো, সপ্তাহে স্বয়ংক্রিয়ভাবে কর্মী বসল, উপস্থিতির সময় চাওয়া ও পূরণ করা হলো, আর রোটা আপনার টিমের জন্য প্রকাশিত হলো। এই হলো পুরো চক্র।", "أُضيفت الوردية، وجرى تعيين موظفي الأسبوع تلقائيًا، وتمت متابعة التوفر وتعبئته، ونُشر الجدول لفريقك. هذه هي الحلقة كاملة.", "Turno adicionado, semana escalada automaticamente, disponibilidade pedida e preenchida e escala publicada para a equipa. Este é o ciclo completo.", "Turno añadido, semana asignada automáticamente, disponibilidad reclamada y completada y cuadrante publicado para tu equipo. Ese es todo el ciclo.", "Créneau ajouté, semaine pourvue automatiquement, disponibilités relancées et renseignées, et planning publié pour votre équipe. Voilà toute la boucle.", "Shifft wedi’i hychwanegu, wythnos wedi’i staffio’n awtomatig, argaeledd wedi’i erlid a’i lenwi, a’r rota wedi’i chyhoeddi i’ch tîm. Dyna’r cylch cyfan."],
  "lt_schedule_s0": ["Up top: the week's wage bill — at the hourly rate and including on-cost.", "Na górze: tygodniowy koszt wynagrodzeń — według stawki godzinowej, wraz z kosztami dodatkowymi.", "Sus: factura salarială a săptămânii — la tariful orar și incluzând costurile suplimentare.", "اوپر: ہفتے کا اجرتی بل — فی گھنٹہ شرح پر اور اضافی لاگت سمیت۔", "ਉੱਪਰ: ਹਫ਼ਤੇ ਦਾ ਤਨਖ਼ਾਹ ਬਿੱਲ — ਪ੍ਰਤੀ ਘੰਟਾ ਦਰ ਉੱਤੇ ਅਤੇ ਵਾਧੂ ਲਾਗਤ ਸਮੇਤ।", "উপরে: সপ্তাহের মজুরির বিল — ঘণ্টাপ্রতি হারে এবং অতিরিক্ত খরচসহ।", "في الأعلى: فاتورة أجور الأسبوع — بسعر الساعة وشاملة التكاليف الإضافية.", "No topo: o total de salários da semana — à taxa horária e incluindo encargos.", "Arriba: el coste salarial de la semana, a tarifa por hora e incluyendo los costes asociados.", "En haut : la masse salariale de la semaine — au taux horaire et charges comprises.", "Ar y brig: bil cyflogau’r wythnos — ar y gyfradd fesul awr ac yn cynnwys costau ychwanegol."],
  "lt_schedule_s1": ["The rota's grouped by listing, with a row per role. Blue means assigned, red still needs someone.", "Grafik jest pogrupowany według ofert, z wierszem dla każdej roli. Niebieski oznacza przypisane, czerwony — że wciąż potrzebna jest osoba.", "Programul e grupat pe oferte, cu un rând pentru fiecare rol. Albastru înseamnă alocat, roșu înseamnă că mai are nevoie de cineva.", "روٹا لسٹنگ کے حساب سے گروپ ہے، ہر کردار کے لیے ایک قطار۔ نیلا مطلب تفویض شدہ، سرخ مطلب ابھی کسی کی ضرورت ہے۔", "ਰੋਟਾ ਲਿਸਟਿੰਗ ਅਨੁਸਾਰ ਗਰੁੱਪ ਹੈ, ਹਰ ਭੂਮਿਕਾ ਲਈ ਇੱਕ ਕਤਾਰ। ਨੀਲਾ ਮਤਲਬ ਸੌਂਪਿਆ ਗਿਆ, ਲਾਲ ਮਤਲਬ ਅਜੇ ਕਿਸੇ ਦੀ ਲੋੜ ਹੈ।", "রোটা লিস্টিং অনুযায়ী গোছানো, প্রতিটি ভূমিকার জন্য একটি সারি। নীল মানে বরাদ্দ হয়েছে, লাল মানে এখনও কাউকে দরকার।", "الجدول مجمّع حسب الإعلان، مع صف لكل دور. الأزرق يعني معيَّن، والأحمر يعني أنه لا يزال بحاجة إلى شخص.", "A escala está agrupada por anúncio, com uma linha por função. Azul significa atribuído, vermelho significa que ainda precisa de alguém.", "El cuadrante está agrupado por anuncio, con una fila por rol. Azul significa asignado; rojo, que aún falta alguien.", "Le planning est regroupé par annonce, avec une ligne par rôle. Bleu signifie affecté, rouge signifie qu’il manque encore quelqu’un.", "Mae’r rota wedi’i grwpio yn ôl rhestriad, gyda rhes ar gyfer pob rôl. Mae glas yn golygu wedi’i neilltuo, mae coch yn golygu bod angen rhywun o hyd."],
  "lt_schedule_s2": ["Let's add a shift — I'll tap the plus on a First Aider day, and the editor opens.", "Dodajmy zmianę — dotknę plusa przy dniu Pierwszej pomocy i otworzy się edytor.", "Să adăugăm o tură — ating plusul de la o zi de Prim-ajutor și se deschide editorul.", "آئیں ایک شفٹ شامل کریں — میں فرسٹ ایڈر کے دن پر پلس ٹیپ کرتا ہوں اور ایڈیٹر کھل جاتا ہے۔", "ਆਓ ਇੱਕ ਸ਼ਿਫ਼ਟ ਜੋੜੀਏ — ਮੈਂ ਫਸਟ ਏਡਰ ਵਾਲੇ ਦਿਨ ਦੇ ਪਲੱਸ ਉੱਤੇ ਟੈਪ ਕਰਦਾ ਹਾਂ, ਅਤੇ ਐਡੀਟਰ ਖੁੱਲ੍ਹ ਜਾਂਦਾ ਹੈ।", "চলুন একটি শিফট যোগ করি — আমি ফার্স্ট এইডার দিনে প্লাসে ট্যাপ করি, আর এডিটর খুলে যায়।", "لنضف وردية — سأضغط على علامة الزائد في يوم المسعف الأول ويُفتح المحرر.", "Vamos adicionar um turno — toco no plus de um dia de Socorrista e o editor abre-se.", "Vamos a añadir un turno: toco el más de un día de Socorrista y se abre el editor.", "Ajoutons un créneau — je touche le plus d’un jour Secouriste et l’éditeur s’ouvre.", "Gadewch i ni ychwanegu shifft — tapiaf y plws ar ddiwrnod Cymorth Cyntaf ac mae’r golygydd yn agor."],
  "lt_schedule_s3": ["Every shift needs someone on it. I'll open Assign staff.", "Każda zmiana potrzebuje kogoś. Otwieram Przypisz personel.", "Fiecare tură are nevoie de cineva. Deschid Alocă personal.", "ہر شفٹ پر کسی کا ہونا ضروری ہے۔ میں عملہ تفویض کریں کھولتا ہوں۔", "ਹਰ ਸ਼ਿਫ਼ਟ ਉੱਤੇ ਕਿਸੇ ਦਾ ਹੋਣਾ ਜ਼ਰੂਰੀ ਹੈ। ਮੈਂ ਸਟਾਫ਼ ਸੌਂਪੋ ਖੋਲ੍ਹਦਾ ਹਾਂ।", "প্রতিটি শিফটে কাউকে থাকতে হয়। আমি কর্মী বরাদ্দ করুন খুলছি।", "كل وردية تحتاج إلى شخص. سأفتح تعيين الموظفين.", "Cada turno precisa de alguém. Abro Atribuir pessoal.", "Cada turno necesita a alguien. Abro Asignar personal.", "Chaque créneau a besoin de quelqu’un. J’ouvre Affecter du personnel.", "Mae angen rhywun ar bob shifft. Agoraf Neilltuo staff."],
  "lt_schedule_s4": ["Auto-fill instantly picks whoever's free and not already booked that day — no hunting.", "Autouzupełnianie od razu wybiera osobę, która jest wolna i nie ma tego dnia innych zajęć — bez szukania.", "Completarea automată alege pe loc pe cine e liber și nu e deja rezervat în ziua aceea — fără căutări.", "آٹو فِل فوراً اسے چنتا ہے جو فارغ ہو اور اس دن پہلے سے مصروف نہ ہو — ڈھونڈنے کی ضرورت نہیں۔", "ਆਟੋ-ਫਿਲ ਤੁਰੰਤ ਉਸਨੂੰ ਚੁਣਦਾ ਹੈ ਜੋ ਵਿਹਲਾ ਹੈ ਅਤੇ ਉਸ ਦਿਨ ਪਹਿਲਾਂ ਤੋਂ ਲੱਗਿਆ ਨਹੀਂ ਹੈ — ਲੱਭਣ ਦੀ ਲੋੜ ਨਹੀਂ।", "অটো-ফিল সঙ্গে সঙ্গে সেই ব্যক্তিকে বাছে যিনি ফ্রি এবং সেদিন আগে থেকে বুক নন — খোঁজাখুঁজির দরকার নেই।", "يختار الملء التلقائي فورًا من هو متاح وغير محجوز في ذلك اليوم — دون بحث.", "O preenchimento automático escolhe logo quem está livre e ainda não está escalado nesse dia — sem andar à procura.", "El autorrelleno elige al instante a quien esté libre y no tenga ya turno ese día, sin buscar.", "Le remplissage automatique choisit aussitôt une personne libre et pas déjà réservée ce jour-là — inutile de chercher.", "Mae Llenwi awtomatig yn dewis pwy bynnag sy’n rhydd ac heb ei archebu eisoes y diwrnod hwnnw ar unwaith — dim chwilio."],
  "lt_schedule_s5": ["Add a note the staff member will see on their shift, then save it.", "Dodaj notatkę, którą pracownik zobaczy przy swojej zmianie, i zapisz.", "Adaugă o notă pe care membrul personalului o va vedea la tura lui, apoi salvează.", "ایک نوٹ شامل کریں جو عملے کا رکن اپنی شفٹ پر دیکھے گا، پھر محفوظ کریں۔", "ਇੱਕ ਨੋਟ ਜੋੜੋ ਜੋ ਸਟਾਫ਼ ਮੈਂਬਰ ਆਪਣੀ ਸ਼ਿਫ਼ਟ ਉੱਤੇ ਦੇਖੇਗਾ, ਫਿਰ ਸੰਭਾਲੋ।", "একটি নোট যোগ করুন যা কর্মী তাঁর শিফটে দেখতে পাবেন, তারপর সংরক্ষণ করুন।", "أضف ملاحظة سيراها الموظف على ورديته، ثم احفظ.", "Adicione uma nota que o membro da equipa verá no seu turno e guarde.", "Añade una nota que la persona verá en su turno y guarda.", "Ajoutez une note que la personne verra sur son créneau, puis enregistrez.", "Ychwanegwch nodyn y bydd yr aelod staff yn ei weld ar ei shifft, yna cadwch."],
  "lt_schedule_s6": ["Don't fill them one by one — Auto-schedule staffs every open shift for the week from your confirmed, available team in one go.", "Nie wypełniaj ich po kolei — Autoplanowanie obsadza każdą otwartą zmianę tygodnia z Twojego potwierdzonego, dostępnego zespołu za jednym razem.", "Nu le completa una câte una — Programarea automată încadrează cu personal fiecare tură deschisă a săptămânii din echipa ta confirmată și disponibilă, dintr-odată.", "انہیں ایک ایک کر کے مت بھریں — آٹو شیڈول آپ کی تصدیق شدہ، دستیاب ٹیم سے ہفتے کی ہر کھلی شفٹ ایک ہی بار میں پُر کر دیتا ہے۔", "ਉਨ੍ਹਾਂ ਨੂੰ ਇੱਕ-ਇੱਕ ਕਰਕੇ ਨਾ ਭਰੋ — ਆਟੋ-ਸ਼ਡਿਊਲ ਤੁਹਾਡੀ ਪੁਸ਼ਟੀ ਕੀਤੀ, ਉਪਲਬਧ ਟੀਮ ਵਿੱਚੋਂ ਹਫ਼ਤੇ ਦੀ ਹਰ ਖੁੱਲ੍ਹੀ ਸ਼ਿਫ਼ਟ ਇੱਕੋ ਵਾਰ ਵਿੱਚ ਭਰ ਦਿੰਦਾ ਹੈ।", "এক একটি করে ভরবেন না — অটো-শিডিউল আপনার নিশ্চিত ও উপলব্ধ টিম থেকে সপ্তাহের প্রতিটি খালি শিফট এক সঙ্গে ভরে দেয়।", "لا تملأها واحدة واحدة — الجدولة التلقائية تعيّن موظفين لكل وردية مفتوحة في الأسبوع من فريقك المؤكد والمتاح دفعة واحدة.", "Não as preencha uma a uma — a Programação automática escala todos os turnos abertos da semana com a sua equipa confirmada e disponível, de uma só vez.", "No las rellenes una a una: la Programación automática asigna todos los turnos abiertos de la semana con tu equipo confirmado y disponible de una sola vez.", "Ne les remplissez pas une par une — la Planification automatique pourvoit tous les créneaux ouverts de la semaine avec votre équipe confirmée et disponible, d’un seul coup.", "Peidiwch â’u llenwi fesul un — mae Amserlennu awtomatig yn staffio pob shifft agored am yr wythnos o’ch tîm cadarnhaol a pharod ar un tro."],
  "lt_schedule_s7": ["Not sure who's free? Ask them. This sends everyone who hasn't submitted a request to fill in their availability — for this week or all weeks.", "Nie wiesz, kto jest wolny? Zapytaj. To wysyła do każdego, kto nie przesłał prośby, polecenie uzupełnienia dostępności — na ten tydzień lub na wszystkie.", "Nu știi cine e liber? Întreabă-i. Astfel trimiți tuturor celor care nu au trimis o cerere rugămintea de a-și completa disponibilitatea — pentru această săptămână sau pentru toate.", "معلوم نہیں کون فارغ ہے؟ ان سے پوچھیں۔ یہ ہر اس شخص کو جس نے درخواست جمع نہیں کرائی اپنی دستیابی بھرنے کا کہتا ہے — اس ہفتے کے لیے یا تمام ہفتوں کے لیے۔", "ਪਤਾ ਨਹੀਂ ਕੌਣ ਵਿਹਲਾ ਹੈ? ਉਨ੍ਹਾਂ ਨੂੰ ਪੁੱਛੋ। ਇਹ ਹਰ ਉਸ ਨੂੰ ਜਿਸਨੇ ਬੇਨਤੀ ਨਹੀਂ ਭੇਜੀ ਆਪਣੀ ਉਪਲਬਧਤਾ ਭਰਨ ਲਈ ਕਹਿੰਦਾ ਹੈ — ਇਸ ਹਫ਼ਤੇ ਲਈ ਜਾਂ ਸਾਰੇ ਹਫ਼ਤਿਆਂ ਲਈ।", "কে ফ্রি নিশ্চিত নন? তাঁদের জিজ্ঞেস করুন। যাঁরা অনুরোধ জমা দেননি সবাইকে এটি তাঁদের উপস্থিতির সময় পূরণ করতে বলে পাঠায় — এই সপ্তাহের জন্য বা সব সপ্তাহের জন্য।", "لست متأكدًا من هو المتاح؟ اسألهم. يرسل هذا إلى كل من لم يقدّم طلبًا ليملأ توفره — لهذا الأسبوع أو لكل الأسابيع.", "Não sabe quem está livre? Pergunte. Isto envia a todos os que não submeteram um pedido a indicação para preencherem a sua disponibilidade — para esta semana ou para todas.", "¿No sabes quién está libre? Pregúntales. Esto envía a todos los que no han enviado una solicitud el aviso de completar su disponibilidad, para esta semana o para todas.", "Vous ne savez pas qui est libre ? Demandez-leur. Cela envoie à tous ceux qui n’ont pas soumis de demande l’invitation à renseigner leurs disponibilités — pour cette semaine ou toutes les semaines.", "Ddim yn siŵr pwy sy’n rhydd? Gofynnwch iddynt. Mae hyn yn anfon at bawb sydd heb gyflwyno cais i lenwi eu hargaeledd — ar gyfer yr wythnos hon neu bob wythnos."],
  "lt_schedule_s8": ["You can also fill it in for someone — open their card and set the days they can work. I'll mark Jordan as weekdays.", "Możesz też uzupełnić dostępność za kogoś — otwórz jego kartę i ustaw dni, w które może pracować. Zaznaczę Jordana na dni robocze.", "Poți completa și tu pentru cineva — deschide-i cardul și setează zilele în care poate lucra. Îl marchez pe Jordan pentru zilele lucrătoare.", "آپ کسی کی جگہ بھی بھر سکتے ہیں — ان کا کارڈ کھولیں اور وہ دن طے کریں جب وہ کام کر سکتے ہیں۔ میں جورڈن کو ہفتے کے دنوں کے لیے نشان زد کرتا ہوں۔", "ਤੁਸੀਂ ਕਿਸੇ ਦੀ ਥਾਂ ਵੀ ਭਰ ਸਕਦੇ ਹੋ — ਉਨ੍ਹਾਂ ਦਾ ਕਾਰਡ ਖੋਲ੍ਹੋ ਅਤੇ ਉਹ ਦਿਨ ਤੈਅ ਕਰੋ ਜਦੋਂ ਉਹ ਕੰਮ ਕਰ ਸਕਦੇ ਹਨ। ਮੈਂ ਜੌਰਡਨ ਨੂੰ ਕੰਮਕਾਜੀ ਦਿਨਾਂ ਲਈ ਨਿਸ਼ਾਨਬੱਧ ਕਰਦਾ ਹਾਂ।", "আপনি কারও হয়েও পূরণ করে দিতে পারেন — তাঁর কার্ড খুলে যেসব দিন কাজ করতে পারবেন ঠিক করুন। আমি জর্ডনকে সপ্তাহের কর্মদিবসের জন্য চিহ্নিত করছি।", "ويمكنك أيضًا تعبئته نيابة عن شخص — افتح بطاقته وحدّد الأيام التي يستطيع العمل فيها. سأحدد جوردان لأيام الأسبوع.", "Também pode preenchê-la por alguém — abra o cartão da pessoa e defina os dias em que pode trabalhar. Vou marcar o Jordan para os dias úteis.", "También puedes rellenarla por alguien: abre su tarjeta y fija los días que puede trabajar. Marcaré a Jordan para los días laborables.", "Vous pouvez aussi le renseigner à la place de quelqu’un — ouvrez sa fiche et réglez les jours où il peut travailler. Je marque Jordan en semaine.", "Gallwch hefyd ei lenwi ar ran rhywun — agorwch eu cerdyn a gosodwch y diwrnodau y gallant weithio. Marciaf Jordan fel dyddiau’r wythnos."],
  "lt_schedule_s9": ["When the week's ready, Publish sends every assigned person their shifts — by email or push, whichever you set — and locks them in.", "Gdy tydzień jest gotowy, Opublikuj wysyła każdej przypisanej osobie jej zmiany — e-mailem lub powiadomieniem push, jak ustawisz — i je zatwierdza.", "Când săptămâna e gata, Publică trimite fiecărei persoane alocate turele ei — prin e-mail sau notificare push, cum ai setat — și le blochează.", "جب ہفتہ تیار ہو تو شائع کریں ہر تفویض شدہ شخص کو اس کی شفٹیں بھیج دیتا ہے — ای میل یا پش سے، جو آپ نے سیٹ کیا ہو — اور انہیں پکا کر دیتا ہے۔", "ਜਦੋਂ ਹਫ਼ਤਾ ਤਿਆਰ ਹੋਵੇ, ਪ੍ਰਕਾਸ਼ਿਤ ਕਰੋ ਹਰ ਸੌਂਪੇ ਗਏ ਵਿਅਕਤੀ ਨੂੰ ਉਸ ਦੀਆਂ ਸ਼ਿਫ਼ਟਾਂ ਭੇਜ ਦਿੰਦਾ ਹੈ — ਈਮੇਲ ਜਾਂ ਪੁਸ਼ ਰਾਹੀਂ, ਜੋ ਵੀ ਤੁਸੀਂ ਸੈੱਟ ਕੀਤਾ ਹੈ — ਅਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਪੱਕਾ ਕਰ ਦਿੰਦਾ ਹੈ।", "সপ্তাহ প্রস্তুত হলে প্রকাশ করুন প্রতিটি বরাদ্দকৃত ব্যক্তিকে তাঁর শিফট পাঠিয়ে দেয় — ইমেইল বা পুশে, যেটা ঠিক করেছেন — আর সেগুলো চূড়ান্ত করে দেয়।", "عندما يصبح الأسبوع جاهزًا، يرسل نشر لكل شخص معيَّن ورديّاته — عبر البريد الإلكتروني أو الإشعار الفوري، حسب ما حددت — ويثبّتها.", "Quando a semana estiver pronta, Publicar envia a cada pessoa atribuída os seus turnos — por e-mail ou notificação, conforme definiu — e fixa-os.", "Cuando la semana está lista, Publicar envía a cada persona asignada sus turnos, por correo o notificación push, según lo que hayas configurado, y los deja cerrados.", "Quand la semaine est prête, Publier envoie à chaque personne affectée ses créneaux — par e-mail ou notification push, selon votre réglage — et les verrouille.", "Pan fydd yr wythnos yn barod, mae Cyhoeddi yn anfon eu shifftiau at bob person a neilltuwyd — drwy e-bost neu hysbysiad gwthio, pa un bynnag a osodoch — ac yn eu cloi."],
  "lt_schedule_s10": ["And the Settings tab tunes the lot: publish alerts, shift reminders, the check-in grace and availability auto-chasing.", "A zakładka Ustawienia dopracowuje wszystko: alerty o publikacji, przypomnienia o zmianach, tolerancję przy odbiciu obecności i automatyczne przypominanie o dostępności.", "Iar fila Setări reglează totul: alertele de publicare, mementourile de tură, toleranța la check-in și urmărirea automată a disponibilității.", "اور سیٹنگز ٹیب سب کچھ ترتیب دیتا ہے: اشاعت کے الرٹس، شفٹ کی یاد دہانیاں، چیک اِن کی رعایتی مہلت اور دستیابی کا خودکار تقاضا۔", "ਅਤੇ ਸੈਟਿੰਗਾਂ ਟੈਬ ਸਭ ਕੁਝ ਠੀਕ ਕਰਦੀ ਹੈ: ਪ੍ਰਕਾਸ਼ਨ ਅਲਰਟ, ਸ਼ਿਫ਼ਟ ਯਾਦ-ਦਹਾਨੀਆਂ, ਚੈੱਕ-ਇਨ ਦੀ ਰਿਆਇਤੀ ਮਿਆਦ ਅਤੇ ਉਪਲਬਧਤਾ ਦੀ ਆਪਣੇ ਆਪ ਪੁੱਛ-ਗਿੱਛ।", "আর সেটিংস ট্যাব সব কিছু ঠিকঠাক করে: প্রকাশের সতর্কতা, শিফট অনুস্মারক, চেক-ইনের ছাড়ের সময় ও উপস্থিতির সময়ের স্বয়ংক্রিয় তাগাদা।", "وتضبط علامة تبويب الإعدادات كل شيء: تنبيهات النشر وتذكيرات الورديات ومهلة تسجيل الحضور والمتابعة التلقائية للتوفر.", "E o separador Definições ajusta tudo: alertas de publicação, lembretes de turno, tolerância no registo de entrada e acompanhamento automático da disponibilidade.", "Y la pestaña Ajustes lo afina todo: avisos de publicación, recordatorios de turno, margen de fichaje y reclamo automático de disponibilidad.", "Et l’onglet Réglages affine le tout : alertes de publication, rappels de créneau, délai de grâce à l’arrivée et relance automatique des disponibilités.", "A’r tab Gosodiadau sy’n tiwnio’r cyfan: rhybuddion cyhoeddi, nodiadau atgoffa shifft, y cyfnod gras cofrestru ac erlid argaeledd yn awtomatig."],
  "lt_dash_title": ["Dashboard", "Pulpit", "Panou de control", "ڈیش بورڈ", "ਡੈਸ਼ਬੋਰਡ", "ড্যাশবোর্ড", "لوحة التحكم", "Painel", "Panel", "Tableau de bord", "Dangosfwrdd"],
  "lt_dash_intro": ["This is your dashboard — the first thing you see each morning. Let me walk you through it.", "To Twój pulpit — pierwsza rzecz, którą widzisz każdego ranka. Oprowadzę Cię po nim.", "Acesta este panoul tău de control — primul lucru pe care îl vezi în fiecare dimineață. Te plimb prin el.", "یہ آپ کا ڈیش بورڈ ہے — ہر صبح سب سے پہلے جو آپ دیکھتے ہیں۔ میں آپ کو اس کی سیر کراتا ہوں۔", "ਇਹ ਤੁਹਾਡਾ ਡੈਸ਼ਬੋਰਡ ਹੈ — ਹਰ ਸਵੇਰ ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਜੋ ਤੁਸੀਂ ਦੇਖਦੇ ਹੋ। ਮੈਂ ਤੁਹਾਨੂੰ ਇਸ ਦੀ ਸੈਰ ਕਰਾਉਂਦਾ ਹਾਂ।", "এটি আপনার ড্যাশবোর্ড — প্রতিদিন সকালে প্রথমে যা দেখেন। আমি আপনাকে ঘুরিয়ে দেখাই।", "هذه لوحة التحكم — أول ما تراه كل صباح. دعني آخذك في جولة فيها.", "Este é o seu painel — a primeira coisa que vê todas as manhãs. Deixe-me mostrar-lhe tudo.", "Este es tu panel: lo primero que ves cada mañana. Te lo enseño.", "Voici votre tableau de bord — la première chose que vous voyez chaque matin. Je vous le fais visiter.", "Dyma’ch dangosfwrdd — y peth cyntaf a welwch bob bore. Gadewch i mi fynd â chi drwyddo."],
  "lt_dash_done": ["That's your dashboard — who's in today, what's filling, what's owed, and what needs doing, all in one place.", "To Twój pulpit — kto jest dziś, co się zapełnia, co jest należne i co trzeba zrobić, wszystko w jednym miejscu.", "Acesta e panoul tău de control — cine e prezent azi, ce se umple, ce se datorează și ce trebuie făcut, toate într-un singur loc.", "یہ آپ کا ڈیش بورڈ ہے — آج کون آیا ہے، کیا بھر رہا ہے، کیا واجب ہے اور کیا کرنا ہے، سب ایک جگہ۔", "ਇਹ ਤੁਹਾਡਾ ਡੈਸ਼ਬੋਰਡ ਹੈ — ਅੱਜ ਕੌਣ ਆਇਆ ਹੈ, ਕੀ ਭਰ ਰਿਹਾ ਹੈ, ਕੀ ਬਕਾਇਆ ਹੈ, ਅਤੇ ਕੀ ਕਰਨਾ ਹੈ, ਸਭ ਇੱਕੋ ਥਾਂ।", "এই হলো আপনার ড্যাশবোর্ড — আজ কে আছে, কী ভরছে, কী বকেয়া, আর কী করতে হবে, সব এক জায়গায়।", "هذه هي لوحة التحكم — من حضر اليوم، وما الذي يمتلئ، وما المستحق، وما الذي يحتاج إلى عمل، كل ذلك في مكان واحد.", "Este é o seu painel — quem está hoje, o que está a encher, o que é devido e o que há a fazer, tudo num só lugar.", "Este es tu panel: quién está hoy, qué se está llenando, qué se debe y qué hay que hacer, todo en un solo lugar.", "Voilà votre tableau de bord — qui est présent aujourd’hui, ce qui se remplit, ce qui est dû et ce qu’il y a à faire, le tout au même endroit.", "Dyna’ch dangosfwrdd — pwy sydd i mewn heddiw, beth sy’n llenwi, beth sy’n ddyledus, a beth sydd angen ei wneud, i gyd mewn un lle."],
  "lt_dash_s0": ["Right at the top, you can see how many children are on site today and how many sessions are running — your day at a glance.", "Na samej górze widzisz, ile dzieci jest dziś na miejscu i ile sesji trwa — Twój dzień w skrócie.", "Chiar sus vezi câți copii sunt azi la fața locului și câte sesiuni se desfășoară — ziua ta dintr-o privire.", "سب سے اوپر آپ دیکھتے ہیں کہ آج کتنے بچے موجود ہیں اور کتنے سیشن چل رہے ہیں — آپ کا دن ایک نظر میں۔", "ਬਿਲਕੁਲ ਉੱਪਰ ਤੁਸੀਂ ਦੇਖਦੇ ਹੋ ਕਿ ਅੱਜ ਕਿੰਨੇ ਬੱਚੇ ਮੌਕੇ ਉੱਤੇ ਹਨ ਅਤੇ ਕਿੰਨੇ ਸੈਸ਼ਨ ਚੱਲ ਰਹੇ ਹਨ — ਤੁਹਾਡਾ ਦਿਨ ਇੱਕ ਨਜ਼ਰ ਵਿੱਚ।", "একদম উপরে দেখতে পান আজ কতজন শিশু সাইটে আছে আর কতগুলো সেশন চলছে — আপনার দিন এক নজরে।", "في الأعلى ترى كم طفلًا في الموقع اليوم وكم جلسة جارية — يومك في لمحة.", "No topo vê quantas crianças estão hoje no local e quantas sessões estão a decorrer — o seu dia num relance.", "Arriba ves cuántos niños hay hoy en el centro y cuántas sesiones están en marcha: tu día de un vistazo.", "Tout en haut, vous voyez combien d’enfants sont sur place aujourd’hui et combien de séances sont en cours — votre journée en un coup d’œil.", "Reit ar y brig gallwch weld faint o blant sydd ar y safle heddiw a faint o sesiynau sy’n rhedeg — eich diwrnod ar un olwg."],
  "lt_dash_s1": ["These four tiles are your pulse. New bookings shows how many came in over the last five weeks, with a little bar for each week.", "Te cztery kafelki to Twój puls. Nowe rezerwacje pokazują, ile wpłynęło w ostatnich pięciu tygodniach, z małym słupkiem dla każdego tygodnia.", "Aceste patru casete sunt pulsul tău. Rezervările noi arată câte au intrat în ultimele cinci săptămâni, cu o mică bară pentru fiecare săptămână.", "یہ چار ٹائلیں آپ کی نبض ہیں۔ نئی بکنگز دکھاتی ہیں کہ پچھلے پانچ ہفتوں میں کتنی آئیں، ہر ہفتے کے لیے ایک چھوٹے بار کے ساتھ۔", "ਇਹ ਚਾਰ ਟਾਈਲਾਂ ਤੁਹਾਡੀ ਨਬਜ਼ ਹਨ। ਨਵੀਆਂ ਬੁਕਿੰਗਾਂ ਦਿਖਾਉਂਦੀਆਂ ਹਨ ਕਿ ਪਿਛਲੇ ਪੰਜ ਹਫ਼ਤਿਆਂ ਵਿੱਚ ਕਿੰਨੀਆਂ ਆਈਆਂ, ਹਰ ਹਫ਼ਤੇ ਲਈ ਇੱਕ ਛੋਟੇ ਬਾਰ ਨਾਲ।", "এই চারটি টাইল আপনার নাড়ি। নতুন বুকিং দেখায় গত পাঁচ সপ্তাহে কতগুলো এসেছে, প্রতি সপ্তাহের জন্য একটি ছোট বারসহ।", "هذه البطاقات الأربع هي نبضك. الحجوزات الجديدة تُظهر كم وصل في آخر خمسة أسابيع، مع عمود صغير لكل أسبوع.", "Estes quatro mosaicos são o seu pulso. Novas reservas mostra quantas entraram nas últimas cinco semanas, com uma pequena barra por semana.", "Estos cuatro mosaicos son tu pulso. Nuevas reservas muestra cuántas entraron en las últimas cinco semanas, con una barrita por semana.", "Ces quatre tuiles sont votre pouls. Nouvelles réservations indique combien sont arrivées ces cinq dernières semaines, avec une petite barre par semaine.", "Y pedair teilsen hyn yw eich curiad. Mae Archebion newydd yn dangos faint ddaeth i mewn dros y pum wythnos ddiwethaf, gyda bar bach ar gyfer pob wythnos."],
  "lt_dash_s2": ["Spaces left tells you how full your open runs are. The ring shows the percentage filled, so you can see what still needs places selling.", "Wolne miejsca mówią, jak pełne są Twoje otwarte zajęcia. Pierścień pokazuje procent zapełnienia, więc widać, gdzie jeszcze trzeba sprzedać miejsca.", "Locurile rămase îți spun cât de pline sunt seriile deschise. Inelul arată procentul ocupat, așa că vezi ce mai are nevoie de locuri vândute.", "باقی نشستیں بتاتی ہیں کہ آپ کے کھلے رنز کتنے بھر چکے ہیں۔ دائرہ بھرنے کی فیصد دکھاتا ہے، تو آپ دیکھ سکتے ہیں کہ کن کے لیے ابھی جگہیں بیچنی ہیں۔", "ਬਾਕੀ ਥਾਵਾਂ ਦੱਸਦੀਆਂ ਹਨ ਕਿ ਤੁਹਾਡੇ ਖੁੱਲ੍ਹੇ ਰਨ ਕਿੰਨੇ ਭਰੇ ਹਨ। ਗੋਲਾ ਭਰਨ ਦਾ ਪ੍ਰਤੀਸ਼ਤ ਦਿਖਾਉਂਦਾ ਹੈ, ਤਾਂ ਜੋ ਤੁਸੀਂ ਦੇਖ ਸਕੋ ਕਿਨ੍ਹਾਂ ਲਈ ਅਜੇ ਥਾਵਾਂ ਵੇਚਣੀਆਂ ਹਨ।", "অবশিষ্ট আসন বলে আপনার খোলা রানগুলো কতটা ভরেছে। রিংটি ভরার শতাংশ দেখায়, তাই বোঝা যায় কোথায় এখনও আসন বিক্রি বাকি।", "تُخبرك الأماكن المتبقية بمدى امتلاء دوراتك المفتوحة. تعرض الحلقة نسبة الامتلاء، فترى ما لا يزال يحتاج إلى بيع أماكن.", "Lugares livres diz-lhe quão cheias estão as suas turmas abertas. O anel mostra a percentagem preenchida, para ver o que ainda precisa de lugares vendidos.", "Plazas libres te dice lo llenas que están tus tandas abiertas. El anillo muestra el porcentaje ocupado, para ver lo que aún necesita vender plazas.", "Places restantes vous dit à quel point vos sessions ouvertes sont remplies. L’anneau montre le pourcentage rempli, pour voir ce qui a encore besoin de places vendues.", "Mae Lleoedd ar ôl yn dweud wrthych pa mor llawn yw eich cyfresi agored. Mae’r cylch yn dangos y ganran sydd wedi’i llenwi, fel y gallwch weld beth sy’n dal angen gwerthu lleoedd."],
  "lt_dash_s3": ["Taken this week is the money collected, after refunds, with the trend across recent weeks underneath.", "Pobrane w tym tygodniu to zebrane pieniądze po zwrotach, z trendem z ostatnich tygodni poniżej.", "Încasat săptămâna aceasta sunt banii colectați, după rambursări, cu tendința ultimelor săptămâni dedesubt.", "اس ہفتے وصول ہوا وہ رقم ہے جو ریفنڈز کے بعد جمع ہوئی، نیچے حالیہ ہفتوں کے رجحان کے ساتھ۔", "ਇਸ ਹਫ਼ਤੇ ਲਿਆ ਗਿਆ ਉਹ ਪੈਸਾ ਹੈ ਜੋ ਰਿਫੰਡਾਂ ਤੋਂ ਬਾਅਦ ਇਕੱਠਾ ਹੋਇਆ, ਹੇਠਾਂ ਹਾਲੀਆ ਹਫ਼ਤਿਆਂ ਦੇ ਰੁਝਾਨ ਨਾਲ।", "এই সপ্তাহে নেওয়া মানে রিফান্ডের পর সংগৃহীত টাকা, নিচে সাম্প্রতিক সপ্তাহগুলোর প্রবণতাসহ।", "المستلم هذا الأسبوع هو المال المحصّل بعد المبالغ المستردة، مع اتجاه الأسابيع الأخيرة تحته.", "Recebido esta semana é o dinheiro cobrado, depois de reembolsos, com a tendência das últimas semanas por baixo.", "Cobrado esta semana es el dinero recaudado, tras los reembolsos, con la tendencia de las últimas semanas debajo.", "Encaissé cette semaine correspond à l’argent collecté, après remboursements, avec la tendance des dernières semaines en dessous.", "Mae Wedi’i gymryd yr wythnos hon yn cyfeirio at yr arian a gasglwyd, ar ôl ad-daliadau, gyda’r duedd dros yr wythnosau diweddar oddi tano."],
  "lt_dash_s4": ["Outstanding is what's still owed — unpaid balances and any vouchers you're waiting on. It turns green when everyone has settled.", "Zaległe to to, co wciąż jest należne — nieopłacone salda i vouchery, na które czekasz. Robi się zielone, gdy wszyscy się rozliczą.", "Restante este ce se mai datorează — solduri neplătite și orice vouchere pe care le aștepți. Devine verde când toată lumea s-a achitat.", "بقایا وہ ہے جو ابھی واجب الادا ہے — غیر ادا شدہ بیلنس اور وہ واؤچرز جن کا آپ انتظار کر رہے ہیں۔ جب سب حساب برابر کر لیں تو یہ سبز ہو جاتا ہے۔", "ਬਕਾਇਆ ਉਹ ਹੈ ਜੋ ਅਜੇ ਦੇਣਾ ਹੈ — ਨਾ-ਅਦਾ ਹੋਏ ਬਕਾਏ ਅਤੇ ਉਹ ਵਾਊਚਰ ਜਿਨ੍ਹਾਂ ਦੀ ਤੁਸੀਂ ਉਡੀਕ ਕਰ ਰਹੇ ਹੋ। ਜਦੋਂ ਸਭ ਨੇ ਹਿਸਾਬ ਚੁਕਤਾ ਕਰ ਲਿਆ ਹੋਵੇ ਤਾਂ ਇਹ ਹਰਾ ਹੋ ਜਾਂਦਾ ਹੈ।", "বকেয়া হলো যা এখনও পাওনা — অপরিশোধিত ব্যালেন্স এবং যেসব ভাউচারের অপেক্ষায় আছেন। সবাই মিটিয়ে দিলে এটি সবুজ হয়ে যায়।", "المستحق هو ما لا يزال مطلوبًا — الأرصدة غير المدفوعة وأي قسائم تنتظرها. يتحول إلى الأخضر عندما يسدد الجميع.", "Em dívida é o que ainda falta pagar — saldos por pagar e quaisquer vales que esteja a aguardar. Fica verde quando todos acertam contas.", "Pendiente es lo que aún se debe: saldos sin pagar y cualquier cupón que estés esperando. Se pone verde cuando todos han pagado.", "Dû est ce qui reste à payer — soldes impayés et bons que vous attendez. Il passe au vert quand tout le monde a réglé.", "Mae Heb ei dalu yn dangos yr hyn sy’n dal yn ddyledus — balansau heb eu talu ac unrhyw dalebau rydych yn aros amdanynt. Mae’n troi’n wyrdd pan fydd pawb wedi setlo."],
  "lt_dash_s5": ["Below, Today lists every session running now, each with its time, how full it is, and anyone waiting on the list.", "Poniżej Dziś wyświetla każdą trwającą teraz sesję — z godziną, stopniem zapełnienia i każdym, kto czeka na liście.", "Mai jos, Azi listează fiecare sesiune care se desfășoară acum, cu ora, cât de plină este și oricine așteaptă pe listă.", "نیچے آج ہر اس سیشن کی فہرست دیتا ہے جو ابھی چل رہا ہے، ہر ایک کے وقت، بھرنے کی سطح اور فہرست میں انتظار کرنے والوں کے ساتھ۔", "ਹੇਠਾਂ ਅੱਜ ਉਹ ਹਰ ਸੈਸ਼ਨ ਸੂਚੀਬੱਧ ਕਰਦਾ ਹੈ ਜੋ ਹੁਣ ਚੱਲ ਰਿਹਾ ਹੈ, ਹਰ ਇੱਕ ਦੇ ਸਮੇਂ, ਕਿੰਨਾ ਭਰਿਆ ਹੈ ਅਤੇ ਸੂਚੀ ਵਿੱਚ ਉਡੀਕ ਕਰ ਰਹੇ ਕਿਸੇ ਵੀ ਵਿਅਕਤੀ ਨਾਲ।", "নিচে আজ এখন চলমান প্রতিটি সেশনের তালিকা দেয়, প্রতিটির সময়, কতটা ভরেছে, আর তালিকায় অপেক্ষারত কেউ থাকলে তাঁদের সঙ্গে।", "في الأسفل يعرض اليوم كل جلسة جارية الآن، مع وقتها ومدى امتلائها وأي شخص ينتظر على القائمة.", "Em baixo, Hoje lista cada sessão a decorrer agora, com a hora, o quão cheia está e quem estiver na lista de espera.", "Debajo, Hoy lista cada sesión en marcha ahora, con su horario, lo llena que está y cualquiera que esté en lista de espera.", "En dessous, Aujourd’hui liste chaque séance en cours, avec son horaire, son taux de remplissage et toute personne en liste d’attente.", "Islaw, mae Heddiw yn rhestru pob sesiwn sy’n rhedeg nawr, gyda’i hamser, pa mor llawn yw hi ac unrhyw un sy’n aros ar y rhestr."],
  "lt_dash_s6": ["Live listings shows your open runs and exactly how many places are left, with a green, amber or red tag you can read at a glance.", "Aktywne oferty pokazują Twoje otwarte zajęcia i dokładnie, ile miejsc zostało, z zieloną, bursztynową lub czerwoną etykietą czytelną na pierwszy rzut oka.", "Ofertele active îți arată seriile deschise și exact câte locuri au mai rămas, cu o etichetă verde, chihlimbar sau roșie pe care o citești dintr-o privire.", "لائیو لسٹنگز آپ کے کھلے رنز اور ٹھیک یہ دکھاتی ہیں کہ کتنی جگہیں باقی ہیں، سبز، عنبری یا سرخ ٹیگ کے ساتھ جو ایک نظر میں پڑھا جا سکتا ہے۔", "ਲਾਈਵ ਲਿਸਟਿੰਗਾਂ ਤੁਹਾਡੇ ਖੁੱਲ੍ਹੇ ਰਨ ਅਤੇ ਬਿਲਕੁਲ ਕਿੰਨੀਆਂ ਥਾਵਾਂ ਬਚੀਆਂ ਹਨ ਦਿਖਾਉਂਦੀਆਂ ਹਨ, ਹਰੇ, ਪੀਲੇ ਜਾਂ ਲਾਲ ਟੈਗ ਨਾਲ ਜੋ ਇੱਕ ਨਜ਼ਰ ਵਿੱਚ ਪੜ੍ਹਿਆ ਜਾ ਸਕਦਾ ਹੈ।", "লাইভ লিস্টিং আপনার খোলা রান ও ঠিক কতগুলো আসন বাকি তা দেখায়, সবুজ, অ্যাম্বার বা লাল ট্যাগসহ যা এক নজরে পড়া যায়।", "تعرض الإعلانات المباشرة دوراتك المفتوحة وعدد الأماكن المتبقية بالضبط، مع وسم أخضر أو كهرماني أو أحمر تقرؤه في لمحة.", "Anúncios ativos mostra as suas turmas abertas e exatamente quantos lugares restam, com uma etiqueta verde, âmbar ou vermelha que se lê num relance.", "Anuncios activos muestra tus tandas abiertas y exactamente cuántas plazas quedan, con una etiqueta verde, ámbar o roja que se lee de un vistazo.", "Annonces actives montre vos sessions ouvertes et exactement combien de places restent, avec une étiquette verte, ambre ou rouge lisible d’un coup d’œil.", "Mae Rhestriadau byw yn dangos eich cyfresi agored a faint yn union o leoedd sydd ar ôl, gyda thag gwyrdd, ambr neu goch y gallwch ei ddarllen ar un olwg."],
  "lt_dash_s7": ["And Tasks today pulls in anything due today from your task manager, so nothing slips through.", "A Zadania na dziś wciąga wszystko, co ma termin dzisiaj z Twojego menedżera zadań, więc nic nie umknie.", "Iar Sarcinile de azi aduce tot ce scade astăzi din managerul tău de sarcini, ca nimic să nu scape.", "اور آج کے کام آپ کے ٹاسک مینیجر سے وہ سب کھینچ لاتا ہے جس کی آج آخری تاریخ ہے، تاکہ کچھ رہ نہ جائے۔", "ਅਤੇ ਅੱਜ ਦੇ ਕੰਮ ਤੁਹਾਡੇ ਕਾਰਜ ਪ੍ਰਬੰਧਕ ਤੋਂ ਉਹ ਸਭ ਖਿੱਚ ਲਿਆਉਂਦਾ ਹੈ ਜਿਸਦੀ ਅੱਜ ਆਖ਼ਰੀ ਤਾਰੀਖ਼ ਹੈ, ਤਾਂ ਜੋ ਕੁਝ ਵੀ ਨਾ ਰਹਿ ਜਾਵੇ।", "আর আজকের কাজ আপনার টাস্ক ম্যানেজার থেকে আজ যা যা শেষ তারিখ তা টেনে আনে, যাতে কিছুই বাদ না পড়ে।", "وتسحب مهام اليوم من مدير المهام كل ما يحين موعده اليوم، فلا يفوتك شيء.", "E Tarefas de hoje traz do seu gestor de tarefas tudo o que termina hoje, para que nada escape.", "Y Tareas de hoy trae de tu gestor de tareas todo lo que vence hoy, para que no se escape nada.", "Et Tâches du jour remonte de votre gestionnaire de tâches tout ce qui est dû aujourd’hui, pour que rien ne passe entre les mailles.", "A Tasgau heddiw yn tynnu i mewn unrhyw beth sy’n ddyledus heddiw o’ch rheolwr tasgau, fel na fydd dim yn llithro drwodd."],
  "lt_dash_s8": ["Scroll on and here's your Business analytics — the bigger picture, worked out from your bookings. Flip between three, six or twelve months up here.", "Przewiń dalej, a zobaczysz Analizę biznesu — szerszy obraz wyliczony z Twoich rezerwacji. Tutaj przełączasz między trzema, sześcioma lub dwunastoma miesiącami.", "Derulează mai jos și iată Analiza afacerii — imaginea de ansamblu, calculată din rezervările tale. Aici comuți între trei, șase sau douăsprezece luni.", "آگے سکرول کریں اور یہ ہے آپ کا بزنس تجزیہ — بڑی تصویر، آپ کی بکنگز سے حساب کی گئی۔ یہاں اوپر تین، چھ یا بارہ مہینوں کے درمیان بدلیں۔", "ਅੱਗੇ ਸਕ੍ਰੋਲ ਕਰੋ ਅਤੇ ਇਹ ਹੈ ਤੁਹਾਡਾ ਕਾਰੋਬਾਰੀ ਵਿਸ਼ਲੇਸ਼ਣ — ਵੱਡੀ ਤਸਵੀਰ, ਤੁਹਾਡੀਆਂ ਬੁਕਿੰਗਾਂ ਤੋਂ ਗਿਣੀ ਗਈ। ਇੱਥੇ ਉੱਪਰ ਤਿੰਨ, ਛੇ ਜਾਂ ਬਾਰਾਂ ਮਹੀਨਿਆਂ ਵਿਚਕਾਰ ਬਦਲੋ।", "আরও স্ক্রল করুন, আর এই যে আপনার ব্যবসার বিশ্লেষণ — বড় চিত্র, আপনার বুকিং থেকে হিসাব করা। এখানে উপরে তিন, ছয় বা বারো মাসের মধ্যে বদলান।", "واصل التمرير وها هو تحليل أعمالك — الصورة الأكبر المحسوبة من حجوزاتك. بدّل هنا في الأعلى بين ثلاثة أو ستة أو اثني عشر شهرًا.", "Continue a deslizar e aqui está a sua Análise do negócio — a visão geral, calculada a partir das suas reservas. Alterne aqui em cima entre três, seis ou doze meses.", "Sigue bajando y aquí está tu Análisis del negocio: el panorama general, calculado a partir de tus reservas. Cambia aquí arriba entre tres, seis o doce meses.", "Continuez à défiler et voici votre Analyse de l’activité — la vue d’ensemble, calculée à partir de vos réservations. Basculez ici en haut entre trois, six ou douze mois.", "Sgroliwch ymlaen a dyma’ch Dadansoddeg busnes — y darlun mwy, wedi’i gyfrifo o’ch archebion. Newidiwch yma ar y brig rhwng tri, chwech neu ddeuddeg mis."],
  "lt_dash_s9": ["These four tiles sum it up — income collected, total bookings, how many families, and your average booking value.", "Te cztery kafelki to podsumowanie — zebrany przychód, łączna liczba rezerwacji, ile rodzin i średnia wartość rezerwacji.", "Aceste patru casete le rezumă — venituri încasate, total rezervări, câte familii și valoarea medie a unei rezervări.", "یہ چار ٹائلیں خلاصہ کرتی ہیں — وصول شدہ آمدن، کل بکنگز، کتنے خاندان، اور آپ کی اوسط بکنگ کی قدر۔", "ਇਹ ਚਾਰ ਟਾਈਲਾਂ ਸਾਰ ਦਿੰਦੀਆਂ ਹਨ — ਇਕੱਠੀ ਹੋਈ ਆਮਦਨ, ਕੁੱਲ ਬੁਕਿੰਗਾਂ, ਕਿੰਨੇ ਪਰਿਵਾਰ, ਅਤੇ ਤੁਹਾਡੀ ਔਸਤ ਬੁਕਿੰਗ ਕੀਮਤ।", "এই চারটি টাইল সারাংশ দেয় — সংগৃহীত আয়, মোট বুকিং, কতগুলো পরিবার, আর আপনার গড় বুকিং মূল্য।", "تلخّص هذه البطاقات الأربع الأمر — الدخل المحصّل وإجمالي الحجوزات وعدد العائلات ومتوسط قيمة الحجز.", "Estes quatro mosaicos resumem tudo — receitas cobradas, total de reservas, quantas famílias e o valor médio da reserva.", "Estos cuatro mosaicos lo resumen: ingresos cobrados, reservas totales, cuántas familias y el valor medio de la reserva.", "Ces quatre tuiles résument tout — revenu encaissé, nombre total de réservations, nombre de familles et valeur moyenne d’une réservation.", "Mae’r pedair teilsen hyn yn ei grynhoi — incwm a gasglwyd, cyfanswm archebion, faint o deuluoedd, a gwerth archeb ar gyfartaledd."],
  "lt_dash_s10": ["Income by month tracks what you've taken, and Booked versus collected sets what parents owe against what's actually landed.", "Przychód według miesięcy pokazuje, ile pobrałeś, a Zarezerwowane a pobrane zestawia to, co rodzice winni, z tym, co faktycznie wpłynęło.", "Venitul pe luni urmărește ce ai încasat, iar Rezervat versus încasat pune față în față ce datorează părinții cu ce a intrat de fapt.", "ماہ بہ ماہ آمدن بتاتی ہے کہ آپ نے کتنا لیا، اور بک شدہ بمقابلہ وصول شدہ وہ رقم جو والدین کے ذمے ہے اس کے مقابل رکھتا ہے جو واقعی پہنچی۔", "ਮਹੀਨੇ ਅਨੁਸਾਰ ਆਮਦਨ ਦੱਸਦੀ ਹੈ ਕਿ ਤੁਸੀਂ ਕਿੰਨਾ ਲਿਆ, ਅਤੇ ਬੁੱਕ ਬਨਾਮ ਇਕੱਠਾ ਉਹ ਰਕਮ ਜੋ ਮਾਪਿਆਂ ਦੇ ਜ਼ਿੰਮੇ ਹੈ ਉਸ ਦੇ ਮੁਕਾਬਲੇ ਰੱਖਦਾ ਹੈ ਜੋ ਸੱਚਮੁੱਚ ਪਹੁੰਚੀ।", "মাসভিত্তিক আয় দেখায় আপনি কত নিয়েছেন, আর বুকড বনাম সংগৃহীত অভিভাবকদের পাওনার সঙ্গে আসলে যা এসেছে তা মেলায়।", "يتتبع الدخل حسب الشهر ما أخذته، ويضع المحجوز مقابل المحصّل ما يدين به أولياء الأمور إلى جانب ما وصل فعلًا.", "Receitas por mês acompanha o que recebeu, e Reservado versus cobrado compara o que os pais devem com o que realmente chegou.", "Ingresos por mes sigue lo que has cobrado, y Reservado frente a cobrado contrapone lo que deben los padres a lo que realmente ha llegado.", "Revenu par mois suit ce que vous avez encaissé, et Réservé par rapport à encaissé met en regard ce que doivent les parents et ce qui est réellement arrivé.", "Mae Incwm yn ôl mis yn olrhain yr hyn a gymeroch, ac mae Archebwyd yn erbyn casglwyd yn gosod yr hyn sy’n ddyledus gan rieni yn erbyn yr hyn sydd wedi glanio mewn gwirionedd."],
  "lt_dash_s11": ["Revenue by activity shows which camps and clubs earn you the most.", "Przychód według zajęć pokazuje, które obozy i zajęcia zarabiają najwięcej.", "Venitul pe activitate arată ce tabere și cluburi îți aduc cel mai mult.", "سرگرمی کے لحاظ سے آمدن دکھاتی ہے کہ کون سے کیمپ اور کلب آپ کو سب سے زیادہ کما کر دیتے ہیں۔", "ਗਤੀਵਿਧੀ ਅਨੁਸਾਰ ਆਮਦਨ ਦਿਖਾਉਂਦੀ ਹੈ ਕਿ ਕਿਹੜੇ ਕੈਂਪ ਅਤੇ ਕਲੱਬ ਤੁਹਾਨੂੰ ਸਭ ਤੋਂ ਵੱਧ ਕਮਾ ਕੇ ਦਿੰਦੇ ਹਨ।", "কার্যক্রমভিত্তিক আয় দেখায় কোন ক্যাম্প ও ক্লাব আপনাকে সবচেয়ে বেশি আয় এনে দেয়।", "يُظهر الدخل حسب النشاط أي المخيمات والنوادي تدرّ عليك أكثر.", "Receitas por atividade mostra que campos e clubes lhe rendem mais.", "Ingresos por actividad muestra qué campamentos y clubes te generan más.", "Revenu par activité montre quels camps et clubs vous rapportent le plus.", "Mae Incwm yn ôl gweithgaredd yn dangos pa wersylloedd a chlybiau sy’n ennill fwyaf i chi."],
  "lt_dash_s12": ["The booking funnel shows how many bookings get confirmed and paid, and Repeat customers how many families come back for more.", "Lejek rezerwacji pokazuje, ile rezerwacji zostaje potwierdzonych i opłaconych, a Stali klienci — ile rodzin wraca po więcej.", "Pâlnia de rezervări arată câte rezervări sunt confirmate și plătite, iar Clienții fideli — câte familii revin pentru mai mult.", "بکنگ کا فنل دکھاتا ہے کہ کتنی بکنگز تصدیق شدہ اور ادا شدہ ہوتی ہیں، اور دوبارہ آنے والے صارفین کہ کتنے خاندان مزید کے لیے واپس آتے ہیں۔", "ਬੁਕਿੰਗ ਫਨਲ ਦਿਖਾਉਂਦਾ ਹੈ ਕਿ ਕਿੰਨੀਆਂ ਬੁਕਿੰਗਾਂ ਪੁਸ਼ਟੀ ਅਤੇ ਅਦਾ ਹੁੰਦੀਆਂ ਹਨ, ਅਤੇ ਦੁਹਰਾਉਣ ਵਾਲੇ ਗਾਹਕ ਕਿ ਕਿੰਨੇ ਪਰਿਵਾਰ ਹੋਰ ਲਈ ਵਾਪਸ ਆਉਂਦੇ ਹਨ।", "বুকিং ফানেল দেখায় কতগুলো বুকিং নিশ্চিত ও পরিশোধিত হয়, আর পুনরাবৃত্ত গ্রাহক দেখায় কতগুলো পরিবার আরও বুক করতে ফিরে আসে।", "يُظهر مسار الحجوزات كم حجزًا يتأكد ويُدفع، ويُظهر العملاء المتكررون كم عائلة تعود للمزيد.", "O funil de reservas mostra quantas reservas são confirmadas e pagas, e Clientes recorrentes quantas famílias voltam para mais.", "El embudo de reservas muestra cuántas reservas se confirman y se pagan, y Clientes recurrentes cuántas familias vuelven a por más.", "L’entonnoir de réservations montre combien de réservations sont confirmées et payées, et Clients fidèles combien de familles reviennent.", "Mae’r twndis archebu yn dangos faint o archebion sy’n cael eu cadarnhau a’u talu, a Chwsmeriaid dychwel faint o deuluoedd sy’n dod yn ôl am fwy."],
  "lt_dash_s13": ["Bookings and payments breaks things down by status and how people pay, and Newest bookings lists the latest to land.", "Rezerwacje i płatności dzielą wszystko według statusu i sposobu płacenia, a Najnowsze rezerwacje wymienia te, które właśnie wpłynęły.", "Rezervările și plățile împart totul după stare și modul de plată, iar Cele mai noi rezervări le listează pe ultimele sosite.", "بکنگز اور ادائیگیاں سب کچھ حالت اور لوگوں کے ادائیگی کے طریقے کے لحاظ سے تقسیم کرتی ہیں، اور تازہ ترین بکنگز حال ہی میں آنے والی بکنگز درج کرتی ہے۔", "ਬੁਕਿੰਗਾਂ ਅਤੇ ਭੁਗਤਾਨ ਸਭ ਕੁਝ ਸਥਿਤੀ ਅਤੇ ਲੋਕਾਂ ਦੇ ਭੁਗਤਾਨ ਦੇ ਤਰੀਕੇ ਅਨੁਸਾਰ ਵੰਡਦੇ ਹਨ, ਅਤੇ ਨਵੀਨਤਮ ਬੁਕਿੰਗਾਂ ਹਾਲ ਹੀ ਵਿੱਚ ਆਈਆਂ ਬੁਕਿੰਗਾਂ ਸੂਚੀਬੱਧ ਕਰਦੀਆਂ ਹਨ।", "বুকিং ও পেমেন্ট সবকিছুকে স্ট্যাটাস ও পরিশোধের ধরন অনুযায়ী ভাগ করে, আর নতুনতম বুকিং সদ্য আসাগুলো তালিকাভুক্ত করে।", "تقسّم الحجوزات والمدفوعات الأمور حسب الحالة وطريقة الدفع، وتسرد أحدث الحجوزات آخر ما وصل.", "Reservas e pagamentos divide tudo por estado e forma de pagamento, e Reservas mais recentes lista as últimas a chegar.", "Reservas y pagos lo desglosa por estado y forma de pago, y Reservas más recientes lista las últimas que han llegado.", "Réservations et paiements répartit le tout par statut et mode de paiement, et Dernières réservations liste les plus récentes.", "Mae Archebion a thaliadau yn dadansoddi pethau yn ôl statws a sut mae pobl yn talu, ac mae Archebion diweddaraf yn rhestru’r rhai diweddaraf i lanio."],
};
